create temporary table _tex_units on commit drop as
select * from jsonb_to_recordset($units$[{"slide_number":1,"block_number":0,"lesson_ordinal":1,"segment_position":1,"segment_id":"6f6ddfce-a63f-5954-8b1f-0c8ec4216812","slide_id":"30b2e7c7-c40a-593a-91aa-556e9c0053a8","note_id":"42caebac-d840-5e17-9def-e375a7426887","title":"INMÍNERCAMPUS · TÉCNICOS DE EXTERIOR","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es abrir el curso situando al técnico como la persona que conecta planificación, producción y prevención.\n\nLa función del técnico titulado combina anticipación y presencia en campo. Anticipar significa diseñar secuencias, viales, zonas de exclusión, recursos y controles antes de movilizar equipos. Estar presente significa comprobar que el terreno, las máquinas y las personas siguen dentro de lo previsto. La supervisión pierde eficacia cuando se limita a firmar documentos después del trabajo o a corregir conductas sin revisar las causas de diseño y organización.\n\nPensemos en un ejemplo. Imagine el inicio de un turno tras una noche de lluvia. La producción quiere arrancar, pero antes alguien debe comprobar pistas, frentes, drenajes, máquinas y coordinación. Esa mirada global es la función técnica.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Anticipar, supervisar y poder parar son tres partes de una misma responsabilidad.","duration_seconds":137,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-001.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-001.jpg","explanation":"Objetivo\n\nAbrir el curso situando al técnico como la persona que conecta planificación, producción y prevención.\n\nExplicación detallada\n\nLa función del técnico titulado combina anticipación y presencia en campo. Anticipar significa diseñar secuencias, viales, zonas de exclusión, recursos y controles antes de movilizar equipos. Estar presente significa comprobar que el terreno, las máquinas y las personas siguen dentro de lo previsto. La supervisión pierde eficacia cuando se limita a firmar documentos después del trabajo o a corregir conductas sin revisar las causas de diseño y organización. Una buena decisión técnica responde, como mínimo, a cinco preguntas: qué puede causar daño; quién o qué puede quedar expuesto; qué barreras impiden el suceso; cómo se sabe que esas barreras funcionan; y quién tiene autoridad para parar o reanudar. La respuesta se apoya en evidencias observables: inspecciones, mediciones, registros de mantenimiento, comunicaciones, permisos y comprobaciones de campo.\n\nLa seguridad en una explotación exterior no se consigue acumulando normas, sino convirtiendo el proyecto y la evaluación de riesgos en condiciones de trabajo verificables. El técnico conecta diseño, producción, mantenimiento, contratas y respuesta ante cambios.\n\nLectura guiada de la diapositiva\n\nANTICIPAR, SUPERVISAR Y PODER PARAR Anticipar exige diseñar secuencias, viales, zonas de exclusión y recursos antes de movilizar equipos. Estar en campo permite comprobar que terreno, máquinas y personas siguen dentro de lo previsto. Supervisar pierde eficacia si se limita a firmar después o a corregir conductas sin revisar causas de diseño y organización. Cinco preguntas de toda decisión Qué puede causar daño y quién queda expuesto. Qué barreras lo impiden y cómo sabemos que funcionan. Quién puede parar o reanudar. La decisión se apoya en inspecciones, mediciones, registros, comunicaciones y permisos.\n\nAplicación práctica\n\nImagine el inicio de un turno tras una noche de lluvia. La producción quiere arrancar, pero antes alguien debe comprobar pistas, frentes, drenajes, máquinas y coordinación. Esa mirada global es la función técnica.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nAnticipar, supervisar y poder parar son tres partes de una misma responsabilidad.","key_points":["Abrir el curso situando al técnico como la persona que conecta planificación, producción y prevención.","Anticipar, supervisar y poder parar son tres partes de una misma responsabilidad."],"stop_criterion":"Anticipar, supervisar y poder parar son tres partes de una misma responsabilidad.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":2,"block_number":0,"lesson_ordinal":1,"segment_position":2,"segment_id":"29458bdb-9000-5cea-a960-300f4f734800","slide_id":"dff9b020-3e08-5ba2-a6ed-1a06f4339f97","note_id":"e8f7158c-bffe-5d10-bc53-2c1ab261d7bc","title":"DE PELIGRO A EVIDENCIA","narration_text":"Esta diapositiva propone mirar el trabajo con criterio técnico y no por costumbre. Nuestro objetivo es distinguir peligro, exposición, riesgo, control, verificación y evidencia sin tratarlos como sinónimos.\n\nResultados de aprendizaje. Distinguir peligro, riesgo, control, verificación y evidencia. Explicar la relación entre proyecto de explotación, DSS, DIS, procedimientos e instrucciones. Aplicar una jerarquía de controles antes de recurrir al EPI. Reconocer cuándo una variación obliga a detener, reevaluar y autorizar de nuevo.\n\nPensemos en un ejemplo. Una roca inestable es un peligro. Un equipo que trabaja bajo su trayectoria crea exposición. La combinación determina el riesgo. La exclusión controla la exposición y una inspección registrada demuestra que la barrera existe.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Un control no está implantado hasta que puede verificarse y dejar evidencia.","duration_seconds":134,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-002.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-002.jpg","explanation":"Objetivo\n\nDistinguir peligro, exposición, riesgo, control, verificación y evidencia sin tratarlos como sinónimos.\n\nExplicación detallada\n\nResultados de aprendizaje. Distinguir peligro, riesgo, control, verificación y evidencia. Explicar la relación entre proyecto de explotación, DSS, DIS, procedimientos e instrucciones. Aplicar una jerarquía de controles antes de recurrir al EPI. Reconocer cuándo una variación obliga a detener, reevaluar y autorizar de nuevo.\n\nLa función del técnico titulado combina anticipación y presencia en campo. Anticipar significa diseñar secuencias, viales, zonas de exclusión, recursos y controles antes de movilizar equipos. Estar presente significa comprobar que el terreno, las máquinas y las personas siguen dentro de lo previsto. La supervisión pierde eficacia cuando se limita a firmar documentos después del trabajo o a corregir conductas sin revisar las causas de diseño y organización. Una buena decisión técnica responde, como mínimo, a cinco preguntas: qué puede causar daño; quién o qué puede quedar expuesto; qué barreras impiden el suceso; cómo se sabe que esas barreras funcionan; y quién tiene autoridad para parar o reanudar. La respuesta se apoya en evidencias observables: inspecciones, mediciones, registros de mantenimiento, comunicaciones, permisos y comprobaciones de campo.\n\nLectura guiada de la diapositiva\n\nPeligro Exposición Riesgo Fuente o situación con capacidad Presencia dentro de la Probabilidad y consecuencia, de causar daño. trayectoria del peligro. considerando exposición y controles. Control Verificación Evidencia Barrera que impide el suceso. Prueba de que la barrera Inspección, medición, registro de funciona. mantenimiento, comunicación o permiso.\n\nAplicación práctica\n\nUna roca inestable es un peligro. Un equipo que trabaja bajo su trayectoria crea exposición. La combinación determina el riesgo. La exclusión controla la exposición y una inspección registrada demuestra que la barrera existe.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUn control no está implantado hasta que puede verificarse y dejar evidencia.","key_points":["Distinguir peligro, exposición, riesgo, control, verificación y evidencia sin tratarlos como sinónimos.","Un control no está implantado hasta que puede verificarse y dejar evidencia."],"stop_criterion":"Un control no está implantado hasta que puede verificarse y dejar evidencia.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":3,"block_number":0,"lesson_ordinal":1,"segment_position":3,"segment_id":"b15354d4-2888-5b45-a4b3-8f9c2915d283","slide_id":"0d65976b-acfe-583e-a909-aa1a3f4146e6","note_id":"1761379c-6ea3-527a-bafa-9eb04a116f94","title":"ARQUITECTURA DOCUMENTAL DE LA EXPLOTACIÓN","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es explicar para qué sirve cada documento de la explotación y evitar usar uno como sustituto de otro.\n\nAlcance y reglas de uso. El manual sirve de soporte al curso inicial presencial de 20 horas. La formación reglada de la ITC 02.1.02 debe impartirse de forma presencial; el estudio autónomo, las diapositivas y los futuros audios son apoyo, no sustitución de las horas obligatorias. Las dimensiones, límites y reglas de la explotación deben comprobarse siempre contra el proyecto aprobado, las disposiciones internas de seguridad y la evaluación actualizada. Este manual no autoriza desviaciones. Las operaciones con explosivos corresponden al personal habilitado y al marco específico del Reglamento de Explosivos.\n\nPensemos en un ejemplo. Un procedimiento de mantenimiento puede ser impecable y, aun así, resultar inseguro si contradice la geometría aprobada, el Documento sobre Seguridad y Salud o una disposición interna de seguridad.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Cada documento responde a una pregunta distinta y debe ser coherente con los de nivel superior.","duration_seconds":123,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-003.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-003.jpg","explanation":"Objetivo\n\nExplicar para qué sirve cada documento de la explotación y evitar usar uno como sustituto de otro.\n\nExplicación detallada\n\nAlcance y reglas de uso. El manual sirve de soporte al curso inicial presencial de 20 horas. La formación reglada de la ITC 02.1.02 debe impartirse de forma presencial; el estudio autónomo, las diapositivas y los futuros audios son apoyo, no sustitución de las horas obligatorias. Las dimensiones, límites y reglas de la explotación deben comprobarse siempre contra el proyecto aprobado, las disposiciones internas de seguridad y la evaluación actualizada. Este manual no autoriza desviaciones. Las operaciones con explosivos corresponden al personal habilitado y al marco específico del Reglamento de Explosivos. El técnico formado con este curso coordina, delimita interferencias y verifica condiciones; no adquiere por ello la condición de artillero. Cuando cambien el terreno, el agua, el método, la secuencia, el equipo, la organización o el entorno, debe revisarse el riesgo antes de continuar. Regla de prevalencia. Ante cualquier diferencia, prevalecen la legislación vigente, las condiciones impuestas por la autoridad minera, el proyecto aprobado, el Documento sobre Seguridad y Salud, las disposiciones internas de seguridad y las instrucciones del fabricante.\n\nLectura guiada de la diapositiva\n\nProyecto de explotación Define método, geometría, fases, equipos, escombreras y drenaje. Documento sobre Seguridad y Salud (Documento sobre Seguridad y Salud) Integra organización preventiva, evaluación, medidas, emergencias, coordinación y seguimiento. Disposición Interna de Seguridad (disposición interna de seguridad) Concreta tráfico, mantenimiento, defectos, señalización, inspecciones y trabajos especiales. Prevalencia: legislación, autoridad minera, proyecto, Documento sobre Seguridad y Salud, disposición interna de seguridad e instrucciones del fabricante.\n\nAplicación práctica\n\nUn procedimiento de mantenimiento puede ser impecable y, aun así, resultar inseguro si contradice la geometría aprobada, el Documento sobre Seguridad y Salud o una disposición interna de seguridad.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nCada documento responde a una pregunta distinta y debe ser coherente con los de nivel superior.","key_points":["Explicar para qué sirve cada documento de la explotación y evitar usar uno como sustituto de otro.","Cada documento responde a una pregunta distinta y debe ser coherente con los de nivel superior."],"stop_criterion":"Cada documento responde a una pregunta distinta y debe ser coherente con los de nivel superior.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":4,"block_number":0,"lesson_ordinal":1,"segment_position":4,"segment_id":"339a0a17-fb64-53ef-9429-61790bb13492","slide_id":"1bcc70bb-11f0-54da-8bb1-f7662cc31e5e","note_id":"7d129d93-78a7-52c6-b949-80d1d09f42da","title":"PROCEDIMIENTOS, INSTRUCCIONES Y PERMISOS","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es diferenciar procedimiento, instrucción y permiso de trabajo por su función práctica.\n\nCómo trabajar con el manual 1. Antes de cada bloque, lea los resultados de aprendizaje y relacione cada uno con una tarea real de su explotación. 2. Durante la explicación, anote qué documento del centro concreta cada criterio: proyecto, DSS, DIS, plan de tráfico, procedimiento, permiso o instrucción. 3. Resuelva las actividades con datos del centro. Una respuesta general no sustituye una decisión basada en el terreno y en la máquina reales. 4. Utilice las listas de comprobación para aprender el orden de una inspección, pero no las implante sin validarlas para el centro. 5.\n\nPensemos en un ejemplo. Para intervenir una trituradora puede existir un procedimiento general, una instrucción de consignación paso a paso y un permiso que autorice esa intervención concreta, con responsables, hora y condiciones.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: El documento correcto debe llegar a la persona correcta antes de iniciar la tarea.","duration_seconds":122,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-004.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-004.jpg","explanation":"Objetivo\n\nDiferenciar procedimiento, instrucción y permiso de trabajo por su función práctica.\n\nExplicación detallada\n\nCómo trabajar con el manual 1. Antes de cada bloque, lea los resultados de aprendizaje y relacione cada uno con una tarea real de su explotación. 2. Durante la explicación, anote qué documento del centro concreta cada criterio: proyecto, DSS, DIS, plan de tráfico, procedimiento, permiso o instrucción. 3. Resuelva las actividades con datos del centro. Una respuesta general no sustituye una decisión basada en el terreno y en la máquina reales. 4. Utilice las listas de comprobación para aprender el orden de una inspección, pero no las implante sin validarlas para el centro. 5. Cierre cada bloque identificando una condición de parada, una verificación crítica y una evidencia que deba quedar registrada.\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLectura guiada de la diapositiva\n\nProcedimiento Instrucción Permiso Secuencia, responsables, Pasos operativos, Determina quién acepta una condiciones previas, puntos de prohibiciones, comunicaciones tarea no rutinaria o de alto parada y registros. y anomalías. riesgo. La consignación, la electricidad, la altura, el izado o una intervención especial pueden requerir permiso. Cada documento responde a una pregunta distinta y se concreta en el centro.\n\nAplicación práctica\n\nPara intervenir una trituradora puede existir un procedimiento general, una instrucción de consignación paso a paso y un permiso que autorice esa intervención concreta, con responsables, hora y condiciones.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl documento correcto debe llegar a la persona correcta antes de iniciar la tarea.","key_points":["Diferenciar procedimiento, instrucción y permiso de trabajo por su función práctica.","El documento correcto debe llegar a la persona correcta antes de iniciar la tarea."],"stop_criterion":"El documento correcto debe llegar a la persona correcta antes de iniciar la tarea.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":5,"block_number":0,"lesson_ordinal":1,"segment_position":5,"segment_id":"cd4360e3-e65c-570d-8a41-57d7b196d456","slide_id":"509a8f3a-3047-539a-a769-0d31d4edf84e","note_id":"e0cfa63d-ac5b-5aa7-b5dc-111de61121e1","title":"JERARQUÍA DE CONTROLES","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es aplicar la jerarquía de controles priorizando diseño y eliminación de exposición.\n\nLos controles se seleccionan de arriba abajo. Eliminar la exposición o cambiar el diseño ofrece más fiabilidad que depender de que una persona recuerde una regla. Cuando una medida de orden inferior sea necesaria, debe integrarse en un conjunto de barreras y verificarse.\n\nPensemos en un ejemplo. Si peatones y volquetes comparten una zona, repartir chalecos no elimina la interacción. Rediseñar el recorrido, separar físicamente o suprimir el cruce reduce la dependencia de la conducta.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Cuanto más depende una barrera de recordar y obedecer, menos robusta es.","duration_seconds":122,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-005.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-005.jpg","explanation":"Objetivo\n\nAplicar la jerarquía de controles priorizando diseño y eliminación de exposición.\n\nExplicación detallada\n\nLos controles se seleccionan de arriba abajo. Eliminar la exposición o cambiar el diseño ofrece más fiabilidad que depender de que una persona recuerde una regla. Cuando una medida de orden inferior sea necesaria, debe integrarse en un conjunto de barreras y verificarse.\n\nLectura guiada de la diapositiva\n\nCONTROL APLICACIÓN VERIFICACIÓN Eliminar Reubicar un tránsito para que no cruce la zona ¿Ha desaparecido la interacción? de carga. Sustituir Método que genere menos polvo o proyección. ¿El residual es menor y no crea otro? Ingeniería Barrera, drenaje, ROPS, captación o ¿Está dimensionada, mantenida y probada? enclavamiento. Organización Plan de tráfico, permiso, vigía. ¿La regla es clara y supervisada? equipo de protección individual Casco, gafas, protección auditiva o respiratoria. ¿Es adecuado, compatible, ajustado y usado?\n\nAplicación práctica\n\nSi peatones y volquetes comparten una zona, repartir chalecos no elimina la interacción. Rediseñar el recorrido, separar físicamente o suprimir el cruce reduce la dependencia de la conducta.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nCuanto más depende una barrera de recordar y obedecer, menos robusta es.","key_points":["Aplicar la jerarquía de controles priorizando diseño y eliminación de exposición.","Cuanto más depende una barrera de recordar y obedecer, menos robusta es."],"stop_criterion":"Cuanto más depende una barrera de recordar y obedecer, menos robusta es.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":6,"block_number":0,"lesson_ordinal":1,"segment_position":6,"segment_id":"bd7cc7ef-d449-5dab-a390-873e4e2eeb1b","slide_id":"b810f5cb-1ae1-50c8-8b88-544d916e74f4","note_id":"042d3258-ae64-5254-baf5-3b6179bf4863","title":"GESTIÓN DEL CAMBIO: ANTES DE SEGUIR TRABAJANDO","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es activar la gestión del cambio antes de continuar cuando varían terreno, agua, equipo, método u organización.\n\nUna explotación es dinámica. El avance modifica caras libres, bancos, distancias, drenajes, visibilidad, firme, radios de giro y trayectorias. Un control que era suficiente puede dejar de serlo después de una voladura, lluvia o entrada de un equipo mayor. La gestión del cambio se activa antes de seguir trabajando.\n\nPensemos en un ejemplo. Una motoniveladora cambia una pendiente transversal; una lluvia revela que el agua ya no evacua; aparece barro en una curva y cambia la trayectoria de los camiones. El cambio aparentemente pequeño ha modificado el riesgo.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Cambiar primero y evaluar después invierte el orden preventivo.","duration_seconds":130,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-006.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-006.jpg","explanation":"Objetivo\n\nActivar la gestión del cambio antes de continuar cuando varían terreno, agua, equipo, método u organización.\n\nExplicación detallada\n\nUna explotación es dinámica. El avance modifica caras libres, bancos, distancias, drenajes, visibilidad, firme, radios de giro y trayectorias. Un control que era suficiente puede dejar de serlo después de una voladura, lluvia o entrada de un equipo mayor. La gestión del cambio se activa antes de seguir trabajando.\n\nLectura guiada de la diapositiva\n\nTerreno o geología Agua o meteorología Equipo o implemento Estabilidad, discontinuidades, Escorrentías, erosión, blandones, Dimensiones, masa, alcance, caída de rocas, drenaje y visibilidad y adherencia. frenado, visibilidad y formación. exclusión. Secuencia o producción Personal o empresa Entorno Interacciones, simultaneidad y Competencia, acogida, Líneas, carreteras, terceros y comunicación. coordinación de actividades vibraciones. empresariales (CAE) y autorizaciones.\n\nAplicación práctica\n\nUna motoniveladora cambia una pendiente transversal; una lluvia revela que el agua ya no evacua; aparece barro en una curva y cambia la trayectoria de los camiones. El cambio aparentemente pequeño ha modificado el riesgo.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nCambiar primero y evaluar después invierte el orden preventivo.","key_points":["Activar la gestión del cambio antes de continuar cuando varían terreno, agua, equipo, método u organización.","Cambiar primero y evaluar después invierte el orden preventivo."],"stop_criterion":"Cambiar primero y evaluar después invierte el orden preventivo.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":7,"block_number":0,"lesson_ordinal":1,"segment_position":7,"segment_id":"4681f223-c526-5481-949d-054be7ce887d","slide_id":"a0b59da2-ec1f-5a9c-88d7-ff30ded98fd0","note_id":"d3551d6c-e9f6-54bf-a524-45f8c99a984a","title":"ACTIVIDAD DEL ALUMNO · 10 MINUTOS","narration_text":"Llegamos a una actividad práctica de aproximadamente 10 minutos. El objetivo es guiar la actividad sobre un cambio pequeño que altera drenaje y tráfico.\n\nLa situación de trabajo es esta. CASO 0A. UN CAMBIO PEQUEÑO CON EFECTO GRANDE Una motoniveladora eleva el borde interior de una pista. Tras la lluvia, el agua queda retenida, hay barro en una curva y los volquetes invaden el carril contrario. Reconocer cómo una corrección menor altera el sistema Identificad el cambio y las exposiciones. Definid las medidas inmediatas. Decidid quién autoriza la reapertura. Puesta en común por grupos. Se valoran cambio identificado, expuestos, medidas y autoridad correcta.\n\nPara orientar el análisis, considera este encuadre. El grupo debe identificar qué cambió, quién queda expuesto, qué señales mostrarían deterioro y qué acción inmediata permitiría controlar la situación sin improvisar.\n\nTrabaja en este orden. Primero separa hechos de suposiciones. Después identifica la energía o condición peligrosa, su trayectoria y las personas expuestas. A continuación propone una medida inmediata para retirar la exposición y otra que corrija la causa. Termina indicando quién decide, qué debe comprobarse y qué condición permite reabrir. Evita respuestas genéricas como tener cuidado o señalizar sin explicar qué barrera controla el escenario.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén ahora la reproducción y realiza la actividad. Conserva tu respuesta para compararla con la resolución posterior. La actividad se resuelve con decisiones observables, no con frases genéricas.","duration_seconds":132,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-007.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-007.jpg","explanation":"Objetivo\n\nGuiar la actividad sobre un cambio pequeño que altera drenaje y tráfico.\n\nExplicación detallada\n\nSituación. Una motoniveladora eleva el borde interior de una pista para corregir roderas. Después de una lluvia, el agua queda retenida, aparece barro en una curva y los volquetes invaden el carril contrario. Trabajo del alumno. Identifique el cambio, las exposiciones y las medidas inmediatas. Determine quién autoriza la reapertura. Criterio de resolución. La corrección ha alterado el drenaje y el tráfico. Se controlan o detienen movimientos, se señaliza, se restablece el drenaje y se verifica firme y visibilidad antes de reabrir. Autoriza el responsable definido por el DSS o la DIS, no el primer conductor que pasa.\n\nLectura guiada de la diapositiva\n\nCASO 0A. UN CAMBIO PEQUEÑO CON EFECTO GRANDE Una motoniveladora eleva el borde interior de una pista. Tras la lluvia, el agua queda retenida, hay barro en una curva y los volquetes invaden el carril contrario. Reconocer cómo una corrección menor altera el sistema Identificad el cambio y las exposiciones. Definid las medidas inmediatas. Decidid quién autoriza la reapertura. Puesta en común por grupos. Se valoran cambio identificado, expuestos, medidas y autoridad correcta.\n\nAplicación práctica\n\nEl grupo debe identificar qué cambió, quién queda expuesto, qué señales mostrarían deterioro y qué acción inmediata permitiría controlar la situación sin improvisar.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa actividad se resuelve con decisiones observables, no con frases genéricas.","key_points":["Guiar la actividad sobre un cambio pequeño que altera drenaje y tráfico.","La actividad se resuelve con decisiones observables, no con frases genéricas."],"stop_criterion":"La actividad se resuelve con decisiones observables, no con frases genéricas.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":8,"block_number":0,"lesson_ordinal":1,"segment_position":8,"segment_id":"6ab08354-dc33-5a88-b167-262d696066ee","slide_id":"59cc23b1-5fbf-5a70-b08b-9b82c3887e82","note_id":"29979c26-c5e1-57e5-ac1d-0ef070cbb00a","title":"RESOLUCIÓN DEL CASO 0A","narration_text":"Vamos a revisar la resolución. Lo importante es comprobar que la decisión retira la exposición inmediata, trata la causa y define cómo se recupera una condición segura.\n\nLa respuesta propuesta se desarrolla así. La corrección ha alterado el drenaje y el tráfico. Controlar Restablecer Verificar Controlar o detener movimientos y Recuperar el drenaje de la pista. Comprobar firme y visibilidad antes señalar. de reabrir. Autoriza el responsable definido por el Documento sobre Seguridad y Salud o la disposición interna de seguridad, no el primer conductor que pasa.\n\nSituación. Una motoniveladora eleva el borde interior de una pista para corregir roderas. Después de una lluvia, el agua queda retenida, aparece barro en una curva y los volquetes invaden el carril contrario. Trabajo del alumno. Identifique el cambio, las exposiciones y las medidas inmediatas. Determine quién autoriza la reapertura. Criterio de resolución. La corrección ha alterado el drenaje y el tráfico.\n\nEn una situación reconocible ocurriría lo siguiente. Cerrar o regular el tráfico evita la exposición inmediata; restablecer el drenaje corrige la causa; observar el comportamiento tras nuevas lluvias verifica que la solución funciona.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDistingue siempre entre control inmediato y solución definitiva. El primero detiene la exposición; la segunda corrige el diseño, el método, el mantenimiento o la organización. No retires una restricción temporal hasta comprobar el resultado y obtener la autorización prevista. Compara ahora esta solución con la tuya: revisa responsable, criterio de parada, condición de reapertura y evidencia de eficacia. Cerrar una incidencia exige comprobar el resultado, no solo ejecutar una reparación.","duration_seconds":142,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-008.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-008.jpg","explanation":"Objetivo\n\nExplicar la solución del caso mostrando control inmediato, corrección de causa y verificación de eficacia.\n\nExplicación detallada\n\nSituación. Una motoniveladora eleva el borde interior de una pista para corregir roderas. Después de una lluvia, el agua queda retenida, aparece barro en una curva y los volquetes invaden el carril contrario. Trabajo del alumno. Identifique el cambio, las exposiciones y las medidas inmediatas. Determine quién autoriza la reapertura. Criterio de resolución. La corrección ha alterado el drenaje y el tráfico. Se controlan o detienen movimientos, se señaliza, se restablece el drenaje y se verifica firme y visibilidad antes de reabrir. Autoriza el responsable definido por el DSS o la DIS, no el primer conductor que pasa.\n\nLectura guiada de la diapositiva\n\nLa corrección ha alterado el drenaje y el tráfico. Controlar Restablecer Verificar Controlar o detener movimientos y Recuperar el drenaje de la pista. Comprobar firme y visibilidad antes señalar. de reabrir. Autoriza el responsable definido por el Documento sobre Seguridad y Salud o la disposición interna de seguridad, no el primer conductor que pasa.\n\nAplicación práctica\n\nCerrar o regular el tráfico evita la exposición inmediata; restablecer el drenaje corrige la causa; observar el comportamiento tras nuevas lluvias verifica que la solución funciona.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nCerrar una incidencia exige comprobar el resultado, no solo ejecutar una reparación.","key_points":["Explicar la solución del caso mostrando control inmediato, corrección de causa y verificación de eficacia.","Cerrar una incidencia exige comprobar el resultado, no solo ejecutar una reparación."],"stop_criterion":"Cerrar una incidencia exige comprobar el resultado, no solo ejecutar una reparación.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":9,"block_number":0,"lesson_ordinal":1,"segment_position":9,"segment_id":"8eeb1445-c77b-53d7-899c-6464d1b6349d","slide_id":"cdcd6e68-8046-554b-9a90-418d4c7f032f","note_id":"2e3e66c2-ba8c-5d66-baf3-c796ce74c157","title":"BLOQUE 0. COMPROBACIÓN","narration_text":"Vamos a comprobar el aprendizaje del bloque. Justifica cada respuesta relacionando peligro, exposición, control y evidencia de campo.\n\nEstas son las cuestiones que debes resolver. 1. ¿Qué medida de la jerarquía ofrece más fiabilidad: eliminar la exposición, instruir al operador, usar equipo de protección individual o señalizar? 2. Razona si es verdadero o falso: «El Documento sobre Seguridad y Salud es la regla interna que gobierna una operación concreta». 3. Llega un equipo mayor al tajo. ¿Qué compruebas antes de continuar? 4. Enumera tres cambios que invalidan una evaluación previa.\n\nUtiliza este ejemplo para comprobar tu criterio. El alumno debe comparar eliminación, señalización, EPI e instrucciones; distinguir Documento sobre Seguridad y Salud y disposición interna; y reconocer cuándo un cambio obliga a reevaluar.\n\nHaz una pausa después de cada pregunta. Si dos opciones parecen posibles, elige la que elimine antes la exposición, dependa menos de la conducta y permita verificar su eficacia. En una secuencia, conserva el orden del trabajo seguro. Anota también el error más peligroso y la consecuencia que produciría; así evitarás acertar simplemente por descarte.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén la reproducción, responde por escrito y explica por qué descartas las demás opciones. Después continúa con la resolución razonada. La comprobación debe revelar razonamiento, no memoria literal.","duration_seconds":125,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-009.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-009.jpg","explanation":"Objetivo\n\nComprobar conceptos fundamentales del marco de partida antes de avanzar.\n\nExplicación detallada\n\nLos controles se seleccionan de arriba abajo. Eliminar la exposición o cambiar el diseño ofrece más fiabilidad que depender de que una persona recuerde una regla. Cuando una medida de orden inferior sea necesaria, debe integrarse en un conjunto de barreras y verificarse.\n\nUna explotación es dinámica. El avance modifica caras libres, bancos, distancias, drenajes, visibilidad, firme, radios de giro y trayectorias. Un control que era suficiente puede dejar de serlo después de una voladura, lluvia o entrada de un equipo mayor. La gestión del cambio se activa antes de seguir trabajando.\n\nResultados de aprendizaje. Distinguir peligro, riesgo, control, verificación y evidencia. Explicar la relación entre proyecto de explotación, DSS, DIS, procedimientos e instrucciones. Aplicar una jerarquía de controles antes de recurrir al EPI. Reconocer cuándo una variación obliga a detener, reevaluar y autorizar de nuevo.\n\nLectura guiada de la diapositiva\n\n1. ¿Qué medida de la jerarquía ofrece más fiabilidad: eliminar la exposición, instruir al operador, usar equipo de protección individual o señalizar? 2. Razona si es verdadero o falso: «El Documento sobre Seguridad y Salud es la regla interna que gobierna una operación concreta». 3. Llega un equipo mayor al tajo. ¿Qué compruebas antes de continuar? 4. Enumera tres cambios que invalidan una evaluación previa.\n\nAplicación práctica\n\nEl alumno debe comparar eliminación, señalización, EPI e instrucciones; distinguir Documento sobre Seguridad y Salud y disposición interna; y reconocer cuándo un cambio obliga a reevaluar.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa comprobación debe revelar razonamiento, no memoria literal.","key_points":["Comprobar conceptos fundamentales del marco de partida antes de avanzar.","La comprobación debe revelar razonamiento, no memoria literal."],"stop_criterion":"La comprobación debe revelar razonamiento, no memoria literal.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":10,"block_number":0,"lesson_ordinal":1,"segment_position":10,"segment_id":"fda16819-1147-52dc-9945-e6303c9ed008","slide_id":"2a5d0e39-9754-515a-8949-4a814b7830dc","note_id":"4adab5b1-622d-5db7-b426-574fd45ca546","title":"BLOQUE 0. RESPUESTAS RAZONADAS","narration_text":"Vamos a revisar la resolución. Lo importante es comprobar que la decisión retira la exposición inmediata, trata la causa y define cómo se recupera una condición segura.\n\nLa respuesta propuesta se desarrolla así. Eliminar la exposición o cambiar el diseño es más fiable que depender de que alguien recuerde una regla. Falso. La regla interna obligatoria es la disposición interna de seguridad; el Documento sobre Seguridad y Salud integra organización, evaluación y medidas. Para un equipo mayor se revisan dimensiones, masa, alcance, radios, frenado, visibilidad, compatibilidad y formación. Terreno, agua, equipo, secuencia, personal y entorno pueden invalidar una evaluación.\n\nLos controles se seleccionan de arriba abajo. Eliminar la exposición o cambiar el diseño ofrece más fiabilidad que depender de que una persona recuerde una regla. Cuando una medida de orden inferior sea necesaria, debe integrarse en un conjunto de barreras y verificarse. Una explotación es dinámica. El avance modifica caras libres, bancos, distancias, drenajes, visibilidad, firme, radios de giro y trayectorias.\n\nEn una situación reconocible ocurriría lo siguiente. Una persona puede conocer una norma y seguir expuesta si el diseño conserva la trayectoria del peligro. Del mismo modo, un papel firmado no demuestra que una barrera esté presente en campo.\n\nDistingue siempre entre control inmediato y solución definitiva. El primero detiene la exposición; la segunda corrige el diseño, el método, el mantenimiento o la organización. No retires una restricción temporal hasta comprobar el resultado y obtener la autorización prevista. Compara ahora esta solución con la tuya: revisa responsable, criterio de parada, condición de reapertura y evidencia de eficacia. La mejor respuesta siempre conecta peligro, exposición, control y evidencia.","duration_seconds":125,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-010.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-010.jpg","explanation":"Objetivo\n\nRazonar las respuestas del bloque cero y corregir errores frecuentes.\n\nExplicación detallada\n\nLos controles se seleccionan de arriba abajo. Eliminar la exposición o cambiar el diseño ofrece más fiabilidad que depender de que una persona recuerde una regla. Cuando una medida de orden inferior sea necesaria, debe integrarse en un conjunto de barreras y verificarse.\n\nUna explotación es dinámica. El avance modifica caras libres, bancos, distancias, drenajes, visibilidad, firme, radios de giro y trayectorias. Un control que era suficiente puede dejar de serlo después de una voladura, lluvia o entrada de un equipo mayor. La gestión del cambio se activa antes de seguir trabajando.\n\nResultados de aprendizaje. Distinguir peligro, riesgo, control, verificación y evidencia. Explicar la relación entre proyecto de explotación, DSS, DIS, procedimientos e instrucciones. Aplicar una jerarquía de controles antes de recurrir al EPI. Reconocer cuándo una variación obliga a detener, reevaluar y autorizar de nuevo.\n\nLectura guiada de la diapositiva\n\nEliminar la exposición o cambiar el diseño es más fiable que depender de que alguien recuerde una regla. Falso. La regla interna obligatoria es la disposición interna de seguridad; el Documento sobre Seguridad y Salud integra organización, evaluación y medidas. Para un equipo mayor se revisan dimensiones, masa, alcance, radios, frenado, visibilidad, compatibilidad y formación. Terreno, agua, equipo, secuencia, personal y entorno pueden invalidar una evaluación.\n\nAplicación práctica\n\nUna persona puede conocer una norma y seguir expuesta si el diseño conserva la trayectoria del peligro. Del mismo modo, un papel firmado no demuestra que una barrera esté presente en campo.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa mejor respuesta siempre conecta peligro, exposición, control y evidencia.","key_points":["Razonar las respuestas del bloque cero y corregir errores frecuentes.","La mejor respuesta siempre conecta peligro, exposición, control y evidencia."],"stop_criterion":"La mejor respuesta siempre conecta peligro, exposición, control y evidencia.","source_pages":"Bloque 0 · marco de partida"},{"slide_number":11,"block_number":1,"lesson_ordinal":2,"segment_position":1,"segment_id":"3ba20ac5-543f-586d-96f8-088b0e5ee50a","slide_id":"c34c8007-bfe4-51a8-a5e2-e3ebef35e59a","note_id":"b759f62c-5518-5425-8f5c-6265d7dc5ea8","title":"EL CICLO DE TRABAJO EN EXTERIOR","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es presentar el ciclo completo de una explotación exterior como una cadena de tareas relacionadas.\n\nLa actividad puede comprender investigación y preparación; retirada de tierra vegetal y desmonte; perforación; voladura; saneo; arranque; carga; transporte; vertido; tratamiento; acopios; expedición; mantenimiento; gestión de aguas; restauración y vigilancia ambiental. No todas las explotaciones utilizan explosivos ni la misma maquinaria, pero todas deben describir sus interfaces y estados no productivos. Antes de evaluar el riesgo hay que describir el trabajo real: qué se hace, dónde, con qué medios, en qué secuencia y con qué interacciones. Una descripción incompleta oculta exposiciones y produce controles genéricos.\n\nPensemos en un ejemplo. Desde la preparación y el arranque hasta el tratamiento, mantenimiento y restauración, cada fase entrega condiciones a la siguiente. Un defecto de una etapa puede reaparecer lejos y horas después.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Evaluar bien exige mirar el proceso completo, no una tarea aislada.","duration_seconds":122,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-011.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-011.jpg","explanation":"Objetivo\n\nPresentar el ciclo completo de una explotación exterior como una cadena de tareas relacionadas.\n\nExplicación detallada\n\nLa actividad puede comprender investigación y preparación; retirada de tierra vegetal y desmonte; perforación; voladura; saneo; arranque; carga; transporte; vertido; tratamiento; acopios; expedición; mantenimiento; gestión de aguas; restauración y vigilancia ambiental. No todas las explotaciones utilizan explosivos ni la misma maquinaria, pero todas deben describir sus interfaces y estados no productivos.\n\nAntes de evaluar el riesgo hay que describir el trabajo real: qué se hace, dónde, con qué medios, en qué secuencia y con qué interacciones. Una descripción incompleta oculta exposiciones y produce controles genéricos.\n\nAplicación práctica\n\nDesde la preparación y el arranque hasta el tratamiento, mantenimiento y restauración, cada fase entrega condiciones a la siguiente. Un defecto de una etapa puede reaparecer lejos y horas después.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEvaluar bien exige mirar el proceso completo, no una tarea aislada.","key_points":["Presentar el ciclo completo de una explotación exterior como una cadena de tareas relacionadas.","Evaluar bien exige mirar el proceso completo, no una tarea aislada."],"stop_criterion":"Evaluar bien exige mirar el proceso completo, no una tarea aislada.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":12,"block_number":1,"lesson_ordinal":2,"segment_position":2,"segment_id":"11e37bba-6ba4-5add-96f0-acc874e0df29","slide_id":"5f165c66-1b82-52ae-b40b-9e7deede0ab8","note_id":"dd7745a1-ddf3-5d15-bffd-0fa5038bb02e","title":"FASES E INTERACCIONES CRÍTICAS","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es identificar interacciones críticas entre preparación, arranque, carga, transporte y tratamiento.\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva.\n\nPensemos en un ejemplo. Una voladura afecta al saneo; el saneo condiciona la carga; la carga influye en estabilidad y tráfico; el transporte modifica pistas y el tratamiento puede devolver atascos o polvo al resto del sistema.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Las interfaces entre fases merecen tanta atención como cada fase por separado.","duration_seconds":128,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-012.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-012.jpg","explanation":"Objetivo\n\nIdentificar interacciones críticas entre preparación, arranque, carga, transporte y tratamiento.\n\nExplicación detallada\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLa actividad puede comprender investigación y preparación; retirada de tierra vegetal y desmonte; perforación; voladura; saneo; arranque; carga; transporte; vertido; tratamiento; acopios; expedición; mantenimiento; gestión de aguas; restauración y vigilancia ambiental. No todas las explotaciones utilizan explosivos ni la misma maquinaria, pero todas deben describir sus interfaces y estados no productivos.\n\nLectura guiada de la diapositiva\n\nFASE INTERACCIONES QUE DEBEN QUEDAR DESCRITAS Preparación Terreno no reconocido, servicios y terceros. Arranque Talud, proyecciones, barrenos, polvo y ruido. Carga Frente, giro, caída y comunicación pala-volquete. Transporte Velocidad, frenado, visibilidad, firme y bordes. Tratamiento Atrapamiento, atascos, energía, polvo y tolvas. Mantenimiento Consignación, elevación, presión, calor, gravedad e incendio. Cierre Accesos, inestabilidad diferida, agua y terceros.\n\nAplicación práctica\n\nUna voladura afecta al saneo; el saneo condiciona la carga; la carga influye en estabilidad y tráfico; el transporte modifica pistas y el tratamiento puede devolver atascos o polvo al resto del sistema.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLas interfaces entre fases merecen tanta atención como cada fase por separado.","key_points":["Identificar interacciones críticas entre preparación, arranque, carga, transporte y tratamiento.","Las interfaces entre fases merecen tanta atención como cada fase por separado."],"stop_criterion":"Las interfaces entre fases merecen tanta atención como cada fase por separado.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":13,"block_number":1,"lesson_ordinal":2,"segment_position":3,"segment_id":"d7e5880d-e929-58db-b274-a1dfd7973f51","slide_id":"18e98469-6958-596b-acc0-bb7651e89100","note_id":"6213b389-533f-5d1d-a458-b46b44d1e5e5","title":"FICHA MÍNIMA DE DEFINICIÓN DE UNA TAREA","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es enseñar a describir una tarea con un mínimo común de datos antes de evaluar el riesgo.\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva.\n\nPensemos en un ejemplo. No basta escribir mantenimiento de cinta. Hay que precisar tramo, aislamiento, personal, herramientas, secuencia, duración, energías, trabajos simultáneos, criterios de parada y estado de entrega.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Una definición incompleta produce una evaluación genérica y controles débiles.","duration_seconds":128,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-013.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-013.jpg","explanation":"Objetivo\n\nEnseñar a describir una tarea con un mínimo común de datos antes de evaluar el riesgo.\n\nExplicación detallada\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLectura guiada de la diapositiva\n\nCAMPO QUÉ DEBE QUEDAR DEFINIDO Objeto y resultado Qué se pretende y cómo se sabe que terminó bien. Ubicación Tajo, banco, plataforma, pista o planta; límites inequívocos. Secuencia Preparación, ejecución, comprobaciones, entrega y cierre. Personas Responsable, ejecutantes, operadores, empresas y terceros. Condiciones previas Autorizaciones, estabilidad, accesos, iluminación y comunicaciones. Parada y evidencias Criterios; lista, permiso, medición, registro o plano.\n\nAplicación práctica\n\nNo basta escribir mantenimiento de cinta. Hay que precisar tramo, aislamiento, personal, herramientas, secuencia, duración, energías, trabajos simultáneos, criterios de parada y estado de entrega.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna definición incompleta produce una evaluación genérica y controles débiles.","key_points":["Enseñar a describir una tarea con un mínimo común de datos antes de evaluar el riesgo.","Una definición incompleta produce una evaluación genérica y controles débiles."],"stop_criterion":"Una definición incompleta produce una evaluación genérica y controles débiles.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":14,"block_number":1,"lesson_ordinal":2,"segment_position":4,"segment_id":"27555c90-0e68-5bd7-ae45-a4e9d02c9dea","slide_id":"6cb7d5db-33bd-5630-a118-be9a0c3519d9","note_id":"a569ce30-cbf0-5a20-8a99-5ef660fa7ce9","title":"PERSONAS, EQUIPOS Y ENERGÍAS","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es ordenar el análisis alrededor de personas, equipos y energías presentes.\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva.\n\nPensemos en un ejemplo. En el cambio de un latiguillo intervienen mecánicos, operador, supervisión, excavadora, bomba hidráulica, implemento, presión residual y gravedad. Olvidar uno solo puede abrir una trayectoria peligrosa.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Las personas no se analizan separadas de los equipos y las energías que las rodean.","duration_seconds":129,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-014.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-014.jpg","explanation":"Objetivo\n\nOrdenar el análisis alrededor de personas, equipos y energías presentes.\n\nExplicación detallada\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLectura guiada de la diapositiva\n\nPersonas Responsable, ejecutantes, operadores, empresas y terceros expuestos. Equipos Máquinas, sustancias y herramientas de la tarea. Condiciones previas Estabilidad, accesos, iluminación, meteorología y comunicaciones. Una descripción incompleta oculta exposiciones y produce controles genéricos.\n\nAplicación práctica\n\nEn el cambio de un latiguillo intervienen mecánicos, operador, supervisión, excavadora, bomba hidráulica, implemento, presión residual y gravedad. Olvidar uno solo puede abrir una trayectoria peligrosa.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLas personas no se analizan separadas de los equipos y las energías que las rodean.","key_points":["Ordenar el análisis alrededor de personas, equipos y energías presentes.","Las personas no se analizan separadas de los equipos y las energías que las rodean."],"stop_criterion":"Las personas no se analizan separadas de los equipos y las energías que las rodean.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":15,"block_number":1,"lesson_ordinal":2,"segment_position":5,"segment_id":"d2fcf402-89a4-53bf-a9be-4e4b1c695247","slide_id":"6335759d-cacf-5d31-b4c5-8418f0b78e62","note_id":"a2d46a56-a189-5394-8c61-f362266bb39b","title":"ENERGÍA, TRAYECTORIA Y EXPUESTO","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es aplicar el modelo energía, trayectoria y persona expuesta a cualquier tarea.\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva.\n\nPensemos en un ejemplo. La energía de una carga suspendida sigue una trayectoria vertical; la de una manguera presurizada puede proyectar fluido; la de un volquete en pendiente sigue la dirección de movimiento posible.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Si no se puede describir la trayectoria, todavía no se entiende el escenario.","duration_seconds":126,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-015.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-015.jpg","explanation":"Objetivo\n\nAplicar el modelo energía, trayectoria y persona expuesta a cualquier tarea.\n\nExplicación detallada\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLectura guiada de la diapositiva\n\nEl análisis sigue el trabajo, no una lista genérica. Energía Trayectoria Expuesto En cada paso, ¿qué energía puede ¿Qué recorrido seguiría? ¿Quién entraría en ella? liberarse? Caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio.\n\nAplicación práctica\n\nLa energía de una carga suspendida sigue una trayectoria vertical; la de una manguera presurizada puede proyectar fluido; la de un volquete en pendiente sigue la dirección de movimiento posible.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nSi no se puede describir la trayectoria, todavía no se entiende el escenario.","key_points":["Aplicar el modelo energía, trayectoria y persona expuesta a cualquier tarea.","Si no se puede describir la trayectoria, todavía no se entiende el escenario."],"stop_criterion":"Si no se puede describir la trayectoria, todavía no se entiende el escenario.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":16,"block_number":1,"lesson_ordinal":2,"segment_position":6,"segment_id":"2511f687-9ff0-560e-b4b8-ee4349f09dd8","slide_id":"cb2b4aff-6bad-59bf-8b94-0344c51c1ec1","note_id":"131628a7-0872-545c-8896-f73e8560f0d5","title":"INTERFERENCIAS ENTRE TAREAS","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es reconocer interferencias incluso cuando cada tarea dispone de su propio procedimiento.\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nPensemos en un ejemplo. Producción quiere probar un triturador mientras una contrata trabaja aguas abajo. Ambas tareas pueden ser correctas por separado, pero su coincidencia introduce energía en una zona ocupada.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Coordinar significa controlar la interacción real, no intercambiar documentos.","duration_seconds":124,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-016.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-016.jpg","explanation":"Objetivo\n\nReconocer interferencias incluso cuando cada tarea dispone de su propio procedimiento.\n\nExplicación detallada\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLectura guiada de la diapositiva\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Considerar tráfico, voladura, mantenimiento, peatones, servicios y contratas. Mantenimiento energiza una línea que producción considera aislada. Una contrata cruza una zona de voladura. Una carretera pública queda expuesta a polvo o proyecciones.\n\nAplicación práctica\n\nProducción quiere probar un triturador mientras una contrata trabaja aguas abajo. Ambas tareas pueden ser correctas por separado, pero su coincidencia introduce energía en una zona ocupada.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nCoordinar significa controlar la interacción real, no intercambiar documentos.","key_points":["Reconocer interferencias incluso cuando cada tarea dispone de su propio procedimiento.","Coordinar significa controlar la interacción real, no intercambiar documentos."],"stop_criterion":"Coordinar significa controlar la interacción real, no intercambiar documentos.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":17,"block_number":1,"lesson_ordinal":2,"segment_position":7,"segment_id":"5b9376e9-85b8-51c5-8ca5-370744e9ab38","slide_id":"c8755ecd-ad8e-59e1-85ad-55be05b1b1a7","note_id":"bfd9906d-7724-56a8-998f-3dcb447f1e11","title":"CRITERIOS DE PARADA Y EVIDENCIAS","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es definir criterios de parada, evidencias y autoridad de reanudación antes de empezar.\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva.\n\nPensemos en un ejemplo. Una grieta nueva, pérdida de visibilidad, fuga presurizada o señal de barreno fallido deben tener una respuesta acordada. También debe saberse quién puede confirmar que el riesgo ha sido reevaluado.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Parar es eficaz solo si existe un camino claro y documentado para reanudar.","duration_seconds":127,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-017.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-017.jpg","explanation":"Objetivo\n\nDefinir criterios de parada, evidencias y autoridad de reanudación antes de empezar.\n\nExplicación detallada\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, revisa circulación y verifica durante un periodo. Repetir relleno no cierra la causa.\n\nLectura guiada de la diapositiva\n\nNo se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Criterio de parada Defecto o variación que obliga a detener, aislar y escalar. Evidencias Lista, permiso, medición, registro, parte, plano o comunicación formal.\n\nAplicación práctica\n\nUna grieta nueva, pérdida de visibilidad, fuga presurizada o señal de barreno fallido deben tener una respuesta acordada. También debe saberse quién puede confirmar que el riesgo ha sido reevaluado.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nParar es eficaz solo si existe un camino claro y documentado para reanudar.","key_points":["Definir criterios de parada, evidencias y autoridad de reanudación antes de empezar.","Parar es eficaz solo si existe un camino claro y documentado para reanudar."],"stop_criterion":"Parar es eficaz solo si existe un camino claro y documentado para reanudar.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":18,"block_number":1,"lesson_ordinal":2,"segment_position":8,"segment_id":"36722f07-6b52-5472-a35c-dd6fc38bd126","slide_id":"a3e90a2c-e8ca-52c1-b393-56aa2fdf14ea","note_id":"50fb26a6-477c-5c65-9b98-8ef035b6efcb","title":"ACTIVIDAD DEL ALUMNO · 20 MINUTOS","narration_text":"Llegamos a una actividad práctica de aproximadamente 20 minutos. El objetivo es dirigir una actividad en la que el alumno describa una operación real antes de evaluarla.\n\nLa situación de trabajo es esta. ACTIVIDAD 1. DESCRIBIR ANTES DE EVALUAR Describid el trabajo real de una operación: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Una ficha de una página Incluid todos los campos de la ficha mínima. Marcado con asterisco cada dato por confirmar en campo. Registrad las diferencias con el procedimiento existente. Puesta en común por parejas. Se valoran la ficha completa y las diferencias registradas.\n\nPara orientar el análisis, considera este encuadre. Puede elegirse carga de volquetes, limpieza de tolva o mantenimiento de cinta. El grupo debe reconstruir pasos, ubicaciones, participantes, energías, interferencias, parada y entrega final.\n\nTrabaja en este orden. Primero separa hechos de suposiciones. Después identifica la energía o condición peligrosa, su trayectoria y las personas expuestas. A continuación propone una medida inmediata para retirar la exposición y otra que corrija la causa. Termina indicando quién decide, qué debe comprobarse y qué condición permite reabrir. Evita respuestas genéricas como tener cuidado o señalizar sin explicar qué barrera controla el escenario.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén ahora la reproducción y realiza la actividad. Conserva tu respuesta para compararla con la resolución posterior. Primero se describe el trabajo real; después se valora su riesgo.","duration_seconds":131,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-018.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-018.jpg","explanation":"Objetivo\n\nDirigir una actividad en la que el alumno describa una operación real antes de evaluarla.\n\nExplicación detallada\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLectura guiada de la diapositiva\n\nACTIVIDAD 1. DESCRIBIR ANTES DE EVALUAR Describid el trabajo real de una operación: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Una ficha de una página Incluid todos los campos de la ficha mínima. Marcado con asterisco cada dato por confirmar en campo. Registrad las diferencias con el procedimiento existente. Puesta en común por parejas. Se valoran la ficha completa y las diferencias registradas.\n\nAplicación práctica\n\nPuede elegirse carga de volquetes, limpieza de tolva o mantenimiento de cinta. El grupo debe reconstruir pasos, ubicaciones, participantes, energías, interferencias, parada y entrega final.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nPrimero se describe el trabajo real; después se valora su riesgo.","key_points":["Dirigir una actividad en la que el alumno describa una operación real antes de evaluarla.","Primero se describe el trabajo real; después se valora su riesgo."],"stop_criterion":"Primero se describe el trabajo real; después se valora su riesgo.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":19,"block_number":1,"lesson_ordinal":2,"segment_position":9,"segment_id":"1a378471-5b60-5df1-bffc-caf3d4efb23e","slide_id":"ba9cb165-ef39-5c8c-a152-6c52926d43cb","note_id":"76ad1912-c495-5122-8b48-822fa8c0cb9d","title":"BLOQUE 1. COMPROBACIÓN","narration_text":"Vamos a comprobar el aprendizaje del bloque. Justifica cada respuesta relacionando peligro, exposición, control y evidencia de campo.\n\nEstas son las cuestiones que debes resolver. Primera pregunta. Ordena las fases preparación, arranque, carga, transporte y tratamiento. Segunda pregunta. Explica qué falta en una ficha que no incluye criterios de parada ni autoridad de reanudación. Tercera pregunta. Decide si puede iniciarse una tarea cuando no se conoce quién autoriza la reapertura. Cuarta pregunta. Enumera las fuentes de energía que deben revisarse: mecánica, eléctrica, hidráulica, neumática, térmica, química y gravitatoria, además de cualquier otra presente en la tarea.\n\nUtiliza este ejemplo para comprobar tu criterio. El alumno debe detectar que una ficha sin criterios de parada ni autoridad de reanudación no permite controlar desviaciones, aunque enumere equipos y personas.\n\nHaz una pausa después de cada pregunta. Si dos opciones parecen posibles, elige la que elimine antes la exposición, dependa menos de la conducta y permita verificar su eficacia. En una secuencia, conserva el orden del trabajo seguro. Anota también el error más peligroso y la consecuencia que produciría; así evitarás acertar simplemente por descarte.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén la reproducción, responde por escrito y explica por qué descartas las demás opciones. Después continúa con la resolución razonada. Una ficha útil permite decidir antes, durante y al terminar.","duration_seconds":125,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-019.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-019.jpg","explanation":"Objetivo\n\nComprobar el orden del ciclo y la calidad mínima de una ficha de tarea.\n\nExplicación detallada\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLa actividad puede comprender investigación y preparación; retirada de tierra vegetal y desmonte; perforación; voladura; saneo; arranque; carga; transporte; vertido; tratamiento; acopios; expedición; mantenimiento; gestión de aguas; restauración y vigilancia ambiental. No todas las explotaciones utilizan explosivos ni la misma maquinaria, pero todas deben describir sus interfaces y estados no productivos.\n\nLectura guiada de la diapositiva\n\nPrimera pregunta. Ordena las fases preparación, arranque, carga, transporte y tratamiento. Segunda pregunta. Explica qué falta en una ficha que no incluye criterios de parada ni autoridad de reanudación. Tercera pregunta. Decide si puede iniciarse una tarea cuando no se conoce quién autoriza la reapertura. Cuarta pregunta. Enumera las fuentes de energía que deben revisarse: mecánica, eléctrica, hidráulica, neumática, térmica, química y gravitatoria, además de cualquier otra presente en la tarea.\n\nAplicación práctica\n\nEl alumno debe detectar que una ficha sin criterios de parada ni autoridad de reanudación no permite controlar desviaciones, aunque enumere equipos y personas.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna ficha útil permite decidir antes, durante y al terminar.","key_points":["Comprobar el orden del ciclo y la calidad mínima de una ficha de tarea.","Una ficha útil permite decidir antes, durante y al terminar."],"stop_criterion":"Una ficha útil permite decidir antes, durante y al terminar.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":20,"block_number":1,"lesson_ordinal":2,"segment_position":10,"segment_id":"29aa02c9-97c1-5893-a21a-52499f0c64d6","slide_id":"15f836ba-aeb0-562b-9a86-bcc9ce0046d6","note_id":"b13aae75-1c26-5f17-93ed-04197b1d4806","title":"BLOQUE 1. RESPUESTAS RAZONADAS","narration_text":"Vamos a revisar la resolución. Lo importante es comprobar que la decisión retira la exposición inmediata, trata la causa y define cómo se recupera una condición segura.\n\nLa respuesta propuesta se desarrolla así. El orden es preparación, arranque, carga, transporte y tratamiento. Sin criterios de parada y autoridad de reanudación, la ficha no sirve para evaluar. No se inicia la tarea sin autoridad de reanudación conocida. Las seis energías son mecánica, eléctrica, hidráulica, térmica, química y gravitatoria.\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque.\n\nEn una situación reconocible ocurriría lo siguiente. Ordenar fases no es un ejercicio académico: permite ver qué condiciones recibe cada equipo. Identificar energía y trayectoria convierte una lista en un escenario controlable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDistingue siempre entre control inmediato y solución definitiva. El primero detiene la exposición; la segunda corrige el diseño, el método, el mantenimiento o la organización. No retires una restricción temporal hasta comprobar el resultado y obtener la autorización prevista. Compara ahora esta solución con la tuya: revisa responsable, criterio de parada, condición de reapertura y evidencia de eficacia. La definición del trabajo es la base de todo el análisis posterior.","duration_seconds":135,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-020.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-020.jpg","explanation":"Objetivo\n\nExplicar las respuestas del bloque uno conectándolas con el trabajo de campo.\n\nExplicación detallada\n\nEl análisis debe seguir el trabajo y no una lista genérica. En cada paso se pregunta qué energía puede liberarse, qué trayectoria seguiría y quién entraría en ella. Las trayectorias incluyen caída de rocas, desplazamiento de máquina, arco eléctrico, proyección, chorro a presión, rodadura, caída a distinto nivel, nube de polvo o propagación de incendio. Condición de parada del bloque. No se inicia una tarea si no se conocen ubicación, secuencia, responsables, equipos, interacciones, criterios de parada y autoridad de reanudación. Actividad 1 Describir antes de evaluar Seleccione una operación real: carga de volquetes, mantenimiento de una cinta o limpieza de una tolva. Redacte una ficha de una página con los nueve campos anteriores. Marque con un asterisco cada dato que deba confirmarse en campo. Compare la ficha con el procedimiento existente y registre las diferencias.\n\nLa actividad puede comprender investigación y preparación; retirada de tierra vegetal y desmonte; perforación; voladura; saneo; arranque; carga; transporte; vertido; tratamiento; acopios; expedición; mantenimiento; gestión de aguas; restauración y vigilancia ambiental. No todas las explotaciones utilizan explosivos ni la misma maquinaria, pero todas deben describir sus interfaces y estados no productivos.\n\nLectura guiada de la diapositiva\n\nEl orden es preparación, arranque, carga, transporte y tratamiento. Sin criterios de parada y autoridad de reanudación, la ficha no sirve para evaluar. No se inicia la tarea sin autoridad de reanudación conocida. Las seis energías son mecánica, eléctrica, hidráulica, térmica, química y gravitatoria.\n\nAplicación práctica\n\nOrdenar fases no es un ejercicio académico: permite ver qué condiciones recibe cada equipo. Identificar energía y trayectoria convierte una lista en un escenario controlable.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa definición del trabajo es la base de todo el análisis posterior.","key_points":["Explicar las respuestas del bloque uno conectándolas con el trabajo de campo.","La definición del trabajo es la base de todo el análisis posterior."],"stop_criterion":"La definición del trabajo es la base de todo el análisis posterior.","source_pages":"Bloque 1 · definición de los trabajos"},{"slide_number":21,"block_number":2,"lesson_ordinal":3,"segment_position":1,"segment_id":"db7a3540-b88e-5bd7-8e63-14c40cad150f","slide_id":"d91500bb-bfc4-51ed-927f-874a63bb5136","note_id":"dd1ffae3-013a-5cb3-b930-14e440dfc80e","title":"MÉTODO OPERATIVO DE EVALUACIÓN","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es presentar un método operativo de evaluación que no se reduzca a una matriz numérica.\n\nLa evaluación combina severidad, probabilidad y exposición, pero la cifra final no debe ocultar el escenario. En sucesos de consecuencias catastróficas, como colapso de talud, atropello, vuelco, explosión o contacto eléctrico, una baja frecuencia histórica no justifica controles débiles. Deben identificarse las barreras críticas y comprobarse antes y durante el trabajo.\n\nPensemos en un ejemplo. Se describe el peligro, la trayectoria y la exposición; después se estima consecuencia y probabilidad, se eligen controles, se asigna responsable y se define cómo verificar eficacia.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Una cifra ayuda a priorizar, pero nunca sustituye la descripción del escenario.","duration_seconds":129,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-021.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-021.jpg","explanation":"Objetivo\n\nPresentar un método operativo de evaluación que no se reduzca a una matriz numérica.\n\nExplicación detallada\n\nLa evaluación combina severidad, probabilidad y exposición, pero la cifra final no debe ocultar el escenario. En sucesos de consecuencias catastróficas, como colapso de talud, atropello, vuelco, explosión o contacto eléctrico, una baja frecuencia histórica no justifica controles débiles. Deben identificarse las barreras críticas y comprobarse antes y durante el trabajo.\n\nLectura guiada de la diapositiva\n\nPeligro concreto Exposición y trayectoria ¿Qué situación o energía puede causar daño? ¿A quién o qué alcanza y por qué vía? Escenario Controles ¿Qué máximo razonable puede ocurrir? ¿Cuáles existen y de qué dependen? Prueba de eficacia Revisión y parada Criterio, frecuencia y responsable de cada barrera. ¿Qué cambio invalida el análisis? Una baja frecuencia histórica no justifica controles débiles ante colapso de talud, atropello, vuelco, explosión o contacto eléctrico.\n\nAplicación práctica\n\nSe describe el peligro, la trayectoria y la exposición; después se estima consecuencia y probabilidad, se eligen controles, se asigna responsable y se define cómo verificar eficacia.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna cifra ayuda a priorizar, pero nunca sustituye la descripción del escenario.","key_points":["Presentar un método operativo de evaluación que no se reduzca a una matriz numérica.","Una cifra ayuda a priorizar, pero nunca sustituye la descripción del escenario."],"stop_criterion":"Una cifra ayuda a priorizar, pero nunca sustituye la descripción del escenario.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":22,"block_number":2,"lesson_ordinal":3,"segment_position":2,"segment_id":"3977a90e-7b89-5343-90f6-fa9c00c3b6ce","slide_id":"94965c34-922b-5255-883f-82252ae1d7c3","note_id":"26cf1f96-e727-5928-b4e3-694d839f1bb7","title":"TALUDES, BANCOS, BERMAS Y PLATAFORMAS","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es explicar los factores que gobiernan la estabilidad de taludes, bancos, bermas y plataformas.\n\nLa estabilidad depende de la geología, discontinuidades, meteorización, agua, geometría, excavación, daños de voladura, vibraciones, cargas próximas al borde y evolución temporal. Un talud que no muestra caída visible puede estar degradándose. Por eso el diseño geotécnico y la observación sistemática son complementarios. El proyecto define alturas, ángulos, bermas, secuencia y drenaje. La ITC del capítulo VII exige que las bermas definitivas respondan a un estudio geotécnico y que las plataformas permitan maniobrar sin aproximaciones innecesarias.\n\nPensemos en un ejemplo. Dos frentes con el mismo ángulo pueden comportarse de forma distinta por discontinuidades, agua, meteorización, orientación o daños de voladura. El proyecto fija la geometría, pero el campo confirma su estado.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La estabilidad se gestiona combinando diseño, observación y revisión ante cambios.","duration_seconds":144,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-022.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-022.jpg","explanation":"Objetivo\n\nExplicar los factores que gobiernan la estabilidad de taludes, bancos, bermas y plataformas.\n\nExplicación detallada\n\nLa estabilidad depende de la geología, discontinuidades, meteorización, agua, geometría, excavación, daños de voladura, vibraciones, cargas próximas al borde y evolución temporal. Un talud que no muestra caída visible puede estar degradándose. Por eso el diseño geotécnico y la observación sistemática son complementarios. El proyecto define alturas, ángulos, bermas, secuencia y drenaje. La ITC del capítulo VII exige que las bermas definitivas respondan a un estudio geotécnico y que las plataformas permitan maniobrar sin aproximaciones innecesarias. En el trabajo normal establece una distancia mínima de cinco metros al\n\nMITECO sobre control geotécnico insiste en que la explotación modifica continuamente las condiciones y que el seguimiento no puede limitarse a la comprobación inicial. Los métodos observacionales sirven para priorizar y detectar; no sustituyen cálculos, instrumentación ni juicio especializado cuando son necesarios.\n\nLectura guiada de la diapositiva\n\nLa estabilidad depende de geología, discontinuidades, meteorización, agua, geometría, daños de voladura y cargas próximas al borde. El proyecto define alturas, ángulos, bermas, secuencia y drenaje. La berma definitiva responde a un estudio geotécnico. En trabajo normal, distancia mínima de 5 m al borde del banco. En situaciones especiales, topes o barreras no franqueables. Un talud sin caída visible puede estar degradándose. Referencia reglamentaria: ITC del capítulo VII. Geometría según proyecto y estudio geotécnico.\n\nAplicación práctica\n\nDos frentes con el mismo ángulo pueden comportarse de forma distinta por discontinuidades, agua, meteorización, orientación o daños de voladura. El proyecto fija la geometría, pero el campo confirma su estado.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa estabilidad se gestiona combinando diseño, observación y revisión ante cambios.","key_points":["Explicar los factores que gobiernan la estabilidad de taludes, bancos, bermas y plataformas.","La estabilidad se gestiona combinando diseño, observación y revisión ante cambios."],"stop_criterion":"La estabilidad se gestiona combinando diseño, observación y revisión ante cambios.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":23,"block_number":2,"lesson_ordinal":3,"segment_position":3,"segment_id":"5212d685-d476-59c7-b6a4-bd1ab5c61211","slide_id":"737181a0-f70d-5e8b-ae81-789bae159d2a","note_id":"675d85cc-75f8-5121-9ab4-27fa7c86a785","title":"INDICADORES DE INESTABILIDAD","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es reconocer indicadores tempranos de inestabilidad y responder sin acercarse al peligro.\n\nLa estabilidad depende de la geología, discontinuidades, meteorización, agua, geometría, excavación, daños de voladura, vibraciones, cargas próximas al borde y evolución temporal. Un talud que no muestra caída visible puede estar degradándose. Por eso el diseño geotécnico y la observación sistemática son complementarios. El proyecto define alturas, ángulos, bermas, secuencia y drenaje. La ITC del capítulo VII exige que las bermas definitivas respondan a un estudio geotécnico y que las plataformas permitan maniobrar sin aproximaciones innecesarias.\n\nPensemos en un ejemplo. Grietas nuevas, caída de fragmentos, abombamiento, agua turbia o deformación de bermas son información. La respuesta inicial es retirar exposición, delimitar, comunicar y evaluar desde un lugar seguro.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: No se entra en una zona potencialmente inestable para comprobar si realmente lo está.","duration_seconds":144,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-023.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-023.jpg","explanation":"Objetivo\n\nReconocer indicadores tempranos de inestabilidad y responder sin acercarse al peligro.\n\nExplicación detallada\n\nLa estabilidad depende de la geología, discontinuidades, meteorización, agua, geometría, excavación, daños de voladura, vibraciones, cargas próximas al borde y evolución temporal. Un talud que no muestra caída visible puede estar degradándose. Por eso el diseño geotécnico y la observación sistemática son complementarios. El proyecto define alturas, ángulos, bermas, secuencia y drenaje. La ITC del capítulo VII exige que las bermas definitivas respondan a un estudio geotécnico y que las plataformas permitan maniobrar sin aproximaciones innecesarias. En el trabajo normal establece una distancia mínima de cinco metros al\n\nMITECO sobre control geotécnico insiste en que la explotación modifica continuamente las condiciones y que el seguimiento no puede limitarse a la comprobación inicial. Los métodos observacionales sirven para priorizar y detectar; no sustituyen cálculos, instrumentación ni juicio especializado cuando son necesarios.\n\nLectura guiada de la diapositiva\n\nGrietas nuevas o crecientes Aislar, señalar, comparar y comunicar. Caída de fragmentos Retirar personas y equipos; no sanear sin método autorizado. Abombamiento en el pie Ampliar exclusión y pedir evaluación. Agua turbia o surgencia Controlar evolución; no bloquear sin análisis. Escalón, hundimiento o Cerrar y verificar. berma deformada Cambio tras lluvia, hielo o Inspección extraordinaria. voladura\n\nAplicación práctica\n\nGrietas nuevas, caída de fragmentos, abombamiento, agua turbia o deformación de bermas son información. La respuesta inicial es retirar exposición, delimitar, comunicar y evaluar desde un lugar seguro.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nNo se entra en una zona potencialmente inestable para comprobar si realmente lo está.","key_points":["Reconocer indicadores tempranos de inestabilidad y responder sin acercarse al peligro.","No se entra en una zona potencialmente inestable para comprobar si realmente lo está."],"stop_criterion":"No se entra en una zona potencialmente inestable para comprobar si realmente lo está.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":24,"block_number":2,"lesson_ordinal":3,"segment_position":4,"segment_id":"2715e41b-50fb-54b4-b163-cbd26f818de3","slide_id":"d4bd4f29-ac62-5e12-b6ea-0d7706391905","note_id":"0e4ae900-f71f-5970-a00c-03d34d947cf6","title":"INSPECCIÓN GEOTÉCNICA EN TRES NIVELES","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es diferenciar inspección operativa, técnica y especializada y saber cuándo escalar.\n\nMITECO sobre control geotécnico insiste en que la explotación modifica continuamente las condiciones y que el seguimiento no puede limitarse a la comprobación inicial. Los métodos observacionales sirven para priorizar y detectar; no sustituyen cálculos, instrumentación ni juicio especializado cuando son necesarios. La estabilidad depende de la geología, discontinuidades, meteorización, agua, geometría, excavación, daños de voladura, vibraciones, cargas próximas al borde y evolución temporal. Un talud que no muestra caída visible puede estar degradándose. Por eso el diseño geotécnico y la observación sistemática son complementarios. El proyecto define alturas, ángulos, bermas, secuencia y drenaje.\n\nPensemos en un ejemplo. El operador puede detectar una grieta; una inspección técnica compara evolución y criterios; un especialista geotécnico interpreta mecanismos y define instrumentación o rediseño.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Cada nivel observa algo distinto y ninguno debe simular competencias que no posee.","duration_seconds":127,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-024.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-024.jpg","explanation":"Objetivo\n\nDiferenciar inspección operativa, técnica y especializada y saber cuándo escalar.\n\nExplicación detallada\n\nMITECO sobre control geotécnico insiste en que la explotación modifica continuamente las condiciones y que el seguimiento no puede limitarse a la comprobación inicial. Los métodos observacionales sirven para priorizar y detectar; no sustituyen cálculos, instrumentación ni juicio especializado cuando son necesarios.\n\nLa estabilidad depende de la geología, discontinuidades, meteorización, agua, geometría, excavación, daños de voladura, vibraciones, cargas próximas al borde y evolución temporal. Un talud que no muestra caída visible puede estar degradándose. Por eso el diseño geotécnico y la observación sistemática son complementarios. El proyecto define alturas, ángulos, bermas, secuencia y drenaje. La ITC del capítulo VII exige que las bermas definitivas respondan a un estudio geotécnico y que las plataformas permitan maniobrar sin aproximaciones innecesarias. En el trabajo normal establece una distancia mínima de cinco metros al\n\nLectura guiada de la diapositiva\n\nOperativa Técnica Especializada Personal y supervisión al inicio Personal competente con Profesional geotécnico cuando y durante el turno; detecta frecuencia definida y tras el riesgo o el cambio lo exija; cambios visibles, caída, agua y eventos; compara con diseño, analiza mecanismo, medidas y exposición inmediata. registros, instrumentación y reapertura. umbrales. Los métodos observacionales priorizan y detectan; no sustituyen cálculos ni instrumentación. Referencia técnica: MITECO. Frecuencias y umbrales definidos para la explotación.\n\nAplicación práctica\n\nEl operador puede detectar una grieta; una inspección técnica compara evolución y criterios; un especialista geotécnico interpreta mecanismos y define instrumentación o rediseño.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nCada nivel observa algo distinto y ninguno debe simular competencias que no posee.","key_points":["Diferenciar inspección operativa, técnica y especializada y saber cuándo escalar.","Cada nivel observa algo distinto y ninguno debe simular competencias que no posee."],"stop_criterion":"Cada nivel observa algo distinto y ninguno debe simular competencias que no posee.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":25,"block_number":2,"lesson_ordinal":3,"segment_position":5,"segment_id":"6194460d-6e87-518a-a1ab-9cf467ea059e","slide_id":"96a489a0-8a19-53a5-b6cd-a391e9a675b3","note_id":"0c4ee205-2408-58a4-a30f-1a1f536c4a6c","title":"AGUA, DRENAJE Y METEOROLOGÍA","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es relacionar agua, drenaje y meteorología con estabilidad, pistas y capacidad de frenado.\n\nEl agua puede reducir la resistencia, aumentar presiones, erosionar, ocultar defectos, degradar pistas y disminuir adherencia. El control comienza aguas arriba: cunetas de guarda, drenajes, bombeos, mantenimiento y vigilancia de puntos de vertido. Una solución improvisada puede trasladar el problema al pie de un talud o a una vía. Mantener libres cunetas, pasos y desagües sin colocar a personas en trayectorias de caída o arrastre. Definir umbrales por lluvia, nivel, caudal, visibilidad, viento o tormenta y asociar una acción. Revisar plataformas y pistas después de episodios intensos: blandones, erosión, socavación, roderas, arrastres y pérdida de protección.\n\nPensemos en un ejemplo. El agua puede saturar un material, erosionar un pie, ocultar un bache y reducir adherencia. Un bombeo improvisado también puede trasladar el problema a otra ladera o escombrera.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: El agua se controla desde su origen hasta un punto de vertido seguro.","duration_seconds":125,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-025.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-025.jpg","explanation":"Objetivo\n\nRelacionar agua, drenaje y meteorología con estabilidad, pistas y capacidad de frenado.\n\nExplicación detallada\n\nEl agua puede reducir la resistencia, aumentar presiones, erosionar, ocultar defectos, degradar pistas y disminuir adherencia. El control comienza aguas arriba: cunetas de guarda, drenajes, bombeos, mantenimiento y vigilancia de puntos de vertido. Una solución improvisada puede trasladar el problema al pie de un talud o a una vía. Mantener libres cunetas, pasos y desagües sin colocar a personas en trayectorias de caída o arrastre. Definir umbrales por lluvia, nivel, caudal, visibilidad, viento o tormenta y asociar una acción. Revisar plataformas y pistas después de episodios intensos: blandones, erosión, socavación, roderas, arrastres y pérdida de protección.\n\nNo bombear ni desviar agua hacia ladera, escombrera o estructura sin comprobar capacidad y estabilidad del receptor. Tratar balsas, lodos y excavaciones inundadas como riesgos geotécnicos y de ahogamiento; delimitar y prever rescate sin entrada impulsiva.\n\nLectura guiada de la diapositiva\n\nEl agua reduce resistencia, aumenta presiones, erosiona, oculta defectos y degrada pistas. Control desde aguas arriba mediante cunetas de guarda, drenajes, bombeos y vertidos. Cada umbral de lluvia, nivel, caudal, visibilidad, viento o tormenta debe tener una acción. Valores según diseño y evaluación. Tras episodios intensos: blandones, erosión, socavación y roderas. No desviar agua sin comprobar capacidad del receptor. Delimitar balsas y excavaciones inundadas; prever rescate sin entrada impulsiva.\n\nAplicación práctica\n\nEl agua puede saturar un material, erosionar un pie, ocultar un bache y reducir adherencia. Un bombeo improvisado también puede trasladar el problema a otra ladera o escombrera.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl agua se controla desde su origen hasta un punto de vertido seguro.","key_points":["Relacionar agua, drenaje y meteorología con estabilidad, pistas y capacidad de frenado.","El agua se controla desde su origen hasta un punto de vertido seguro."],"stop_criterion":"El agua se controla desde su origen hasta un punto de vertido seguro.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":26,"block_number":2,"lesson_ordinal":3,"segment_position":6,"segment_id":"6b0da393-198d-5be1-9fd0-84b9827aa05f","slide_id":"1d4e5f1a-9e5b-5e33-b864-87449399b8aa","note_id":"f8b8b12f-174e-5e87-997e-a3133d8255fc","title":"ACTIVIDAD DEL ALUMNO · 15 MINUTOS","narration_text":"Llegamos a una actividad práctica de aproximadamente 15 minutos. El objetivo es plantear el caso de lluvia posterior a una voladura y obligar a decidir antes de entrar.\n\nLa situación de trabajo es esta. CASO 2A. LLUVIA DESPUÉS DE LA VOLADURA Tras una voladura nocturna llueve intensamente. A primera hora hay agua turbia en el pie, material suelto en una berma y una grieta nueva. Producción propone cargar desde abajo mientras se revisa desde un vehículo ligero. Decisión del grupo ¿Puede iniciarse la carga? Definid zona, información y autoridad. Puesta en común en plenario. Criterios: exclusión, evaluación competente y reapertura documentada.\n\nPara orientar el análisis, considera este encuadre. El alumno debe tratar conjuntamente agua turbia, material suelto y grieta nueva, establecer exclusión, comunicar, pedir evaluación competente y definir condiciones de reapertura.\n\nTrabaja en este orden. Primero separa hechos de suposiciones. Después identifica la energía o condición peligrosa, su trayectoria y las personas expuestas. A continuación propone una medida inmediata para retirar la exposición y otra que corrija la causa. Termina indicando quién decide, qué debe comprobarse y qué condición permite reabrir. Evita respuestas genéricas como tener cuidado o señalizar sin explicar qué barrera controla el escenario.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén ahora la reproducción y realiza la actividad. Conserva tu respuesta para compararla con la resolución posterior. La ausencia de un desprendimiento previo no es evidencia de estabilidad.","duration_seconds":131,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-026.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-026.jpg","explanation":"Objetivo\n\nPlantear el caso de lluvia posterior a una voladura y obligar a decidir antes de entrar.\n\nExplicación detallada\n\nEl agua puede reducir la resistencia, aumentar presiones, erosionar, ocultar defectos, degradar pistas y disminuir adherencia. El control comienza aguas arriba: cunetas de guarda, drenajes, bombeos, mantenimiento y vigilancia de puntos de vertido. Una solución improvisada puede trasladar el problema al pie de un talud o a una vía. Mantener libres cunetas, pasos y desagües sin colocar a personas en trayectorias de caída o arrastre. Definir umbrales por lluvia, nivel, caudal, visibilidad, viento o tormenta y asociar una acción. Revisar plataformas y pistas después de episodios intensos: blandones, erosión, socavación, roderas, arrastres y pérdida de protección.\n\nNo bombear ni desviar agua hacia ladera, escombrera o estructura sin comprobar capacidad y estabilidad del receptor. Tratar balsas, lodos y excavaciones inundadas como riesgos geotécnicos y de ahogamiento; delimitar y prever rescate sin entrada impulsiva.\n\nLectura guiada de la diapositiva\n\nCASO 2A. LLUVIA DESPUÉS DE LA VOLADURA Tras una voladura nocturna llueve intensamente. A primera hora hay agua turbia en el pie, material suelto en una berma y una grieta nueva. Producción propone cargar desde abajo mientras se revisa desde un vehículo ligero. Decisión del grupo ¿Puede iniciarse la carga? Definid zona, información y autoridad. Puesta en común en plenario. Criterios: exclusión, evaluación competente y reapertura documentada.\n\nAplicación práctica\n\nEl alumno debe tratar conjuntamente agua turbia, material suelto y grieta nueva, establecer exclusión, comunicar, pedir evaluación competente y definir condiciones de reapertura.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa ausencia de un desprendimiento previo no es evidencia de estabilidad.","key_points":["Plantear el caso de lluvia posterior a una voladura y obligar a decidir antes de entrar.","La ausencia de un desprendimiento previo no es evidencia de estabilidad."],"stop_criterion":"La ausencia de un desprendimiento previo no es evidencia de estabilidad.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":27,"block_number":2,"lesson_ordinal":3,"segment_position":7,"segment_id":"02de303f-099b-54c7-8d0f-dd21ea6374a7","slide_id":"a8eff4a2-148a-5c55-985e-50dd9cdb9c0a","note_id":"bc5f5edf-2b42-52a1-8bf4-9e431dbff91d","title":"TRÁFICO MINERO Y GEOMETRÍA DE PISTAS","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es explicar que la geometría de las pistas es una barrera técnica y debe comprobarse contra proyecto e ITC.\n\nEn este punto conviene fijar las magnitudes reglamentarias. En el desarrollo normal del trabajo, la plataforma debe permitir las maniobras manteniendo una distancia mínima de cinco metros al borde del banco. El arcén entre el borde de la pista o del acceso y el pie o borde inferior de un talud no puede ser menor de dos metros. En una pista de un solo carril, la calzada tendrá como mínimo una vez y media la anchura del vehículo mayor previsto; con tráfico intenso y pesado, dos veces esa anchura; y, en una pista de dos carriles, tres veces la del vehículo más ancho. Las pendientes longitudinales medias de las pistas no deben superar el diez por ciento, con máximos puntuales del quince por ciento.\n\nPensemos en un ejemplo. Anchura, arcenes, distancia al borde, pendiente, radios, visibilidad, drenaje y pretiles forman un sistema. Una cifra aislada no garantiza seguridad si el resto del diseño falla.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La pista debe ser compatible con el vehículo real y con las condiciones reales.","duration_seconds":126,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-027.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-027.jpg","explanation":"Objetivo\n\nExplicar que la geometría de las pistas es una barrera técnica y debe comprobarse contra proyecto e ITC.\n\nExplicación detallada\n\nReglas de interacción vehículo persona. Prohibir presencia en la zona de acción de maquinaria y definir exclusiones visibles. Limitar tránsito peatonal, usar accesos seguros y, en pista, arcén o lado opuesto al tráfico de modo visible. No aproximarse a un volquete cargado en operación normal a menos de cinco metros; si es imprescindible, hacerlo por delante, con comunicación y detención aseguradas. Establecer contacto positivo antes de entrar en una maniobra: el operador confirma que ha visto, detiene y autoriza. Separar vehículos ligeros y pesados; prohibir estacionar en puntos ciegos y definir espera segura. Adaptar operación a polvo, niebla, lluvia, oscuridad o deslumbramiento. Sin visibilidad suficiente se detiene o aplica un sistema autorizado.\n\nLa seguridad vial interna depende del sistema, no solo del conductor. El plan separa flujos, minimiza marcha atrás, dimensiona rutas para el vehículo crítico, mantiene superficie y drenaje, controla velocidad y prioridad y gestiona visitantes. Las cámaras y alarmas ayudan, pero no eliminan un diseño deficiente.\n\nLectura guiada de la diapositiva\n\nELEMENTO CRITERIO REGLAMENTARIO Plataforma Al menos 5 m al borde en trabajo normal. Arcén frente a talud Al menos 2 m; ampliar y proteger si hay desprendimiento. Un carril 1,5 veces el ancho del mayor vehículo; 2 veces con tráfico intenso y pesado. Dos carriles 3 veces el ancho del vehículo más ancho. Pendiente Media ≤ 10 %; máximos puntuales 15 %; acceso especial ≤ 20 %, con medidas específicas. Curvas sin maniobras ni peralte inverso; borde con caída balizado y con tope o barrera. ITC 07.1.03. Comprobar proyecto y disposición interna de seguridad.\n\nAplicación práctica\n\nAnchura, arcenes, distancia al borde, pendiente, radios, visibilidad, drenaje y pretiles forman un sistema. Una cifra aislada no garantiza seguridad si el resto del diseño falla.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa pista debe ser compatible con el vehículo real y con las condiciones reales.","key_points":["Explicar que la geometría de las pistas es una barrera técnica y debe comprobarse contra proyecto e ITC.","La pista debe ser compatible con el vehículo real y con las condiciones reales."],"stop_criterion":"La pista debe ser compatible con el vehículo real y con las condiciones reales.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":28,"block_number":2,"lesson_ordinal":3,"segment_position":8,"segment_id":"958d9204-b715-5d74-89aa-4ae8306b28e6","slide_id":"90e8fd56-0c46-52aa-9146-5c30e10b9960","note_id":"b123de70-35cf-5af9-9c55-c58f93540f91","title":"INTERACCIÓN VEHÍCULO Y PERSONA","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es controlar la interacción entre maquinaria móvil y personas mediante separación y reglas visibles.\n\nReglas de interacción vehículo persona. Prohibir presencia en la zona de acción de maquinaria y definir exclusiones visibles. Limitar tránsito peatonal, usar accesos seguros y, en pista, arcén o lado opuesto al tráfico de modo visible. No aproximarse a un volquete cargado en operación normal a menos de cinco metros; si es imprescindible, hacerlo por delante, con comunicación y detención aseguradas. Establecer contacto positivo antes de entrar en una maniobra: el operador confirma que ha visto, detiene y autoriza. Separar vehículos ligeros y pesados; prohibir estacionar en puntos ciegos y definir espera segura. Adaptar operación a polvo, niebla, lluvia, oscuridad o deslumbramiento.\n\nPensemos en un ejemplo. Un topógrafo que entra en el radio de una cargadora no queda protegido solo por un chaleco. Se necesita exclusión, acceso definido, contacto con el operador y ubicación fuera de puntos ciegos.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La prioridad es evitar que persona y máquina compartan trayectoria.","duration_seconds":125,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-028.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-028.jpg","explanation":"Objetivo\n\nControlar la interacción entre maquinaria móvil y personas mediante separación y reglas visibles.\n\nExplicación detallada\n\nReglas de interacción vehículo persona. Prohibir presencia en la zona de acción de maquinaria y definir exclusiones visibles. Limitar tránsito peatonal, usar accesos seguros y, en pista, arcén o lado opuesto al tráfico de modo visible. No aproximarse a un volquete cargado en operación normal a menos de cinco metros; si es imprescindible, hacerlo por delante, con comunicación y detención aseguradas. Establecer contacto positivo antes de entrar en una maniobra: el operador confirma que ha visto, detiene y autoriza. Separar vehículos ligeros y pesados; prohibir estacionar en puntos ciegos y definir espera segura. Adaptar operación a polvo, niebla, lluvia, oscuridad o deslumbramiento. Sin visibilidad suficiente se detiene o aplica un sistema autorizado.\n\nLa seguridad vial interna depende del sistema, no solo del conductor. El plan separa flujos, minimiza marcha atrás, dimensiona rutas para el vehículo crítico, mantiene superficie y drenaje, controla velocidad y prioridad y gestiona visitantes. Las cámaras y alarmas ayudan, pero no eliminan un diseño deficiente.\n\nLectura guiada de la diapositiva\n\nProhibir presencia en la zona de acción de maquinaria y definir exclusiones visibles. Limitar tránsito peatonal y usar accesos seguros; en pista, arcén o lado opuesto al tráfico. Volquete cargado en operación normal: no acercarse a menos de 5 m. Si es imprescindible, por delante, con comunicación y detención aseguradas. Separar vehículos ligeros y pesados. Adaptar la operación a polvo, niebla, lluvia, oscuridad o deslumbramiento. Manual InmínerCampus · Tráfico minero; comprobar proyecto y disposición interna de seguridad.\n\nAplicación práctica\n\nUn topógrafo que entra en el radio de una cargadora no queda protegido solo por un chaleco. Se necesita exclusión, acceso definido, contacto con el operador y ubicación fuera de puntos ciegos.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa prioridad es evitar que persona y máquina compartan trayectoria.","key_points":["Controlar la interacción entre maquinaria móvil y personas mediante separación y reglas visibles.","La prioridad es evitar que persona y máquina compartan trayectoria."],"stop_criterion":"La prioridad es evitar que persona y máquina compartan trayectoria.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":29,"block_number":2,"lesson_ordinal":3,"segment_position":9,"segment_id":"364a9daf-18b4-58d2-acaf-c74fdc086aa2","slide_id":"429c94b9-a3e7-5223-9668-d9f466c1714a","note_id":"581c547b-d29d-5a47-929c-0ca1d70e3374","title":"CONTACTO POSITIVO Y MARCHA ATRÁS","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es enseñar el contacto positivo antes de entrar en una zona de maniobra o iniciar marcha atrás.\n\nReglas de interacción vehículo persona. Prohibir presencia en la zona de acción de maquinaria y definir exclusiones visibles. Limitar tránsito peatonal, usar accesos seguros y, en pista, arcén o lado opuesto al tráfico de modo visible. No aproximarse a un volquete cargado en operación normal a menos de cinco metros; si es imprescindible, hacerlo por delante, con comunicación y detención aseguradas. Establecer contacto positivo antes de entrar en una maniobra: el operador confirma que ha visto, detiene y autoriza. Separar vehículos ligeros y pesados; prohibir estacionar en puntos ciegos y definir espera segura. Adaptar operación a polvo, niebla, lluvia, oscuridad o deslumbramiento.\n\nPensemos en un ejemplo. La persona solicita acceso desde un lugar visible, el operador detiene y confirma, y solo entonces se autoriza la aproximación. Si se pierde contacto, la maniobra se detiene.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Ver la máquina no significa que el operador haya visto a la persona.","duration_seconds":124,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-029.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-029.jpg","explanation":"Objetivo\n\nEnseñar el contacto positivo antes de entrar en una zona de maniobra o iniciar marcha atrás.\n\nExplicación detallada\n\nReglas de interacción vehículo persona. Prohibir presencia en la zona de acción de maquinaria y definir exclusiones visibles. Limitar tránsito peatonal, usar accesos seguros y, en pista, arcén o lado opuesto al tráfico de modo visible. No aproximarse a un volquete cargado en operación normal a menos de cinco metros; si es imprescindible, hacerlo por delante, con comunicación y detención aseguradas. Establecer contacto positivo antes de entrar en una maniobra: el operador confirma que ha visto, detiene y autoriza. Separar vehículos ligeros y pesados; prohibir estacionar en puntos ciegos y definir espera segura. Adaptar operación a polvo, niebla, lluvia, oscuridad o deslumbramiento. Sin visibilidad suficiente se detiene o aplica un sistema autorizado.\n\nLa seguridad vial interna depende del sistema, no solo del conductor. El plan separa flujos, minimiza marcha atrás, dimensiona rutas para el vehículo crítico, mantiene superficie y drenaje, controla velocidad y prioridad y gestiona visitantes. Las cámaras y alarmas ayudan, pero no eliminan un diseño deficiente.\n\nLectura guiada de la diapositiva\n\nAntes de entrar en una maniobra, el operador: Confirma Detiene Autoriza Confirma que ha visto a la persona. Detiene la maniobra. Autoriza la entrada. Ver la máquina u oír la alarma no basta. El plan de tráfico minimiza la marcha atrás. Sin visibilidad suficiente, detener o aplicar un sistema autorizado. Definir espera segura para peatones y vehículos ligeros.\n\nAplicación práctica\n\nLa persona solicita acceso desde un lugar visible, el operador detiene y confirma, y solo entonces se autoriza la aproximación. Si se pierde contacto, la maniobra se detiene.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nVer la máquina no significa que el operador haya visto a la persona.","key_points":["Enseñar el contacto positivo antes de entrar en una zona de maniobra o iniciar marcha atrás.","Ver la máquina no significa que el operador haya visto a la persona."],"stop_criterion":"Ver la máquina no significa que el operador haya visto a la persona.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":30,"block_number":2,"lesson_ordinal":3,"segment_position":10,"segment_id":"c2be2216-c4b6-526c-9c2d-8a7ce22ae5e4","slide_id":"440cb327-1788-5514-ba56-2e6ab9c456fd","note_id":"be2c3dfa-62ab-5d0e-be50-130e815052ad","title":"PUNTOS CIEGOS","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es explicar los puntos ciegos como limitación de diseño que exige controles redundantes.\n\nLa seguridad vial interna depende del sistema, no solo del conductor. El plan separa flujos, minimiza marcha atrás, dimensiona rutas para el vehículo crítico, mantiene superficie y drenaje, controla velocidad y prioridad y gestiona visitantes. Las cámaras y alarmas ayudan, pero no eliminan un diseño deficiente.\n\nPensemos en un ejemplo. Cámaras, espejos y alarmas ayudan, pero pueden ensuciarse, fallar o no cubrir todo el entorno. El diseño del flujo, las zonas de espera y la eliminación de marcha atrás son más robustos.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Un avisador no convierte una zona ciega en una zona segura.","duration_seconds":124,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-030.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-030.jpg","explanation":"Objetivo\n\nExplicar los puntos ciegos como limitación de diseño que exige controles redundantes.\n\nExplicación detallada\n\nLa seguridad vial interna depende del sistema, no solo del conductor. El plan separa flujos, minimiza marcha atrás, dimensiona rutas para el vehículo crítico, mantiene superficie y drenaje, controla velocidad y prioridad y gestiona visitantes. Las cámaras y alarmas ayudan, pero no eliminan un diseño deficiente.\n\nReglas de interacción vehículo persona. Prohibir presencia en la zona de acción de maquinaria y definir exclusiones visibles. Limitar tránsito peatonal, usar accesos seguros y, en pista, arcén o lado opuesto al tráfico de modo visible. No aproximarse a un volquete cargado en operación normal a menos de cinco metros; si es imprescindible, hacerlo por delante, con comunicación y detención aseguradas. Establecer contacto positivo antes de entrar en una maniobra: el operador confirma que ha visto, detiene y autoriza. Separar vehículos ligeros y pesados; prohibir estacionar en puntos ciegos y definir espera segura. Adaptar operación a polvo, niebla, lluvia, oscuridad o deslumbramiento. Sin visibilidad suficiente se detiene o aplica un sistema autorizado.\n\nLectura guiada de la diapositiva\n\nNo estacionar en puntos ciegos; definir espera segura. Cámaras y alarmas ayudan, pero no eliminan un diseño deficiente. Verificar cristales, espejos, cámaras, radar, luces y limpieza. Una alarma de marcha atrás no sustituye la segregación. Los puntos ciegos de cargadora y volquete son riesgo dominante de atropello.\n\nAplicación práctica\n\nCámaras, espejos y alarmas ayudan, pero pueden ensuciarse, fallar o no cubrir todo el entorno. El diseño del flujo, las zonas de espera y la eliminación de marcha atrás son más robustos.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUn avisador no convierte una zona ciega en una zona segura.","key_points":["Explicar los puntos ciegos como limitación de diseño que exige controles redundantes.","Un avisador no convierte una zona ciega en una zona segura."],"stop_criterion":"Un avisador no convierte una zona ciega en una zona segura.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":31,"block_number":2,"lesson_ordinal":4,"segment_position":1,"segment_id":"55ee238c-84ab-57a3-94eb-8fb336f236df","slide_id":"53acc119-0606-55f3-a8a5-1e991425cbd6","note_id":"cb35d898-dda2-5615-a5fd-b792f2751919","title":"PERFORACIÓN Y VOLADURA: QUÉ COORDINA EL TÉCNICO","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es delimitar qué coordina el técnico alrededor de perforación y voladura sin atribuirle habilitaciones inexistentes.\n\nEn voladuras, el técnico coordina el entorno: información, exclusión, cortes, señales, evacuación, recuento, control de accesos y reanudación. La carga, conexión, disparo y tratamiento de barrenos fallidos corresponden a personal autorizado conforme al Reglamento de Explosivos y a las DIS. Nunca se perfora, manipula o excava en zona con posible barreno fallido sin identificación y autorización específicas.\n\nPensemos en un ejemplo. El técnico verifica terreno, estabilidad, accesos, interferencias, horario, meteorología, evacuación y recuento. La manipulación de explosivos corresponde al personal habilitado.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Coordinar el entorno de una voladura no convierte a nadie en artillero.","duration_seconds":134,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-031.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-031.jpg","explanation":"Objetivo\n\nDelimitar qué coordina el técnico alrededor de perforación y voladura sin atribuirle habilitaciones inexistentes.\n\nExplicación detallada\n\nEn voladuras, el técnico coordina el entorno: información, exclusión, cortes, señales, evacuación, recuento, control de accesos y reanudación. La carga, conexión, disparo y tratamiento de barrenos fallidos corresponden a personal autorizado conforme al Reglamento de Explosivos y a las DIS. Nunca se perfora, manipula o excava en zona con posible barreno fallido sin identificación y autorización específicas.\n\nLectura guiada de la diapositiva\n\nPerforación Antes Área reconocida, estable y preparada; equipo Plan autorizado, área, horario, interferencias, frenado o bloqueado; captación de polvo integrada meteorología, accesos, refugios y recuento. en el método. Exclusión Tras el disparo Barreras, vigilantes, comunicación y equipos Tiempo prescrito, inspección autorizada, humos y retirados. estabilidad. Carga, conexión y disparo corresponden a personal autorizado. El curso no habilita como artillero. Real Decreto 130/2017.\n\nAplicación práctica\n\nEl técnico verifica terreno, estabilidad, accesos, interferencias, horario, meteorología, evacuación y recuento. La manipulación de explosivos corresponde al personal habilitado.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nCoordinar el entorno de una voladura no convierte a nadie en artillero.","key_points":["Delimitar qué coordina el técnico alrededor de perforación y voladura sin atribuirle habilitaciones inexistentes.","Coordinar el entorno de una voladura no convierte a nadie en artillero."],"stop_criterion":"Coordinar el entorno de una voladura no convierte a nadie en artillero.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":32,"block_number":2,"lesson_ordinal":4,"segment_position":2,"segment_id":"55456e1f-6069-54a8-bc42-1bc273df8253","slide_id":"cd258529-9217-5a06-aa1b-821a785741bc","note_id":"622f750b-1dba-5b21-9fbb-e60a0dd2b10f","title":"BARRENO SOSPECHOSO: EXCLUIR Y AVISAR","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es fijar una respuesta inequívoca ante un barreno sospechoso o fallido.\n\nEn voladuras, el técnico coordina el entorno: información, exclusión, cortes, señales, evacuación, recuento, control de accesos y reanudación. La carga, conexión, disparo y tratamiento de barrenos fallidos corresponden a personal autorizado conforme al Reglamento de Explosivos y a las DIS. Nunca se perfora, manipula o excava en zona con posible barreno fallido sin identificación y autorización específicas.\n\nPensemos en un ejemplo. Si aparece una perforación, cable, detonador o zona dudosa, se detiene la excavación, se mantiene distancia, se señaliza y se avisa por el canal previsto. Nadie investiga manipulando.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La duda se gestiona como barreno fallido hasta que personal autorizado determine lo contrario.","duration_seconds":133,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-032.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-032.jpg","explanation":"Objetivo\n\nFijar una respuesta inequívoca ante un barreno sospechoso o fallido.\n\nExplicación detallada\n\nEn voladuras, el técnico coordina el entorno: información, exclusión, cortes, señales, evacuación, recuento, control de accesos y reanudación. La carga, conexión, disparo y tratamiento de barrenos fallidos corresponden a personal autorizado conforme al Reglamento de Explosivos y a las DIS. Nunca se perfora, manipula o excava en zona con posible barreno fallido sin identificación y autorización específicas.\n\nLectura guiada de la diapositiva\n\nNunca perforar, manipular o excavar en una zona con posible barreno fallido sin identificación y autorización específicas. Mantener la exclusión e impedir improvisaciones. Aplicar el procedimiento de barreno fallido por personal autorizado, conforme al Reglamento de Explosivos y a las disposición interna de seguridad. El técnico coordina y delimita; no sustituye al artillero. Reglamento de Explosivos y disposición interna de seguridad del centro.\n\nAplicación práctica\n\nSi aparece una perforación, cable, detonador o zona dudosa, se detiene la excavación, se mantiene distancia, se señaliza y se avisa por el canal previsto. Nadie investiga manipulando.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa duda se gestiona como barreno fallido hasta que personal autorizado determine lo contrario.","key_points":["Fijar una respuesta inequívoca ante un barreno sospechoso o fallido.","La duda se gestiona como barreno fallido hasta que personal autorizado determine lo contrario."],"stop_criterion":"La duda se gestiona como barreno fallido hasta que personal autorizado determine lo contrario.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":33,"block_number":2,"lesson_ordinal":4,"segment_position":3,"segment_id":"c637e0fc-7dcc-5324-9cd8-2d7eb692d2b3","slide_id":"0ad89249-c024-5ca3-ab33-c12120001a65","note_id":"ffef0787-255c-5f3d-81a8-87f0f6d1382d","title":"MANTENIMIENTO Y ENERGÍAS PELIGROSAS","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es mostrar todas las formas de energía peligrosa que pueden permanecer tras detener un equipo.\n\nLa parada de un mando no elimina energía. Un equipo puede conservar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica, material atascado o energía gravitatoria. La consignación transforma el equipo en una condición controlada y verificable antes de intervenir. 1. Preparar: identificar alcance, fuentes, aislamiento, personas afectadas y estado seguro. 2. Parar de forma normal y comunicar la intervención. 3. Separar o aislar todas las fuentes de energía. 4. Bloquear los órganos de aislamiento e identificar al titular según procedimiento. 5. Disipar, descargar, purgar, enfriar, calzar o soportar energías acumuladas. 6.\n\nPensemos en un ejemplo. Además de electricidad, existen presión hidráulica y neumática, gravedad, tensión mecánica, calor, rotación, material almacenado y posibilidad de reenergización remota.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Poner un mando a cero no equivale a aislar.","duration_seconds":125,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-033.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-033.jpg","explanation":"Objetivo\n\nMostrar todas las formas de energía peligrosa que pueden permanecer tras detener un equipo.\n\nExplicación detallada\n\nLa parada de un mando no elimina energía. Un equipo puede conservar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica, material atascado o energía gravitatoria. La consignación transforma el equipo en una condición controlada y verificable antes de intervenir. 1. Preparar: identificar alcance, fuentes, aislamiento, personas afectadas y estado seguro. 2. Parar de forma normal y comunicar la intervención. 3. Separar o aislar todas las fuentes de energía. 4. Bloquear los órganos de aislamiento e identificar al titular según procedimiento. 5. Disipar, descargar, purgar, enfriar, calzar o soportar energías acumuladas. 6. Verificar ausencia de energía con método adecuado, incluida prueba de intento cuando proceda. 7. Ejecutar manteniendo control de herramientas, piezas y cambios de alcance. 8. Reponer protecciones, retirar personas y materiales y retirar bloqueos con control. 9. Comunicar y reenergizar; comprobar funcionamiento seguro. Principio clave. Una etiqueta informa; un bloqueo eficaz impide la maniobra. La verificación demuestra que el aislamiento funciona. No deben confundirse.\n\nLectura guiada de la diapositiva\n\nParar un mando no elimina la energía Puede quedar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica o material atascado. La consignación convierte el equipo en una condición controlada y verificable. Una etiqueta informa. Un bloqueo eficaz impide la maniobra. La verificación demuestra que funciona.\n\nAplicación práctica\n\nAdemás de electricidad, existen presión hidráulica y neumática, gravedad, tensión mecánica, calor, rotación, material almacenado y posibilidad de reenergización remota.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nPoner un mando a cero no equivale a aislar.","key_points":["Mostrar todas las formas de energía peligrosa que pueden permanecer tras detener un equipo.","Poner un mando a cero no equivale a aislar."],"stop_criterion":"Poner un mando a cero no equivale a aislar.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":34,"block_number":2,"lesson_ordinal":4,"segment_position":4,"segment_id":"1c303a78-4bdb-5db5-9957-0e8f76234bf6","slide_id":"22a4a11a-9a68-5a21-9c39-70afe080fafc","note_id":"6f228ce6-f086-5e51-b178-3aa3ae5c2407","title":"CONSIGNACIÓN EN NUEVE PASOS","narration_text":"Esta diapositiva propone mirar el trabajo con criterio técnico y no por costumbre. Nuestro objetivo es explicar una consignación completa en nueve pasos y la responsabilidad individual sobre el bloqueo.\n\nLa parada de un mando no elimina energía. Un equipo puede conservar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica, material atascado o energía gravitatoria. La consignación transforma el equipo en una condición controlada y verificable antes de intervenir. 1. Preparar: identificar alcance, fuentes, aislamiento, personas afectadas y estado seguro. 2. Parar de forma normal y comunicar la intervención. 3. Separar o aislar todas las fuentes de energía. 4. Bloquear los órganos de aislamiento e identificar al titular según procedimiento. 5. Disipar, descargar, purgar, enfriar, calzar o soportar energías acumuladas. 6.\n\nPensemos en un ejemplo. Preparar, parar, aislar, bloquear e identificar, disipar, verificar, ejecutar, probar de forma controlada y retirar bloqueos son una secuencia. Saltar la verificación deja una suposición en el centro del trabajo.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: El estado de energía cero debe demostrarse antes de tocar.","duration_seconds":135,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-034.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-034.jpg","explanation":"Objetivo\n\nExplicar una consignación completa en nueve pasos y la responsabilidad individual sobre el bloqueo.\n\nExplicación detallada\n\nLa parada de un mando no elimina energía. Un equipo puede conservar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica, material atascado o energía gravitatoria. La consignación transforma el equipo en una condición controlada y verificable antes de intervenir. 1. Preparar: identificar alcance, fuentes, aislamiento, personas afectadas y estado seguro. 2. Parar de forma normal y comunicar la intervención. 3. Separar o aislar todas las fuentes de energía. 4. Bloquear los órganos de aislamiento e identificar al titular según procedimiento. 5. Disipar, descargar, purgar, enfriar, calzar o soportar energías acumuladas. 6. Verificar ausencia de energía con método adecuado, incluida prueba de intento cuando proceda. 7. Ejecutar manteniendo control de herramientas, piezas y cambios de alcance. 8. Reponer protecciones, retirar personas y materiales y retirar bloqueos con control. 9. Comunicar y reenergizar; comprobar funcionamiento seguro. Principio clave. Una etiqueta informa; un bloqueo eficaz impide la maniobra. La verificación demuestra que el aislamiento funciona. No deben confundirse.\n\nLectura guiada de la diapositiva\n\nPreparar alcance, fuentes, aislamiento y personas. 2 Parar de forma normal y comunicar. Separar o aislar todas las fuentes de energía. 4 Bloquear órganos de aislamiento e identificar al titular. Disipar, descargar, purgar, enfriar, calzar o 6 Verificar ausencia de energía; prueba de intento soportar energías acumuladas. cuando proceda. Ejecutar controlando herramientas, piezas y 8 Reponer protecciones y retirar bloqueos con cambios de alcance. control. Comunicar, reenergizar y comprobar. Referencia técnica: INSST, NTP 1117.\n\nAplicación práctica\n\nPreparar, parar, aislar, bloquear e identificar, disipar, verificar, ejecutar, probar de forma controlada y retirar bloqueos son una secuencia. Saltar la verificación deja una suposición en el centro del trabajo.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl estado de energía cero debe demostrarse antes de tocar.","key_points":["Explicar una consignación completa en nueve pasos y la responsabilidad individual sobre el bloqueo.","El estado de energía cero debe demostrarse antes de tocar."],"stop_criterion":"El estado de energía cero debe demostrarse antes de tocar.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":35,"block_number":2,"lesson_ordinal":4,"segment_position":5,"segment_id":"882f0a4d-00ff-5159-997b-a98d299cfc7c","slide_id":"9c7c1c7d-0457-513a-9fe6-a918f7e720e1","note_id":"451095dd-2ae8-5fcb-a939-8abdc9068851","title":"ACTIVIDAD DEL ALUMNO · 15 MINUTOS","narration_text":"Llegamos a una actividad práctica de aproximadamente 15 minutos. El objetivo es dirigir el caso del atasco en una cinta con tensión, material y rearme remoto.\n\nLa situación de trabajo es esta. CASO 2B. ATASCO EN UNA CINTA Una cinta se detiene por atasco. El mando está en cero, la banda conserva tensión, hay material sobre ella y otro trabajador puede rearmar desde un cuadro remoto. Definir consignación y verificaciones Puesta en común tras el trabajo del grupo. Alcance con equipos aguas arriba y abajo. Bloqueos. Energía mecánica estabilizada. Ausencia de energía verificada.\n\nPara orientar el análisis, considera este encuadre. El alumno debe identificar energía eléctrica, tensión de banda, gravedad del material y acción de terceros; proponer aislamiento aguas arriba y abajo y definir una prueba de ausencia de energía.\n\nTrabaja en este orden. Primero separa hechos de suposiciones. Después identifica la energía o condición peligrosa, su trayectoria y las personas expuestas. A continuación propone una medida inmediata para retirar la exposición y otra que corrija la causa. Termina indicando quién decide, qué debe comprobarse y qué condición permite reabrir. Evita respuestas genéricas como tener cuidado o señalizar sin explicar qué barrera controla el escenario.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén ahora la reproducción y realiza la actividad. Conserva tu respuesta para compararla con la resolución posterior. El atasco se libera solo cuando todas las fuentes están controladas.","duration_seconds":129,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-035.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-035.jpg","explanation":"Objetivo\n\nDirigir el caso del atasco en una cinta con tensión, material y rearme remoto.\n\nExplicación detallada\n\nLa parada de un mando no elimina energía. Un equipo puede conservar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica, material atascado o energía gravitatoria. La consignación transforma el equipo en una condición controlada y verificable antes de intervenir. 1. Preparar: identificar alcance, fuentes, aislamiento, personas afectadas y estado seguro. 2. Parar de forma normal y comunicar la intervención. 3. Separar o aislar todas las fuentes de energía. 4. Bloquear los órganos de aislamiento e identificar al titular según procedimiento. 5. Disipar, descargar, purgar, enfriar, calzar o soportar energías acumuladas. 6. Verificar ausencia de energía con método adecuado, incluida prueba de intento cuando proceda. 7. Ejecutar manteniendo control de herramientas, piezas y cambios de alcance. 8. Reponer protecciones, retirar personas y materiales y retirar bloqueos con control. 9. Comunicar y reenergizar; comprobar funcionamiento seguro. Principio clave. Una etiqueta informa; un bloqueo eficaz impide la maniobra. La verificación demuestra que el aislamiento funciona. No deben confundirse.\n\nLectura guiada de la diapositiva\n\nCASO 2B. ATASCO EN UNA CINTA Una cinta se detiene por atasco. El mando está en cero, la banda conserva tensión, hay material sobre ella y otro trabajador puede rearmar desde un cuadro remoto. Definir consignación y verificaciones Puesta en común tras el trabajo del grupo. Alcance con equipos aguas arriba y abajo. Bloqueos. Energía mecánica estabilizada. Ausencia de energía verificada.\n\nAplicación práctica\n\nEl alumno debe identificar energía eléctrica, tensión de banda, gravedad del material y acción de terceros; proponer aislamiento aguas arriba y abajo y definir una prueba de ausencia de energía.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl atasco se libera solo cuando todas las fuentes están controladas.","key_points":["Dirigir el caso del atasco en una cinta con tensión, material y rearme remoto.","El atasco se libera solo cuando todas las fuentes están controladas."],"stop_criterion":"El atasco se libera solo cuando todas las fuentes están controladas.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":36,"block_number":2,"lesson_ordinal":4,"segment_position":6,"segment_id":"5f2da823-2c67-54a8-85aa-8135afb0735d","slide_id":"34283ffe-9165-59de-877d-2fba3186a033","note_id":"ac38aabb-236e-5470-b201-64b60ba47ee3","title":"POLVO Y SÍLICE CRISTALINA RESPIRABLE (SCR)","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es explicar por qué el polvo visible no representa toda la exposición a sílice cristalina respirable.\n\nEl polvo visible indica emisión, pero la fracción respirable no se valora a simple vista. La SCR puede generarse en perforación, arranque, trituración, transferencia, limpieza, circulación y mantenimiento. Los trabajos con exposición a polvo de sílice respirable generado por un proceso de trabajo están incluidos en el marco de agentes cancerígenos; la estrategia debe reducir la exposición al nivel más bajo técnicamente posible. INSST publica para la sílice cristalina respirable un VLA-ED de 0,05 mg/m³. El cumplimiento no se presume por usar mascarilla o riego: requiere muestreo representativo, método reconocido, interpretación y acciones ante desviaciones.\n\nPensemos en un ejemplo. Las partículas respirables pueden permanecer suspendidas y penetrar profundamente sin formar una nube espectacular. Perforación, trituración, transferencia y limpieza son focos principales.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: No se evalúa la exposición mirando únicamente el aire.","duration_seconds":130,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-036.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-036.jpg","explanation":"Objetivo\n\nExplicar por qué el polvo visible no representa toda la exposición a sílice cristalina respirable.\n\nExplicación detallada\n\nEl polvo visible indica emisión, pero la fracción respirable no se valora a simple vista. La SCR puede generarse en perforación, arranque, trituración, transferencia, limpieza, circulación y mantenimiento. Los trabajos con exposición a polvo de sílice respirable generado por un proceso de trabajo están incluidos en el marco de agentes cancerígenos; la estrategia debe reducir la exposición al nivel más bajo técnicamente posible.\n\nINSST publica para la sílice cristalina respirable un VLA-ED de 0,05 mg/m³. El cumplimiento no se presume por usar mascarilla o riego: requiere muestreo representativo, método reconocido, interpretación y acciones ante desviaciones.\n\nLectura guiada de la diapositiva\n\nEl polvo visible indica emisión, pero la fracción respirable no se valora a simple vista. Se genera en perforación, arranque, trituración, transferencia, limpieza, circulación y mantenimiento. El marco de agentes cancerígenos exige reducir la exposición al nivel más bajo técnicamente posible. Valor límite ambiental de exposición diaria (VLA-ED), publicado por el INSST: 0,05 mg/m³. Se exige muestreo representativo, método reconocido y acciones ante desviaciones. No se presume cumplimiento por usar mascarilla o riego. ITC 02.0.02; INSST.\n\nAplicación práctica\n\nLas partículas respirables pueden permanecer suspendidas y penetrar profundamente sin formar una nube espectacular. Perforación, trituración, transferencia y limpieza son focos principales.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nNo se evalúa la exposición mirando únicamente el aire.","key_points":["Explicar por qué el polvo visible no representa toda la exposición a sílice cristalina respirable.","No se evalúa la exposición mirando únicamente el aire."],"stop_criterion":"No se evalúa la exposición mirando únicamente el aire.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":37,"block_number":2,"lesson_ordinal":4,"segment_position":7,"segment_id":"d8e00672-ba84-56ff-bf27-7d14153ddc86","slide_id":"8ee33bea-5a17-5a45-8549-2f9b33ff60de","note_id":"7ce7c391-c663-5eb3-8ad1-c361986efd10","title":"CONTROLAR EL POLVO EN CUATRO NIVELES","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es aplicar controles de polvo en fuente, trayectoria, organización y persona.\n\nINSST publica para la sílice cristalina respirable un VLA-ED de 0,05 mg/m³. El cumplimiento no se presume por usar mascarilla o riego: requiere muestreo representativo, método reconocido, interpretación y acciones ante desviaciones. El polvo visible indica emisión, pero la fracción respirable no se valora a simple vista. La SCR puede generarse en perforación, arranque, trituración, transferencia, limpieza, circulación y mantenimiento. Los trabajos con exposición a polvo de sílice respirable generado por un proceso de trabajo están incluidos en el marco de agentes cancerígenos; la estrategia debe reducir la exposición al nivel más bajo técnicamente posible.\n\nPensemos en un ejemplo. Método húmedo, captación, cerramiento y automatización actúan en origen; cabinas filtradas y separación controlan trayectoria; mantenimiento y limpieza sostienen la eficacia; el respirador queda como complemento.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Una mascarilla no compensa una captación averiada o una cabina con fugas.","duration_seconds":129,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-037.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-037.jpg","explanation":"Objetivo\n\nAplicar controles de polvo en fuente, trayectoria, organización y persona.\n\nExplicación detallada\n\nINSST publica para la sílice cristalina respirable un VLA-ED de 0,05 mg/m³. El cumplimiento no se presume por usar mascarilla o riego: requiere muestreo representativo, método reconocido, interpretación y acciones ante desviaciones.\n\nEl polvo visible indica emisión, pero la fracción respirable no se valora a simple vista. La SCR puede generarse en perforación, arranque, trituración, transferencia, limpieza, circulación y mantenimiento. Los trabajos con exposición a polvo de sílice respirable generado por un proceso de trabajo están incluidos en el marco de agentes cancerígenos; la estrategia debe reducir la exposición al nivel más bajo técnicamente posible.\n\nLectura guiada de la diapositiva\n\nFuente Trayectoria Método húmedo, captación localizada, cerramiento, Cabinas cerradas y filtradas, ventilación, automatización, filtros mantenidos y menos caída segregación, estabilización de viales y limpieza sin libre. redispersar. Organización Persona Plan de medición, zonas, tiempos, mantenimiento, Protección respiratoria seleccionada por evaluación, señalización, formación y vigilancia de salud. con ajuste, compatibilidad y conservación.\n\nAplicación práctica\n\nMétodo húmedo, captación, cerramiento y automatización actúan en origen; cabinas filtradas y separación controlan trayectoria; mantenimiento y limpieza sostienen la eficacia; el respirador queda como complemento.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna mascarilla no compensa una captación averiada o una cabina con fugas.","key_points":["Aplicar controles de polvo en fuente, trayectoria, organización y persona.","Una mascarilla no compensa una captación averiada o una cabina con fugas."],"stop_criterion":"Una mascarilla no compensa una captación averiada o una cabina con fugas.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":38,"block_number":2,"lesson_ordinal":4,"segment_position":8,"segment_id":"3830bd89-269b-53da-8225-f1ae8ae803ba","slide_id":"9d9f939f-84a5-560f-83f2-6dd3039b00b6","note_id":"bdda1f03-e599-5686-a712-c0fcd007ed31","title":"RUIDO, VIBRACIONES Y CALOR","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es integrar ruido, vibraciones y calor en la planificación diaria y no tratarlos como molestias menores.\n\nLos valores de acción diarios publicados para vibraciones son 2,5 m/s² para mano-brazo y 0,5 m/s² para cuerpo entero; los límites son 5 m/s² y 1,15 m/s². Su aplicación exige calcular la exposición y no comparar una lectura instantánea sin contexto. WBGT cuando proceda y signos Calor y sol aclimatación, pausas, horario y ola de calor. precoces. vigilancia mutua.\n\nPensemos en un ejemplo. Un operador puede acumular ruido, vibración de cuerpo entero y carga térmica durante el mismo turno. Mantenimiento, asiento, velocidad, pausas, sombra e hidratación deben coordinarse.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La exposición total depende de intensidad, duración y condiciones de la persona.","duration_seconds":140,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-038.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-038.jpg","explanation":"Objetivo\n\nIntegrar ruido, vibraciones y calor en la planificación diaria y no tratarlos como molestias menores.\n\nExplicación detallada\n\nLos valores de acción diarios publicados para vibraciones son 2,5 m/s² para mano-brazo y 0,5 m/s² para cuerpo entero; los límites son 5 m/s² y 1,15 m/s². Su aplicación exige calcular la exposición y no comparar una lectura instantánea sin contexto.\n\nWBGT cuando proceda y signos Calor y sol aclimatación, pausas, horario y ola de calor. precoces. vigilancia mutua.\n\nLectura guiada de la diapositiva\n\nEXPOSICIÓN CONTROL Y CRITERIO Ruido Equipos menos ruidosos, encapsulado, silenciadores, mantenimiento, distancia y tiempo. El equipo de protección individual complementa. Vibración de cuerpo entero Máquina y asiento adecuados. Acción: 0,5 m/s²; límite: 1,15 m/s². Vibración mano-brazo Herramienta adecuada. Acción: 2,5 m/s²; límite: 5 m/s². Calor y sol Sombra, climatización, agua, aclimatación, pausas y WBGT (índice de temperatura de globo y bulbo húmedo), cuando proceda. Se evalúa la exposición A(8), normalizada a ocho horas, no una lectura instantánea.\n\nAplicación práctica\n\nUn operador puede acumular ruido, vibración de cuerpo entero y carga térmica durante el mismo turno. Mantenimiento, asiento, velocidad, pausas, sombra e hidratación deben coordinarse.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa exposición total depende de intensidad, duración y condiciones de la persona.","key_points":["Integrar ruido, vibraciones y calor en la planificación diaria y no tratarlos como molestias menores.","La exposición total depende de intensidad, duración y condiciones de la persona."],"stop_criterion":"La exposición total depende de intensidad, duración y condiciones de la persona.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":39,"block_number":2,"lesson_ordinal":4,"segment_position":9,"segment_id":"90866cf5-50b3-56e3-9a74-a1ecb121947e","slide_id":"11f0ce44-af84-540f-8875-ec25ab5042d8","note_id":"399b73f3-6b24-58ee-8c73-1d55ae75f355","title":"ELECTRICIDAD, INCENDIO Y SUSTANCIAS","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es desarrollar electricidad, líneas aéreas, incendio y sustancias con criterios claros de parada.\n\nPara un trabajo sin tensión, una vez identificados la zona y los elementos de la instalación, la secuencia reglamentaria contiene cinco etapas: desconectar; prevenir cualquier posible realimentación; verificar la ausencia de tensión; poner a tierra y en cortocircuito; y proteger frente a elementos próximos en tensión, cuando existan, estableciendo además la señalización que delimita la zona de trabajo. Hasta completar las cinco etapas no se autoriza el inicio y la parte afectada se considera en tensión. Las maniobras corresponden a personal autorizado y, en alta tensión, a personal cualificado.\n\nPensemos en un ejemplo. Una caja elevada puede invadir la distancia de seguridad de una línea; una fuga de combustible puede alcanzar una fuente caliente. Para trabajos sin tensión deben cumplirse las cinco reglas de oro completas.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La energía eléctrica y el fuego exigen distancias, aislamiento y personal competente.","duration_seconds":120,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-039.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-039.jpg","explanation":"Objetivo\n\nDesarrollar electricidad, líneas aéreas, incendio y sustancias con criterios claros de parada.\n\nExplicación detallada\n\nLas líneas aéreas pueden alcanzarse con cajas elevadas, brazos, perforadoras, grúas, tuberías o cargas. El control preferente es eliminar la posibilidad mediante trazado, gálibo y pasos preparados. La ITC minera fija reglas para cruces y proximidades; el trabajo excepcional exige desconexión y puesta a tierra o una DIS específica con distancias y supervisión. No debe estimarse una distancia a ojo desde la cabina. Inventariar líneas, tensión, gálibos, puntos de cruce y equipos desplegables. Señalizar con anticipación y utilizar limitadores o barreras físicas cuando proceda. Coordinar con el titular y confirmar el estado eléctrico antes de intervenir.\n\nAplicar las reglas de trabajo sin tensión por personal autorizado: desconectar, impedir realimentación, verificar ausencia, poner a tierra cuando proceda y proteger frente a proximidades. Tratar cables dañados, cuadros abiertos, protecciones disparadas y tierras defectuosas como condiciones de parada.\n\nLa prevención combina separación de fuentes de ignición, almacenamiento compatible, contención de derrames, ventilación, orden, mantenimiento y respuesta. El combustible pulverizado sobre una superficie caliente, una manguera hidráulica rota o una batería dañada pueden iniciar un incendio rápido. El extintor no compensa una fuga activa o una evacuación imposible.\n\nLectura guiada de la diapositiva\n\nLas líneas aéreas pueden alcanzarse con cajas elevadas, brazos, perforadoras, grúas o cargas. Inventariar líneas, tensión, gálibos y cruces. No estimar una distancia a ojo desde la cabina. Trabajo sin tensión por personal autorizado: desconectar, impedir realimentación, verificar ausencia y poner a tierra. Ante incendio: separar fuentes de ignición, almacenamiento compatible y contención de derrames. El extintor no compensa una fuga activa. Real Decreto 614/2001. Condiciones de trabajo según evaluación y personal autorizado.\n\nAplicación práctica\n\nUna caja elevada puede invadir la distancia de seguridad de una línea; una fuga de combustible puede alcanzar una fuente caliente. Para trabajos sin tensión deben cumplirse las cinco reglas de oro completas.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa energía eléctrica y el fuego exigen distancias, aislamiento y personal competente.","key_points":["Desarrollar electricidad, líneas aéreas, incendio y sustancias con criterios claros de parada.","La energía eléctrica y el fuego exigen distancias, aislamiento y personal competente."],"stop_criterion":"La energía eléctrica y el fuego exigen distancias, aislamiento y personal competente.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":40,"block_number":2,"lesson_ordinal":4,"segment_position":10,"segment_id":"ac4a8dff-11f0-5a9a-8bc7-2e92c17079d4","slide_id":"fd73e050-73d0-59c2-9aa2-5ed6dcbc06d7","note_id":"50fe7c7e-f768-59d9-bf33-3557b52251e5","title":"EMERGENCIAS, PRIMEROS AUXILIOS Y CIERRE","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es explicar la respuesta de emergencia con la secuencia proteger, avisar, socorrer, recibir y preservar.\n\nLa primera obligación es no crear una segunda víctima. Quien detecta la emergencia para si puede hacerlo con seguridad, avisa por el canal previsto, da ubicación inequívoca, naturaleza, afectados y riesgos activos, y mantiene accesos libres. Solo interviene dentro de su competencia y con protección adecuada. 1. Proteger: reconocer energía, tráfico, caída de rocas, electricidad, fuego, atmósfera y acceso. Aislar sin exponerse. 2. Avisar: activar el plan e indicar ubicación, tipo de incidente, afectados, riesgos y mejor acceso. 3. Socorrer: valorar consciencia y respiración, seguir instrucciones y aplicar primeros auxilios dentro de la formación. 4.\n\nPensemos en un ejemplo. Antes de acercarse a una víctima se comprueban tráfico, rocas, electricidad, fuego y atmósfera. Después se activa el plan con ubicación exacta y se guía a los servicios externos.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Ayudar nunca debe crear una segunda víctima.","duration_seconds":126,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-040.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-040.jpg","explanation":"Objetivo\n\nExplicar la respuesta de emergencia con la secuencia proteger, avisar, socorrer, recibir y preservar.\n\nExplicación detallada\n\nLa primera obligación es no crear una segunda víctima. Quien detecta la emergencia para si puede hacerlo con seguridad, avisa por el canal previsto, da ubicación inequívoca, naturaleza, afectados y riesgos activos, y mantiene accesos libres. Solo interviene dentro de su competencia y con protección adecuada. 1. Proteger: reconocer energía, tráfico, caída de rocas, electricidad, fuego, atmósfera y acceso. Aislar sin exponerse. 2. Avisar: activar el plan e indicar ubicación, tipo de incidente, afectados, riesgos y mejor acceso. 3. Socorrer: valorar consciencia y respiración, seguir instrucciones y aplicar primeros auxilios dentro de la formación. 4. Recibir: designar guía para servicios externos y facilitar información de sustancias, energías y terreno. 5. Preservar y aprender: controlar la zona, conservar evidencias cuando sea compatible y comunicar. Nunca. Entrar en una tolva, hueco, atmósfera sospechosa, zona eléctrica, frente inestable, balsa o equipo sin control de energía para un rescate improvisado.\n\nLectura guiada de la diapositiva\n\nProteger Avisar Socorrer Reconocer energía, tráfico, rocas, Ubicación, tipo, afectados, riesgos y Consciencia y respiración, dentro de electricidad, fuego, atmósfera y mejor acceso. la formación. acceso. Recibir Preservar y aprender Guía a servicios externos e información de sustancias y Controlar la zona y comunicar. energías. Nunca entrar en tolva, hueco o atmósfera sospechosa para un rescate improvisado. Cierre sin energías, huecos, derrames ni defectos para el siguiente turno.\n\nAplicación práctica\n\nAntes de acercarse a una víctima se comprueban tráfico, rocas, electricidad, fuego y atmósfera. Después se activa el plan con ubicación exacta y se guía a los servicios externos.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nAyudar nunca debe crear una segunda víctima.","key_points":["Explicar la respuesta de emergencia con la secuencia proteger, avisar, socorrer, recibir y preservar.","Ayudar nunca debe crear una segunda víctima."],"stop_criterion":"Ayudar nunca debe crear una segunda víctima.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":41,"block_number":2,"lesson_ordinal":5,"segment_position":1,"segment_id":"89b2fd56-aaee-55d6-b43d-f6cd13e1b0ec","slide_id":"14959a0c-fec9-531b-bf29-7afeeb261da1","note_id":"d1bb4483-4af1-5903-a3b1-688e137942b5","title":"BLOQUE 2. COMPROBACIÓN","narration_text":"Vamos a comprobar el aprendizaje del bloque. Justifica cada respuesta relacionando peligro, exposición, control y evidencia de campo.\n\nEstas son las cuestiones que debes resolver. 1. Ordena: bloquear, verificar, aislar, disipar energía. 2. Razona si es verdadero o falso: «Una alarma de marcha atrás elimina el punto ciego». 3. Señala tres riesgos en una pista con borde sin protección. 4. Detecta el error: se desatasca una cinta con el mando en cero y sin bloqueo. 5. Decide ante una grieta nueva en coronación tras la lluvia.\n\nUtiliza este ejemplo para comprobar tu criterio. Ordenar aislar, bloquear, disipar y verificar revela si el alumno entiende el estado seguro. Negar que una alarma elimine un punto ciego evita confiar en una sola ayuda.\n\nHaz una pausa después de cada pregunta. Si dos opciones parecen posibles, elige la que elimine antes la exposición, dependa menos de la conducta y permita verificar su eficacia. En una secuencia, conserva el orden del trabajo seguro. Anota también el error más peligroso y la consecuencia que produciría; así evitarás acertar simplemente por descarte.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén la reproducción, responde por escrito y explica por qué descartas las demás opciones. Después continúa con la resolución razonada. La comprobación debe centrarse en decisiones críticas.","duration_seconds":120,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-041.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-041.jpg","explanation":"Objetivo\n\nComprobar consignación, puntos ciegos, polvo y emergencias mediante preguntas razonadas.\n\nExplicación detallada\n\nLa parada de un mando no elimina energía. Un equipo puede conservar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica, material atascado o energía gravitatoria. La consignación transforma el equipo en una condición controlada y verificable antes de intervenir. 1. Preparar: identificar alcance, fuentes, aislamiento, personas afectadas y estado seguro. 2. Parar de forma normal y comunicar la intervención. 3. Separar o aislar todas las fuentes de energía. 4. Bloquear los órganos de aislamiento e identificar al titular según procedimiento. 5. Disipar, descargar, purgar, enfriar, calzar o soportar energías acumuladas. 6. Verificar ausencia de energía con método adecuado, incluida prueba de intento cuando proceda. 7. Ejecutar manteniendo control de herramientas, piezas y cambios de alcance. 8. Reponer protecciones, retirar personas y materiales y retirar bloqueos con control. 9. Comunicar y reenergizar; comprobar funcionamiento seguro. Principio clave. Una etiqueta informa; un bloqueo eficaz impide la maniobra. La verificación demuestra que el aislamiento funciona. No deben confundirse.\n\nLectura guiada de la diapositiva\n\n1. Ordena: bloquear, verificar, aislar, disipar energía. 2. Razona si es verdadero o falso: «Una alarma de marcha atrás elimina el punto ciego». 3. Señala tres riesgos en una pista con borde sin protección. 4. Detecta el error: se desatasca una cinta con el mando en cero y sin bloqueo. 5. Decide ante una grieta nueva en coronación tras la lluvia.\n\nAplicación práctica\n\nOrdenar aislar, bloquear, disipar y verificar revela si el alumno entiende el estado seguro. Negar que una alarma elimine un punto ciego evita confiar en una sola ayuda.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa comprobación debe centrarse en decisiones críticas.","key_points":["Comprobar consignación, puntos ciegos, polvo y emergencias mediante preguntas razonadas.","La comprobación debe centrarse en decisiones críticas."],"stop_criterion":"La comprobación debe centrarse en decisiones críticas.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":42,"block_number":2,"lesson_ordinal":5,"segment_position":2,"segment_id":"755a230d-982a-59e0-80ad-d666aef68e38","slide_id":"572c4631-06a5-5810-99d9-3961f8a5af6f","note_id":"700ebb7f-a75d-5b8f-8aea-4ae836458d8d","title":"BLOQUE 2. RESOLUCIONES Y RESPUESTAS","narration_text":"Vamos a revisar la resolución. Lo importante es comprobar que la decisión retira la exposición inmediata, trata la causa y define cómo se recupera una condición segura.\n\nLa respuesta propuesta se desarrolla así. Caso 2A No trabajar bajo la trayectoria potencial. Excluir, documentar desde lugar seguro, revisar drenajes y obtener evaluación competente. Reabrir solo con criterio documentado. Caso 2B Aislar alimentaciones y movimientos asociados; bloquear, estabilizar energía y material, y verificar ausencia. Consignación: preparar, aislar, bloquear, disipar y verificar. Falso: la alarma ayuda; no elimina el punto ciego. Grieta nueva: aislar y comunicar.\n\nLa parada de un mando no elimina energía. Un equipo puede conservar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica, material atascado o energía gravitatoria. La consignación transforma el equipo en una condición controlada y verificable antes de intervenir. 1. Preparar: identificar alcance, fuentes, aislamiento, personas afectadas y estado seguro. 2. Parar de forma normal y comunicar la intervención. 3.\n\nEn una situación reconocible ocurriría lo siguiente. La lluvia exige exclusión y evaluación competente; la cinta exige consignación integral; el polvo exige controlar la fuente y verificar la exposición.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDistingue siempre entre control inmediato y solución definitiva. El primero detiene la exposición; la segunda corrige el diseño, el método, el mantenimiento o la organización. No retires una restricción temporal hasta comprobar el resultado y obtener la autorización prevista. Compara ahora esta solución con la tuya: revisa responsable, criterio de parada, condición de reapertura y evidencia de eficacia. La solución correcta elimina o controla la trayectoria antes de recuperar producción.","duration_seconds":157,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-042.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-042.jpg","explanation":"Objetivo\n\nResolver los casos del bloque dos mostrando por qué cada control es necesario.\n\nExplicación detallada\n\nLa parada de un mando no elimina energía. Un equipo puede conservar presión hidráulica o neumática, tensión eléctrica, calor, partes suspendidas, tensión mecánica, material atascado o energía gravitatoria. La consignación transforma el equipo en una condición controlada y verificable antes de intervenir. 1. Preparar: identificar alcance, fuentes, aislamiento, personas afectadas y estado seguro. 2. Parar de forma normal y comunicar la intervención. 3. Separar o aislar todas las fuentes de energía. 4. Bloquear los órganos de aislamiento e identificar al titular según procedimiento. 5. Disipar, descargar, purgar, enfriar, calzar o soportar energías acumuladas. 6. Verificar ausencia de energía con método adecuado, incluida prueba de intento cuando proceda. 7. Ejecutar manteniendo control de herramientas, piezas y cambios de alcance. 8. Reponer protecciones, retirar personas y materiales y retirar bloqueos con control. 9. Comunicar y reenergizar; comprobar funcionamiento seguro. Principio clave. Una etiqueta informa; un bloqueo eficaz impide la maniobra. La verificación demuestra que el aislamiento funciona. No deben confundirse.\n\nLectura guiada de la diapositiva\n\nCaso 2A No trabajar bajo la trayectoria potencial. Excluir, documentar desde lugar seguro, revisar drenajes y obtener evaluación competente. Reabrir solo con criterio documentado. Caso 2B Aislar alimentaciones y movimientos asociados; bloquear, estabilizar energía y material, y verificar ausencia. Consignación: preparar, aislar, bloquear, disipar y verificar. Falso: la alarma ayuda; no elimina el punto ciego. Grieta nueva: aislar y comunicar.\n\nAplicación práctica\n\nLa lluvia exige exclusión y evaluación competente; la cinta exige consignación integral; el polvo exige controlar la fuente y verificar la exposición.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa solución correcta elimina o controla la trayectoria antes de recuperar producción.","key_points":["Resolver los casos del bloque dos mostrando por qué cada control es necesario.","La solución correcta elimina o controla la trayectoria antes de recuperar producción."],"stop_criterion":"La solución correcta elimina o controla la trayectoria antes de recuperar producción.","source_pages":"Bloque 2 · técnicas preventivas y de protección"},{"slide_number":43,"block_number":3,"lesson_ordinal":6,"segment_position":1,"segment_id":"86cfe71a-6481-55f2-9a55-7855bc882be1","slide_id":"3d893f04-acc8-5a3c-8bae-c1147312b5ab","note_id":"264b2c9b-56f9-56bb-a87a-0953eee66d69","title":"CICLO DE VIDA DEL EQUIPO","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es presentar el ciclo de vida del equipo desde selección hasta retirada.\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno. Resultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nPensemos en un ejemplo. Un equipo puede ser adecuado al comprarlo y dejar de serlo tras una modificación, cambio de implemento, envejecimiento o nuevo terreno. Cada fase necesita criterios y registros.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La conformidad inicial no sustituye la gestión durante toda la vida del equipo.","duration_seconds":126,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-043.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-043.jpg","explanation":"Objetivo\n\nPresentar el ciclo de vida del equipo desde selección hasta retirada.\n\nExplicación detallada\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nResultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nLectura guiada de la diapositiva\n\nReal Decreto 1215/1997.\n\nAplicación práctica\n\nUn equipo puede ser adecuado al comprarlo y dejar de serlo tras una modificación, cambio de implemento, envejecimiento o nuevo terreno. Cada fase necesita criterios y registros.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa conformidad inicial no sustituye la gestión durante toda la vida del equipo.","key_points":["Presentar el ciclo de vida del equipo desde selección hasta retirada.","La conformidad inicial no sustituye la gestión durante toda la vida del equipo."],"stop_criterion":"La conformidad inicial no sustituye la gestión durante toda la vida del equipo.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":44,"block_number":3,"lesson_ordinal":6,"segment_position":2,"segment_id":"f2ebeebb-987d-5b61-8e40-8bc1b1abf6fe","slide_id":"4c5b7a94-875f-5f86-aedd-c1e1b78805fd","note_id":"41b20ecd-f46a-5085-a7ae-de91ffe7c85b","title":"RIESGOS: PERFORADORA, EXCAVADORA, CARGADORA","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es comparar riesgos dominantes de perforadora, excavadora y cargadora sin caer en listas genéricas.\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno. Resultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nPensemos en un ejemplo. La perforadora combina estabilidad, polvo y elementos rotativos; la excavadora añade alcance y frente; la cargadora incorpora articulación, atropello y caída de material.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La evaluación debe seguir el movimiento y la función real de cada máquina.","duration_seconds":154,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-044.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-044.jpg","explanation":"Objetivo\n\nComparar riesgos dominantes de perforadora, excavadora y cargadora sin caer en listas genéricas.\n\nExplicación detallada\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nResultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nLectura guiada de la diapositiva\n\nPerforadora Excavadora Cargadora Vuelco, borde, polvo, ruido, Colapso de frente, alcance, Atropello, vuelco, material, atrapamiento, barras y vuelco, golpe, caída y líneas. articulación y punto ciego. mangueras. Posición, zona de giro, Plan de carga, contacto Plataforma estable, captación, visibilidad y límites. positivo, cinturón y exclusión. exclusión, guardas y método de cambio.\n\nAplicación práctica\n\nLa perforadora combina estabilidad, polvo y elementos rotativos; la excavadora añade alcance y frente; la cargadora incorpora articulación, atropello y caída de material.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa evaluación debe seguir el movimiento y la función real de cada máquina.","key_points":["Comparar riesgos dominantes de perforadora, excavadora y cargadora sin caer en listas genéricas.","La evaluación debe seguir el movimiento y la función real de cada máquina."],"stop_criterion":"La evaluación debe seguir el movimiento y la función real de cada máquina.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":45,"block_number":3,"lesson_ordinal":6,"segment_position":3,"segment_id":"ca31f3c2-b504-5f27-a17a-1fedbb1f8794","slide_id":"0bb2cc6b-69e0-57d4-9ba7-4d95a125b288","note_id":"738b6dad-4ca3-539f-ab4e-cca220fcdee7","title":"RIESGOS: VOLQUETE, BULLDÓCER, MOTONIVELADORA","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es comparar volquete, bulldócer y motoniveladora atendiendo a geometría, visibilidad y tarea.\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno. Resultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nPensemos en un ejemplo. El volquete depende de frenos, borde y caja; el bulldócer trabaja cerca de desniveles y con visibilidad limitada; la motoniveladora ocupa gran anchura y altera drenajes.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La misma pista no ofrece el mismo riesgo a todas las máquinas.","duration_seconds":153,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-045.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-045.jpg","explanation":"Objetivo\n\nComparar volquete, bulldócer y motoniveladora atendiendo a geometría, visibilidad y tarea.\n\nExplicación detallada\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nResultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nLectura guiada de la diapositiva\n\nVolquete Bulldócer Motoniveladora Colisión, vuelco, borde, frenado, Vuelco, borde, material oculto y Colisión, vuelco, cuchilla, carga y caja elevada. marcha atrás. visibilidad y tráfico. Ruta, descarga nivelada, Trabajo seguro respecto al Corte de zona, señales, cinturón, alarmas y frenos. borde, referencias, ROPS y comunicación, luces y apoyo firme. separación.\n\nAplicación práctica\n\nEl volquete depende de frenos, borde y caja; el bulldócer trabaja cerca de desniveles y con visibilidad limitada; la motoniveladora ocupa gran anchura y altera drenajes.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa misma pista no ofrece el mismo riesgo a todas las máquinas.","key_points":["Comparar volquete, bulldócer y motoniveladora atendiendo a geometría, visibilidad y tarea.","La misma pista no ofrece el mismo riesgo a todas las máquinas."],"stop_criterion":"La misma pista no ofrece el mismo riesgo a todas las máquinas.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":46,"block_number":3,"lesson_ordinal":6,"segment_position":4,"segment_id":"a9e157f0-0945-5f8f-a140-55371fd0f338","slide_id":"03d84c5c-a4d3-555d-8614-01c9eac22135","note_id":"c967a623-f9a6-5772-bff4-9af4f3e0c990","title":"RIESGOS: TRITURACIÓN, CINTAS Y VEHÍCULOS LIGEROS","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es explicar riesgos de trituración, cintas y vehículos ligeros y sus interacciones.\n\nResultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura. El equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nPensemos en un ejemplo. Una cinta puede arrancar desde otro punto; una trituradora conserva material y energía; un vehículo ligero puede desaparecer en el punto ciego de un volquete.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Los equipos fijos y móviles forman un sistema conectado.","duration_seconds":151,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-046.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-046.jpg","explanation":"Objetivo\n\nExplicar riesgos de trituración, cintas y vehículos ligeros y sus interacciones.\n\nExplicación detallada\n\nResultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nLectura guiada de la diapositiva\n\nTrituradora y criba Cinta Vehículo ligero Atrapamiento, proyección, Atrapamiento, arranque, caída Aplastamiento por equipo caída, atasco, polvo y ruido. de material y altura. pesado, vuelco y acceso indebido. Guardas, acceso, consignación, Guardas, emergencia, captación y desatasco. consignación, pasarelas y Segregación, visibilidad, limpieza segura. comunicación y estacionamiento.\n\nAplicación práctica\n\nUna cinta puede arrancar desde otro punto; una trituradora conserva material y energía; un vehículo ligero puede desaparecer en el punto ciego de un volquete.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLos equipos fijos y móviles forman un sistema conectado.","key_points":["Explicar riesgos de trituración, cintas y vehículos ligeros y sus interacciones.","Los equipos fijos y móviles forman un sistema conectado."],"stop_criterion":"Los equipos fijos y móviles forman un sistema conectado.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":47,"block_number":3,"lesson_ordinal":6,"segment_position":5,"segment_id":"43d96e7e-5b47-5f9f-9fa4-4c8258605baf","slide_id":"d2cd78c4-9203-534f-bcf6-25fc05c8e4a8","note_id":"bceba098-aa01-552b-9a0b-91d38d6db5ca","title":"DOCUMENTACIÓN, CONFORMIDAD Y MARCADO CE","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es aclarar qué demuestran documentación, declaración de conformidad y marcado CE y qué no demuestran.\n\nCE y la declaración de conformidad no sustituyen la evaluación del lugar ni garantizan que la máquina sea apta para cualquier pendiente, material o accesorio. Se revisan manual, placa, capacidad, límites de inclinación, cargas, presión de neumáticos, mantenimiento y dispositivos. Una modificación sustancial o un accesorio no previsto puede alterar estabilidad, visibilidad y conformidad. Identificación inequívoca: fabricante, modelo, número, año y capacidad. Manual disponible en idioma comprensible y procedimientos coherentes. Declaración de conformidad cuando sea exigible y registro de puesta en servicio. Inspecciones reglamentarias y adicionales por instalación, deterioro o condiciones severas. Historial de defectos, reparaciones, pruebas, cambios y campañas.\n\nPensemos en un ejemplo. La identificación y el manual permiten saber configuración, límites y mantenimiento. El marcado CE no certifica que el terreno, la ruta o la tarea concreta sean seguros.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La adecuación al puesto se verifica en la explotación.","duration_seconds":133,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-047.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-047.jpg","explanation":"Objetivo\n\nAclarar qué demuestran documentación, declaración de conformidad y marcado CE y qué no demuestran.\n\nExplicación detallada\n\nCE y la declaración de conformidad no sustituyen la evaluación del lugar ni garantizan que la máquina sea apta para cualquier pendiente, material o accesorio. Se revisan manual, placa, capacidad, límites de inclinación, cargas, presión de neumáticos, mantenimiento y dispositivos. Una modificación sustancial o un accesorio no previsto puede alterar estabilidad, visibilidad y conformidad. Identificación inequívoca: fabricante, modelo, número, año y capacidad. Manual disponible en idioma comprensible y procedimientos coherentes. Declaración de conformidad cuando sea exigible y registro de puesta en servicio. Inspecciones reglamentarias y adicionales por instalación, deterioro o condiciones severas. Historial de defectos, reparaciones, pruebas, cambios y campañas. Autorización del operador específica y formación práctica documentada.\n\nLectura guiada de la diapositiva\n\nIdentificación inequívoca: fabricante, modelo, número, año y capacidad. Manual disponible en idioma comprensible; declaración de conformidad cuando sea exigible. Inspecciones reglamentarias y adicionales; historial de defectos, reparaciones y pruebas. El marcado CE no sustituye la evaluación del lugar ni garantiza aptitud para cualquier pendiente, material o accesorio. Una modificación sustancial o un accesorio no previsto altera estabilidad, visibilidad y conformidad. Conformidad cuando sea exigible; aptitud de uso según evaluación, fabricante y condiciones del centro.\n\nAplicación práctica\n\nLa identificación y el manual permiten saber configuración, límites y mantenimiento. El marcado CE no certifica que el terreno, la ruta o la tarea concreta sean seguros.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa adecuación al puesto se verifica en la explotación.","key_points":["Aclarar qué demuestran documentación, declaración de conformidad y marcado CE y qué no demuestran.","La adecuación al puesto se verifica en la explotación."],"stop_criterion":"La adecuación al puesto se verifica en la explotación.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":48,"block_number":3,"lesson_ordinal":6,"segment_position":6,"segment_id":"293778b7-5d20-57b5-8956-d67c7b9f40fc","slide_id":"06a034d2-518f-5c62-9975-0225fbb04413","note_id":"a61da09d-398e-59fa-99ea-2dd045bbbfab","title":"ROPS, FOPS Y CINTURÓN","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es explicar la función conjunta de estructuras ROPS y FOPS y del cinturón de seguridad.\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno. Criterio conservador. Si no se conoce la función o consecuencia de un defecto, no se clasifica como menor por intuición. Se consulta el manual, mantenimiento o ingeniería y se mantiene fuera de servicio cuando pueda comprometer seguridad.\n\nPensemos en un ejemplo. En un vuelco, la estructura crea un volumen de supervivencia y el cinturón mantiene al operador dentro. Una estructura dañada o un cinturón defectuoso requieren evaluación e inmovilización según criticidad.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: ROPS sin cinturón no forma un sistema completo de protección.","duration_seconds":136,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-048.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-048.jpg","explanation":"Objetivo\n\nExplicar la función conjunta de estructuras ROPS y FOPS y del cinturón de seguridad.\n\nExplicación detallada\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nCriterio conservador. Si no se conoce la función o consecuencia de un defecto, no se clasifica como menor por intuición. Se consulta el manual, mantenimiento o ingeniería y se mantiene fuera de servicio cuando pueda comprometer seguridad.\n\nLectura guiada de la diapositiva\n\nROPS, estructura de protección en caso de vuelco, y FOPS, estructura de protección frente a caída de objetos, protegen según diseño. Comprobar integridad, anclajes, corrosión y reparaciones. El cinturón mantiene al ocupante en el volumen protegido. Comprobar anclaje, hebilla, cinta, enrollado y uso. ROPS y cinturón funcionan como un sistema. Un cinturón con riesgo de vuelco es defecto crítico.\n\nAplicación práctica\n\nEn un vuelco, la estructura crea un volumen de supervivencia y el cinturón mantiene al operador dentro. Una estructura dañada o un cinturón defectuoso requieren evaluación e inmovilización según criticidad.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nROPS sin cinturón no forma un sistema completo de protección.","key_points":["Explicar la función conjunta de estructuras ROPS y FOPS y del cinturón de seguridad.","ROPS sin cinturón no forma un sistema completo de protección."],"stop_criterion":"ROPS sin cinturón no forma un sistema completo de protección.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":49,"block_number":3,"lesson_ordinal":6,"segment_position":7,"segment_id":"ee0be948-1485-5caf-83f6-1ebe01f9d69c","slide_id":"ee57f618-2476-5d59-9f6b-c96b4de2d040","note_id":"c0c0ce3c-4fbd-5d75-b883-70a609b123ea","title":"FRENOS, DIRECCIÓN, VISIBILIDAD Y AVISADORES","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es revisar frenos, dirección, visibilidad y avisadores como funciones críticas antes del uso.\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno. La inspección sigue un recorrido estable, con el equipo inmovilizado y sin entrar bajo elementos elevados. El operador registra defectos y conoce qué impide usar la máquina. La supervisión revisa tendencias, no solo casillas.\n\nPensemos en un ejemplo. Una prueba debe hacerse en condiciones controladas y comparar el resultado con el criterio del fabricante. La ausencia de testigos no demuestra capacidad de frenado.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Las funciones críticas se comprueban, no se presuponen.","duration_seconds":136,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-049.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-049.jpg","explanation":"Objetivo\n\nRevisar frenos, dirección, visibilidad y avisadores como funciones críticas antes del uso.\n\nExplicación detallada\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nLa inspección sigue un recorrido estable, con el equipo inmovilizado y sin entrar bajo elementos elevados. El operador registra defectos y conoce qué impide usar la máquina. La supervisión revisa tendencias, no solo casillas.\n\nLectura guiada de la diapositiva\n\nFrenos Dirección Servicio, emergencia y estacionamiento. Prueba Holguras, respuesta, fugas y prueba. prescrita, alarmas y fugas. Visibilidad Avisos Cristales, espejos, cámaras, radar, luces y limpieza. Acústicos y luminosos; no sustituyen la separación. Fallo de frenado o dirección: condición de parada. Las pruebas son las prescritas para el equipo.\n\nAplicación práctica\n\nUna prueba debe hacerse en condiciones controladas y comparar el resultado con el criterio del fabricante. La ausencia de testigos no demuestra capacidad de frenado.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLas funciones críticas se comprueban, no se presuponen.","key_points":["Revisar frenos, dirección, visibilidad y avisadores como funciones críticas antes del uso.","Las funciones críticas se comprueban, no se presuponen."],"stop_criterion":"Las funciones críticas se comprueban, no se presuponen.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":50,"block_number":3,"lesson_ordinal":6,"segment_position":8,"segment_id":"b490ba11-90f5-581e-a4a3-105900639f7d","slide_id":"2e5b2462-b5d6-5281-bf08-2795f7cbea1d","note_id":"8d9b7bed-3937-5446-8ad5-d78b5043031f","title":"GUARDAS Y PARADAS DE EMERGENCIA","narration_text":"Esta diapositiva propone mirar el trabajo con criterio técnico y no por costumbre. Nuestro objetivo es diferenciar guardas y paradas de emergencia y evitar usar la parada como medio habitual de aislamiento.\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nPensemos en un ejemplo. La guarda impide contacto; el enclavamiento controla acceso; la parada de emergencia limita consecuencias. Para intervenir se requiere consignación, porque el equipo puede rearmarse.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Una seta de emergencia no sustituye un bloqueo personal.","duration_seconds":121,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-050.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-050.jpg","explanation":"Objetivo\n\nDiferenciar guardas y paradas de emergencia y evitar usar la parada como medio habitual de aislamiento.\n\nExplicación detallada\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nLectura guiada de la diapositiva\n\nGuardas Impiden acceso a partes móviles o proyecciones. Comprobar presencia, fijación, abertura, enclavamiento y ausencia de puentes. Parada de emergencia Detiene con rapidez. Comprobar acceso, identificación, prueba, rearme y alcance. Guarda crítica inoperativa o protección activada: condición de parada. Rearmar sin investigar la causa normaliza la desviación.\n\nAplicación práctica\n\nLa guarda impide contacto; el enclavamiento controla acceso; la parada de emergencia limita consecuencias. Para intervenir se requiere consignación, porque el equipo puede rearmarse.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna seta de emergencia no sustituye un bloqueo personal.","key_points":["Diferenciar guardas y paradas de emergencia y evitar usar la parada como medio habitual de aislamiento.","Una seta de emergencia no sustituye un bloqueo personal."],"stop_criterion":"Una seta de emergencia no sustituye un bloqueo personal.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":51,"block_number":3,"lesson_ordinal":6,"segment_position":9,"segment_id":"8e039783-2397-541a-ba18-f9e32a6e9d09","slide_id":"a688fe2b-8b33-53fb-b740-a6818ff94d86","note_id":"24457a4e-cc41-5acf-9561-219b9a2369cc","title":"INSPECCIÓN ANTES DEL USO","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es enseñar un recorrido sistemático de inspección antes del uso.\n\nLa inspección sigue un recorrido estable, con el equipo inmovilizado y sin entrar bajo elementos elevados. El operador registra defectos y conoce qué impide usar la máquina. La supervisión revisa tendencias, no solo casillas.\n\nPensemos en un ejemplo. Se comienza por el entorno, se recorre estructura, rodaje, fluidos, cabina, mandos, protecciones y función. El equipo permanece inmovilizado y nadie entra bajo elementos elevados.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La secuencia estable reduce olvidos y mejora la calidad del registro.","duration_seconds":119,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-051.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-051.jpg","explanation":"Objetivo\n\nEnseñar un recorrido sistemático de inspección antes del uso.\n\nExplicación detallada\n\nLa inspección sigue un recorrido estable, con el equipo inmovilizado y sin entrar bajo elementos elevados. El operador registra defectos y conoce qué impide usar la máquina. La supervisión revisa tendencias, no solo casillas.\n\nLectura guiada de la diapositiva\n\nRecorrido estable, con el equipo inmovilizado y sin entrar bajo elementos elevados. Entorno Suelo, borde, personas, líneas, iluminación y ruta. Exterior e Fugas, daños, neumáticos u orugas, pasadores, implemento bloqueos y latiguillos. Cabina y arranque Cinturón, cristales, espejos, cámara, extintor, indicadores, frenos, dirección y emergencia. Documentación Chequeo, autorización y defectos previos. Defecto crítico abierto o falta de autorización: no se usa.\n\nAplicación práctica\n\nSe comienza por el entorno, se recorre estructura, rodaje, fluidos, cabina, mandos, protecciones y función. El equipo permanece inmovilizado y nadie entra bajo elementos elevados.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa secuencia estable reduce olvidos y mejora la calidad del registro.","key_points":["Enseñar un recorrido sistemático de inspección antes del uso.","La secuencia estable reduce olvidos y mejora la calidad del registro."],"stop_criterion":"La secuencia estable reduce olvidos y mejora la calidad del registro.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":52,"block_number":3,"lesson_ordinal":6,"segment_position":10,"segment_id":"213f7fe8-95cb-5d26-8480-6ce539589e94","slide_id":"fed4b7da-4cb5-5e34-b431-16e75d70fa35","note_id":"cc300d27-6ed3-5caa-99f9-5a40c7d39271","title":"DEFECTOS: CRÍTICO, LIMITANTE, MENOR","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es clasificar defectos como críticos, limitantes o menores con criterio conservador.\n\nCriterio conservador. Si no se conoce la función o consecuencia de un defecto, no se clasifica como menor por intuición. Se consulta el manual, mantenimiento o ingeniería y se mantiene fuera de servicio cuando pueda comprometer seguridad.\n\nPensemos en un ejemplo. Un fallo de freno o cinturón defectuoso en un equipo con riesgo de vuelco es crítico. Un daño cosmético sin función puede ser menor, pero solo después de confirmar que no afecta a seguridad.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Si no se conoce la consecuencia, el defecto no se rebaja por intuición.","duration_seconds":120,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-052.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-052.jpg","explanation":"Objetivo\n\nClasificar defectos como críticos, limitantes o menores con criterio conservador.\n\nExplicación detallada\n\nCriterio conservador. Si no se conoce la función o consecuencia de un defecto, no se clasifica como menor por intuición. Se consulta el manual, mantenimiento o ingeniería y se mantiene fuera de servicio cuando pueda comprometer seguridad.\n\nLectura guiada de la diapositiva\n\nCrítico Limitante Menor Inmovilizar, señalar, aislar y Solo con evaluación y Registrar y programar reparar antes de usar. autorización documentadas, corrección sin pérdida de con restricción y plazo. función de seguridad. Freno o dirección, cinturón con riesgo de vuelco, daño estructural, fuga caliente o guarda crítica. Criterio conservador: si no se conoce función o consecuencia, no es menor. Consultar y mantener fuera de servicio.\n\nAplicación práctica\n\nUn fallo de freno o cinturón defectuoso en un equipo con riesgo de vuelco es crítico. Un daño cosmético sin función puede ser menor, pero solo después de confirmar que no afecta a seguridad.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nSi no se conoce la consecuencia, el defecto no se rebaja por intuición.","key_points":["Clasificar defectos como críticos, limitantes o menores con criterio conservador.","Si no se conoce la consecuencia, el defecto no se rebaja por intuición."],"stop_criterion":"Si no se conoce la consecuencia, el defecto no se rebaja por intuición.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":53,"block_number":3,"lesson_ordinal":7,"segment_position":1,"segment_id":"d29b2ccb-333c-541e-a871-f7f1021e270f","slide_id":"6504ab90-69d1-5f9f-81c1-3f0597bda5a9","note_id":"673994b4-4145-5e48-8d10-81ee3c33f402","title":"ACTIVIDAD DEL ALUMNO · 30 MINUTOS","narration_text":"Llegamos a una actividad práctica de aproximadamente 30 minutos. El objetivo es dirigir una inspección de campo basada en una máquina real o fotografías.\n\nLa situación de trabajo es esta. ACTIVIDAD DE INSPECCIÓN EN CAMPO Aplicad el recorrido de inspección previa sobre una máquina real o fotografías de una máquina minera. Recorred entorno, exterior, implemento, cabina, arranque y documentación. Registrad los defectos observados. Clasificad cada defecto. Justificad la decisión de inmovilización. Puesta en común por equipos. Se valora la clasificación razonada y la decisión de uso, no solo completar casillas.\n\nPara orientar el análisis, considera este encuadre. El alumno debe identificar equipo, seguir el recorrido, registrar defectos, clasificarlos, decidir acción y justificar qué evidencia permitiría cerrar cada uno.\n\nTrabaja en este orden. Primero separa hechos de suposiciones. Después identifica la energía o condición peligrosa, su trayectoria y las personas expuestas. A continuación propone una medida inmediata para retirar la exposición y otra que corrija la causa. Termina indicando quién decide, qué debe comprobarse y qué condición permite reabrir. Evita respuestas genéricas como tener cuidado o señalizar sin explicar qué barrera controla el escenario.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén ahora la reproducción y realiza la actividad. Conserva tu respuesta para compararla con la resolución posterior. Inspeccionar no es marcar casillas; es producir una decisión segura.","duration_seconds":129,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-053.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-053.jpg","explanation":"Objetivo\n\nDirigir una inspección de campo basada en una máquina real o fotografías.\n\nExplicación detallada\n\nLa inspección sigue un recorrido estable, con el equipo inmovilizado y sin entrar bajo elementos elevados. El operador registra defectos y conoce qué impide usar la máquina. La supervisión revisa tendencias, no solo casillas.\n\nCriterio conservador. Si no se conoce la función o consecuencia de un defecto, no se clasifica como menor por intuición. Se consulta el manual, mantenimiento o ingeniería y se mantiene fuera de servicio cuando pueda comprometer seguridad.\n\nLectura guiada de la diapositiva\n\nACTIVIDAD DE INSPECCIÓN EN CAMPO Aplicad el recorrido de inspección previa sobre una máquina real o fotografías de una máquina minera. Recorred entorno, exterior, implemento, cabina, arranque y documentación. Registrad los defectos observados. Clasificad cada defecto. Justificad la decisión de inmovilización. Puesta en común por equipos. Se valora la clasificación razonada y la decisión de uso, no solo completar casillas.\n\nAplicación práctica\n\nEl alumno debe identificar equipo, seguir el recorrido, registrar defectos, clasificarlos, decidir acción y justificar qué evidencia permitiría cerrar cada uno.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nInspeccionar no es marcar casillas; es producir una decisión segura.","key_points":["Dirigir una inspección de campo basada en una máquina real o fotografías.","Inspeccionar no es marcar casillas; es producir una decisión segura."],"stop_criterion":"Inspeccionar no es marcar casillas; es producir una decisión segura.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":54,"block_number":3,"lesson_ordinal":7,"segment_position":2,"segment_id":"5c31b4d9-b311-5004-8a60-5ffd37e0c880","slide_id":"3f92ccc3-7d67-5dbe-a2a6-d614d62e78fd","note_id":"94a916ee-87c9-5f20-bb00-94e034faadaa","title":"MANTENIMIENTO SEGURO Y FLUIDOS A PRESIÓN","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es explicar mantenimiento seguro y fluidos a presión con planificación previa.\n\nBajar implementos; si deben elevarse, usar soportes mecánicos diseñados. Nunca confiar en la hidráulica. Liberar presión según manual; una manguera puede inyectar fluido bajo la piel sin herida aparente importante. No buscar fugas con la mano. Usar método seguro y tratar la inyección como urgencia médica. Controlar neumáticos y ruedas con procedimiento específico; la energía almacenada exige exclusión y medios adecuados. Para soldar o cortar, retirar combustibles, limpiar, controlar atmósfera y fuego y mantener vigilancia cuando proceda. Tras reparar, reponer guardas, retirar bloqueos con control, probar en zona segura y comunicar retorno.\n\nPensemos en un ejemplo. Se elige lugar, acceso, iluminación, herramientas, soportes, repuestos y control de derrames. Las fugas no se buscan con la mano y la presión se libera según fabricante.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La intervención empieza antes de abrir una protección o aflojar una conexión.","duration_seconds":121,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-054.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-054.jpg","explanation":"Objetivo\n\nExplicar mantenimiento seguro y fluidos a presión con planificación previa.\n\nExplicación detallada\n\nBajar implementos; si deben elevarse, usar soportes mecánicos diseñados. Nunca confiar en la hidráulica. Liberar presión según manual; una manguera puede inyectar fluido bajo la piel sin herida aparente importante. No buscar fugas con la mano. Usar método seguro y tratar la inyección como urgencia médica. Controlar neumáticos y ruedas con procedimiento específico; la energía almacenada exige exclusión y medios adecuados. Para soldar o cortar, retirar combustibles, limpiar, controlar atmósfera y fuego y mantener vigilancia cuando proceda. Tras reparar, reponer guardas, retirar bloqueos con control, probar en zona segura y comunicar retorno.\n\nLectura guiada de la diapositiva\n\nPlanificar lugar, acceso, limpieza, iluminación, herramientas, repuestos, izado y fluidos. Liberar presión según el manual del fabricante. Una manguera puede inyectar fluido bajo la piel sin herida aparente importante: tratar como urgencia médica. No buscar fugas con la mano; usar un método seguro. Neumáticos y ruedas requieren procedimiento específico y exclusión.\n\nAplicación práctica\n\nSe elige lugar, acceso, iluminación, herramientas, soportes, repuestos y control de derrames. Las fugas no se buscan con la mano y la presión se libera según fabricante.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa intervención empieza antes de abrir una protección o aflojar una conexión.","key_points":["Explicar mantenimiento seguro y fluidos a presión con planificación previa.","La intervención empieza antes de abrir una protección o aflojar una conexión."],"stop_criterion":"La intervención empieza antes de abrir una protección o aflojar una conexión.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":55,"block_number":3,"lesson_ordinal":7,"segment_position":3,"segment_id":"e513f8c2-96ef-5782-af3c-437db0531937","slide_id":"83f54589-bbd9-5246-9177-3d22f33fc7ef","note_id":"2120e20d-18b6-5be8-993b-f3f1471efa2e","title":"IMPLEMENTOS ELEVADOS Y TRABAJOS EN CALIENTE","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es controlar implementos elevados, trabajos en caliente y riesgos de caída o incendio.\n\nBajar implementos; si deben elevarse, usar soportes mecánicos diseñados. Nunca confiar en la hidráulica. Liberar presión según manual; una manguera puede inyectar fluido bajo la piel sin herida aparente importante. No buscar fugas con la mano. Usar método seguro y tratar la inyección como urgencia médica. Controlar neumáticos y ruedas con procedimiento específico; la energía almacenada exige exclusión y medios adecuados. Para soldar o cortar, retirar combustibles, limpiar, controlar atmósfera y fuego y mantener vigilancia cuando proceda. Tras reparar, reponer guardas, retirar bloqueos con control, probar en zona segura y comunicar retorno.\n\nPensemos en un ejemplo. Un implemento elevado se baja o soporta mecánicamente; un tablón no es soporte calculado. El trabajo en caliente necesita limpieza, separación de combustibles, extintor y vigilancia posterior.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La hidráulica y la ausencia de llama visible no son garantías suficientes.","duration_seconds":124,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-055.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-055.jpg","explanation":"Objetivo\n\nControlar implementos elevados, trabajos en caliente y riesgos de caída o incendio.\n\nExplicación detallada\n\nBajar implementos; si deben elevarse, usar soportes mecánicos diseñados. Nunca confiar en la hidráulica. Liberar presión según manual; una manguera puede inyectar fluido bajo la piel sin herida aparente importante. No buscar fugas con la mano. Usar método seguro y tratar la inyección como urgencia médica. Controlar neumáticos y ruedas con procedimiento específico; la energía almacenada exige exclusión y medios adecuados. Para soldar o cortar, retirar combustibles, limpiar, controlar atmósfera y fuego y mantener vigilancia cuando proceda. Tras reparar, reponer guardas, retirar bloqueos con control, probar en zona segura y comunicar retorno.\n\nLectura guiada de la diapositiva\n\nBajar los implementos. Si deben elevarse, usar soportes mecánicos diseñados. Nunca confiar en la hidráulica; un tablón no es un soporte calculado. Para soldar o cortar: retirar combustibles, limpiar, controlar atmósfera y fuego, y mantener vigilancia. Tras reparar: reponer guardas, retirar bloqueos con control, probar en zona segura y comunicar el retorno.\n\nAplicación práctica\n\nUn implemento elevado se baja o soporta mecánicamente; un tablón no es soporte calculado. El trabajo en caliente necesita limpieza, separación de combustibles, extintor y vigilancia posterior.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa hidráulica y la ausencia de llama visible no son garantías suficientes.","key_points":["Controlar implementos elevados, trabajos en caliente y riesgos de caída o incendio.","La hidráulica y la ausencia de llama visible no son garantías suficientes."],"stop_criterion":"La hidráulica y la ausencia de llama visible no son garantías suficientes.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":56,"block_number":3,"lesson_ordinal":7,"segment_position":4,"segment_id":"f75616eb-fde2-50b5-b619-0bdef19067f2","slide_id":"c784c9ae-550d-56f3-8314-678779930c7c","note_id":"2437853a-e36b-53a2-841d-7f20ea41daf5","title":"EPI: EL ÚLTIMO CONTROL","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es situar el EPI como último nivel de control y explicar selección, compatibilidad y mantenimiento.\n\nEPI protege frente al riesgo residual y se selecciona a partir de la evaluación. La certificación no asegura compatibilidad: casco, gafas, orejeras, respirador y ropa pueden interferir. El ajuste real, estado y limpieza son parte de la protección.\n\nPensemos en un ejemplo. Casco, gafas, protección auditiva y respiratoria pueden interferir entre sí. Deben ajustarse a la persona y al riesgo residual, revisarse y sustituirse cuando pierdan eficacia.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Entregar un EPI no demuestra que proteja durante la tarea.","duration_seconds":122,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-056.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-056.jpg","explanation":"Objetivo\n\nSituar el EPI como último nivel de control y explicar selección, compatibilidad y mantenimiento.\n\nExplicación detallada\n\nEPI protege frente al riesgo residual y se selecciona a partir de la evaluación. La certificación no asegura compatibilidad: casco, gafas, orejeras, respirador y ropa pueden interferir. El ajuste real, estado y limpieza son parte de la protección.\n\nLectura guiada de la diapositiva\n\nEl equipo de protección individual protege frente al riesgo residual y se selecciona a partir de la evaluación. La certificación no asegura compatibilidad: casco, gafas, orejeras, respirador y ropa pueden interferir. El ajuste real, el estado y la limpieza forman parte de la protección. Ninguna medida de equipo de protección individual sustituye controles de orden superior. Real Decreto 773/1997.\n\nAplicación práctica\n\nCasco, gafas, protección auditiva y respiratoria pueden interferir entre sí. Deben ajustarse a la persona y al riesgo residual, revisarse y sustituirse cuando pierdan eficacia.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEntregar un EPI no demuestra que proteja durante la tarea.","key_points":["Situar el EPI como último nivel de control y explicar selección, compatibilidad y mantenimiento.","Entregar un EPI no demuestra que proteja durante la tarea."],"stop_criterion":"Entregar un EPI no demuestra que proteja durante la tarea.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":57,"block_number":3,"lesson_ordinal":7,"segment_position":5,"segment_id":"4b88034b-532e-59f8-b1c5-3325e26c1232","slide_id":"2a34c253-aa5a-55ab-b7b5-b455584b1464","note_id":"f63cc714-0e51-5141-940f-2d837c649c94","title":"EPI POR RIESGO: SELECCIÓN Y AJUSTE","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es relacionar riesgos concretos con selección y ajuste del EPI.\n\nEPI protege frente al riesgo residual y se selecciona a partir de la evaluación. La certificación no asegura compatibilidad: casco, gafas, orejeras, respirador y ropa pueden interferir. El ajuste real, estado y limpieza son parte de la protección.\n\nPensemos en un ejemplo. Polvo exige filtro y ajuste facial; ruido exige atenuación adecuada sin impedir comunicaciones críticas; altura exige sistema compatible con punto de anclaje y distancia de caída.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: El EPI se selecciona desde la evaluación, no desde un catálogo genérico.","duration_seconds":122,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-057.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-057.jpg","explanation":"Objetivo\n\nRelacionar riesgos concretos con selección y ajuste del EPI.\n\nExplicación detallada\n\nEPI protege frente al riesgo residual y se selecciona a partir de la evaluación. La certificación no asegura compatibilidad: casco, gafas, orejeras, respirador y ropa pueden interferir. El ajuste real, estado y limpieza son parte de la protección.\n\nLectura guiada de la diapositiva\n\nRIESGO O SELECCIÓN Y COMPROBACIÓN Cabeza Casco; barboqueo cuando proceda. Ojos y cara Gafas cerradas o pantalla según impacto, polvo o salpicadura. Ruido Tapón, orejera o doble protección; atenuación real y ajuste. Polvo / SCR Protección respiratoria definida por evaluación; filtro, ajuste, barba y prueba. Pies y manos Calzado de seguridad; guante según agente. Alta visibilidad y Prenda certificada; sistema completo anticaída, caída priorizando la protección colectiva. Referencia técnica: INSST, NTP 733.\n\nAplicación práctica\n\nPolvo exige filtro y ajuste facial; ruido exige atenuación adecuada sin impedir comunicaciones críticas; altura exige sistema compatible con punto de anclaje y distancia de caída.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl EPI se selecciona desde la evaluación, no desde un catálogo genérico.","key_points":["Relacionar riesgos concretos con selección y ajuste del EPI.","El EPI se selecciona desde la evaluación, no desde un catálogo genérico."],"stop_criterion":"El EPI se selecciona desde la evaluación, no desde un catálogo genérico.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":58,"block_number":3,"lesson_ordinal":7,"segment_position":6,"segment_id":"d8094197-e993-548a-95cf-9221e73e6fa8","slide_id":"708fd6a6-a3a3-5e49-a4ca-4831b8a9b56b","note_id":"0dd9d80c-2918-5736-9bc0-42b5c8aff4f2","title":"ESCALERAS, ANDAMIOS Y PLATAFORMAS ELEVADORAS","narration_text":"Esta diapositiva propone mirar el trabajo con criterio técnico y no por costumbre. Nuestro objetivo es diferenciar escalera, andamio y plataforma elevadora y matizar cuándo una escalera puede usarse como puesto.\n\nPensemos en un ejemplo. La escalera se reserva para casos justificados de bajo riesgo y corta duración cuando no sea razonable otro medio. Andamios y plataformas requieren montaje, inspección, nivelación y protección colectiva.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de cerrar, explica el criterio con tus propias palabras y aplícalo a una tarea conocida. Si no puedes identificar la barrera, la persona responsable y la comprobación final, todavía falta concretar la decisión preventiva.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: El medio de acceso debe elegirse por riesgo y duración, no por comodidad.","duration_seconds":124,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-058.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-058.jpg","explanation":"Objetivo\n\nDiferenciar escalera, andamio y plataforma elevadora y matizar cuándo una escalera puede usarse como puesto.\n\nExplicación detallada\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nResultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nCE y la declaración de conformidad no sustituyen la evaluación del lugar ni garantizan que la máquina sea apta para cualquier pendiente, material o accesorio. Se revisan manual, placa, capacidad, límites de inclinación, cargas, presión de neumáticos, mantenimiento y dispositivos. Una modificación sustancial o un accesorio no previsto puede alterar estabilidad, visibilidad y conformidad. Identificación inequívoca: fabricante, modelo, número, año y capacidad. Manual disponible en idioma comprensible y procedimientos coherentes. Declaración de conformidad cuando sea exigible y registro de puesta en servicio. Inspecciones reglamentarias y adicionales por instalación, deterioro o condiciones severas. Historial de defectos, reparaciones, pruebas, cambios y campañas. Autorización del operador específica y formación práctica documentada.\n\nLectura guiada de la diapositiva\n\nEscalera Andamio o plataforma Tipo, longitud, apoyo, sujeción, ángulo y estado. No Montaje, inspección, nivel, barandilla, acceso, carga usar como puesto de trabajo. y exclusión. Plataforma elevadora Punto de anclaje Terreno, estabilizadores, alcance, viento, rescate y Diseño o cálculo, ubicación e inspección. operador.\n\nAplicación práctica\n\nLa escalera se reserva para casos justificados de bajo riesgo y corta duración cuando no sea razonable otro medio. Andamios y plataformas requieren montaje, inspección, nivelación y protección colectiva.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl medio de acceso debe elegirse por riesgo y duración, no por comodidad.","key_points":["Diferenciar escalera, andamio y plataforma elevadora y matizar cuándo una escalera puede usarse como puesto.","El medio de acceso debe elegirse por riesgo y duración, no por comodidad."],"stop_criterion":"El medio de acceso debe elegirse por riesgo y duración, no por comodidad.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":59,"block_number":3,"lesson_ordinal":7,"segment_position":7,"segment_id":"31505e2d-9ae8-5663-9946-948ed7336cb0","slide_id":"815f6d71-ce1c-5607-afc6-6d1db7ad9adc","note_id":"92b22778-9548-5910-bbb0-82244f46437d","title":"IZADO, ESLINGAS Y ACCESORIOS","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es planificar izados considerando carga, equipo, accesorios, terreno y comunicaciones.\n\nPensemos en un ejemplo. Antes de elevar se conoce masa, centro de gravedad, configuración, capacidad, radio, suelo, señalista y zona de exclusión. Nadie pasa bajo la carga.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de cerrar, explica el criterio con tus propias palabras y aplícalo a una tarea conocida. Si no puedes identificar la barrera, la persona responsable y la comprobación final, todavía falta concretar la decisión preventiva.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Un accesorio certificado puede fallar si se usa con un ángulo o configuración no previstos.","duration_seconds":122,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-059.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-059.jpg","explanation":"Objetivo\n\nPlanificar izados considerando carga, equipo, accesorios, terreno y comunicaciones.\n\nExplicación detallada\n\nEl equipo seguro resulta de una elección adecuada, instalación correcta, uso dentro de límites, inspección, mantenimiento y retirada ante defectos. El técnico comprueba el sistema completo: máquina, terreno, tarea, operador, accesorios y entorno.\n\nResultados de aprendizaje. Seleccionar equipos considerando tarea, terreno, visibilidad, estabilidad y compatibilidad. Interpretar documentación, protecciones, avisos y limitaciones. Estructurar inspecciones antes del uso y criterios de inmovilización. Planificar mantenimiento con consignación y soportes seguros. Seleccionar EPI por riesgo residual, compatibilidad y ajuste. Controlar medios auxiliares, izado, acceso y trabajo en altura.\n\nCE y la declaración de conformidad no sustituyen la evaluación del lugar ni garantizan que la máquina sea apta para cualquier pendiente, material o accesorio. Se revisan manual, placa, capacidad, límites de inclinación, cargas, presión de neumáticos, mantenimiento y dispositivos. Una modificación sustancial o un accesorio no previsto puede alterar estabilidad, visibilidad y conformidad. Identificación inequívoca: fabricante, modelo, número, año y capacidad. Manual disponible en idioma comprensible y procedimientos coherentes. Declaración de conformidad cuando sea exigible y registro de puesta en servicio. Inspecciones reglamentarias y adicionales por instalación, deterioro o condiciones severas. Historial de defectos, reparaciones, pruebas, cambios y campañas. Autorización del operador específica y formación práctica documentada.\n\nLectura guiada de la diapositiva\n\nEl plan de izado define masa y centro de gravedad, equipo y accesorios, configuración, capacidad, terreno, exclusión, señalista, comunicaciones y respuesta ante fallo. Eslinga y accesorio Identificación, capacidad, ángulo, aristas, estado y compatibilidad. Gato y soporte Capacidad, apoyo y estabilidad; nunca solo el gato. Nadie se sitúa bajo carga suspendida.\n\nAplicación práctica\n\nAntes de elevar se conoce masa, centro de gravedad, configuración, capacidad, radio, suelo, señalista y zona de exclusión. Nadie pasa bajo la carga.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUn accesorio certificado puede fallar si se usa con un ángulo o configuración no previstos.","key_points":["Planificar izados considerando carga, equipo, accesorios, terreno y comunicaciones.","Un accesorio certificado puede fallar si se usa con un ángulo o configuración no previstos."],"stop_criterion":"Un accesorio certificado puede fallar si se usa con un ángulo o configuración no previstos.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":60,"block_number":3,"lesson_ordinal":7,"segment_position":8,"segment_id":"01e9e8a4-6e08-5490-91b8-2f16d37e4469","slide_id":"f38e95fe-e88b-5e46-b8fd-3c4bd5333414","note_id":"2062ae47-2798-5ba5-bd19-7c4d1a35df47","title":"ACTIVIDAD DEL ALUMNO · 20 MINUTOS","narration_text":"Llegamos a una actividad práctica de aproximadamente 20 minutos. El objetivo es resolver los casos de cámara averiada y cambio de latiguillo sin compensaciones improvisadas.\n\nLa situación de trabajo es esta. CASOS 3A Y 3B 3A. Cámara averiada Falla la cámara trasera de un volquete. Hay alarma, la descarga exige marcha atrás junto a un borde y circulan contratas. Clasificad el defecto y decidid si hay alternativa admisible. 3B. Cambio de latiguillo Un latiguillo pierde aceite; la cuchara está elevada y el motor parado. Se propone un tablón bajo el brazo. Enumerad las energías y el método seguro. Puesta en común.\n\nPara orientar el análisis, considera este encuadre. Una alarma no reemplaza visibilidad crítica; el volquete se inmoviliza o se rediseña la maniobra bajo evaluación. El latiguillo exige bajar, soportar, despresurizar, verificar y controlar derrames.\n\nTrabaja en este orden. Primero separa hechos de suposiciones. Después identifica la energía o condición peligrosa, su trayectoria y las personas expuestas. A continuación propone una medida inmediata para retirar la exposición y otra que corrija la causa. Termina indicando quién decide, qué debe comprobarse y qué condición permite reabrir. Evita respuestas genéricas como tener cuidado o señalizar sin explicar qué barrera controla el escenario.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén ahora la reproducción y realiza la actividad. Conserva tu respuesta para compararla con la resolución posterior. La producción no convierte un defecto crítico en aceptable.","duration_seconds":133,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-060.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-060.jpg","explanation":"Objetivo\n\nResolver los casos de cámara averiada y cambio de latiguillo sin compensaciones improvisadas.\n\nExplicación detallada\n\nIzado. El plan debe definir masa y centro de gravedad, equipo y accesorios, configuración, capacidad, terreno, exclusión, señalista, comunicaciones y respuesta ante fallo. Nadie se sitúa bajo carga suspendida. Caso 3A Cámara averiada en un volquete Situación. La cámara trasera falla. Hay alarma, pero la descarga exige marcha atrás junto a un borde y circulan contratas. Trabajo del alumno. Clasifique el defecto y decida si existe alternativa admisible. Criterio de resolución. La pérdida de visibilidad en una maniobra crítica no se compensa automáticamente con alarma. Se inmoviliza para reparar o se rediseña con control documentado que elimine exposición: ruta sin marcha atrás, zona cerrada, señalista competente y comunicación fiable, si evaluación y DIS lo permiten. Caso 3B Cambio de latiguillo Situación. Un latiguillo pierde aceite. La cuchara se deja elevada y el motor está parado. Se propone colocar un tablón bajo el brazo. Trabajo del alumno. Enumere energías y método seguro. Criterio de resolución. Hay energía gravitatoria e hidráulica y posible arranque. Se baja el implemento o instala soporte diseñado, se consigna, descarga presión y verifica. Un tablón no es un soporte calculado.\n\nLectura guiada de la diapositiva\n\nCASOS 3A Y 3B 3A. Cámara averiada Falla la cámara trasera de un volquete. Hay alarma, la descarga exige marcha atrás junto a un borde y circulan contratas. Clasificad el defecto y decidid si hay alternativa admisible. 3B. Cambio de latiguillo Un latiguillo pierde aceite; la cuchara está elevada y el motor parado. Se propone un tablón bajo el brazo. Enumerad las energías y el método seguro. Puesta en común.\n\nAplicación práctica\n\nUna alarma no reemplaza visibilidad crítica; el volquete se inmoviliza o se rediseña la maniobra bajo evaluación. El latiguillo exige bajar, soportar, despresurizar, verificar y controlar derrames.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa producción no convierte un defecto crítico en aceptable.","key_points":["Resolver los casos de cámara averiada y cambio de latiguillo sin compensaciones improvisadas.","La producción no convierte un defecto crítico en aceptable."],"stop_criterion":"La producción no convierte un defecto crítico en aceptable.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":61,"block_number":3,"lesson_ordinal":7,"segment_position":9,"segment_id":"875a7f9d-b023-5a08-b961-51fbccb46d12","slide_id":"45a3e695-dafa-5c77-802f-57b256e2f7e2","note_id":"a030a2b2-e7bd-578d-b79e-51f9e8a8373b","title":"BLOQUE 3. COMPROBACIÓN","narration_text":"Vamos a comprobar el aprendizaje del bloque. Justifica cada respuesta relacionando peligro, exposición, control y evidencia de campo.\n\nEstas son las cuestiones que debes resolver. Primera pregunta. Clasifica como crítico, limitante o menor un fallo de freno, un daño meramente cosmético, un cinturón defectuoso o no utilizado en un equipo con riesgo de vuelco y un elemento secundario cuya función se haya confirmado como no necesaria para la condición autorizada. Segunda pregunta. Decide si el marcado CE garantiza el uso seguro en cualquier terreno. Tercera pregunta. Explica con qué se asegura un implemento elevado. Cuarta pregunta. Decide qué hacer cuando una trituradora dispara repetidamente una protección y se rearma sin investigar la causa.\n\nUtiliza este ejemplo para comprobar tu criterio. Las preguntas deben obligar a justificar por qué un freno, un cinturón o una cámara afectan a funciones de seguridad y por qué la conformidad no cubre cualquier terreno.\n\nHaz una pausa después de cada pregunta. Si dos opciones parecen posibles, elige la que elimine antes la exposición, dependa menos de la conducta y permita verificar su eficacia. En una secuencia, conserva el orden del trabajo seguro. Anota también el error más peligroso y la consecuencia que produciría; así evitarás acertar simplemente por descarte.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén la reproducción, responde por escrito y explica por qué descartas las demás opciones. Después continúa con la resolución razonada. Clasificar es relacionar defecto, función y consecuencia.","duration_seconds":129,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-061.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-061.jpg","explanation":"Objetivo\n\nComprobar clasificación de defectos, marcado CE, EPI y medios auxiliares.\n\nExplicación detallada\n\nLimitante documentadas que establezcan restricción afecta una función necesaria en la y plazo. condición autorizada.\n\nCriterio conservador. Si no se conoce la función o consecuencia de un defecto, no se clasifica como menor por intuición. Se consulta el manual, mantenimiento o ingeniería y se mantiene fuera de servicio cuando pueda comprometer seguridad.\n\nEPI protege frente al riesgo residual y se selecciona a partir de la evaluación. La certificación no asegura compatibilidad: casco, gafas, orejeras, respirador y ropa pueden interferir. El ajuste real, estado y limpieza son parte de la protección.\n\nLectura guiada de la diapositiva\n\nPrimera pregunta. Clasifica como crítico, limitante o menor un fallo de freno, un daño meramente cosmético, un cinturón defectuoso o no utilizado en un equipo con riesgo de vuelco y un elemento secundario cuya función se haya confirmado como no necesaria para la condición autorizada. Segunda pregunta. Decide si el marcado CE garantiza el uso seguro en cualquier terreno. Tercera pregunta. Explica con qué se asegura un implemento elevado. Cuarta pregunta. Decide qué hacer cuando una trituradora dispara repetidamente una protección y se rearma sin investigar la causa.\n\nAplicación práctica\n\nLas preguntas deben obligar a justificar por qué un freno, un cinturón o una cámara afectan a funciones de seguridad y por qué la conformidad no cubre cualquier terreno.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nClasificar es relacionar defecto, función y consecuencia.","key_points":["Comprobar clasificación de defectos, marcado CE, EPI y medios auxiliares.","Clasificar es relacionar defecto, función y consecuencia."],"stop_criterion":"Clasificar es relacionar defecto, función y consecuencia.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":62,"block_number":3,"lesson_ordinal":7,"segment_position":10,"segment_id":"b2e141ec-f98f-5b4f-93e0-ebbdb1917d97","slide_id":"bf921448-40d0-5956-9831-c12e10a46a79","note_id":"63667198-4c26-5daa-a54e-c94b71b28bda","title":"BLOQUE 3. RESOLUCIONES Y RESPUESTAS","narration_text":"Vamos a revisar la resolución. Lo importante es comprobar que la decisión retira la exposición inmediata, trata la causa y define cómo se recupera una condición segura.\n\nLa respuesta propuesta se desarrolla así. 3A. La pérdida de visibilidad en una maniobra crítica no se compensa con alarma. Inmovilizar para reparar o rediseñar con ruta sin marcha atrás, zona cerrada o señalista competente, si evaluación y disposición interna de seguridad lo permiten. 3B. Energía gravitatoria e hidráulica y posible arranque. Bajar implemento o instalar soporte diseñado; consignar, descargar presión y verificar. Freno y cinturón: críticos. Cosmético: menor. Falso: el CE no sustituye la evaluación del uso. Implemento elevado: soporte diseñado.\n\nIzado. El plan debe definir masa y centro de gravedad, equipo y accesorios, configuración, capacidad, terreno, exclusión, señalista, comunicaciones y respuesta ante fallo. Nadie se sitúa bajo carga suspendida. Caso 3A Cámara averiada en un volquete Situación. La cámara trasera falla. Hay alarma, pero la descarga exige marcha atrás junto a un borde y circulan contratas. Trabajo del alumno. Clasifique el defecto y decida si existe alternativa admisible.\n\nEn una situación reconocible ocurriría lo siguiente. La cámara averiada cambia la maniobra; el latiguillo conserva presión; el marcado CE no evalúa la explotación; la escalera no es siempre la opción correcta.\n\nDistingue siempre entre control inmediato y solución definitiva. El primero detiene la exposición; la segunda corrige el diseño, el método, el mantenimiento o la organización. No retires una restricción temporal hasta comprobar el resultado y obtener la autorización prevista. Compara ahora esta solución con la tuya: revisa responsable, criterio de parada, condición de reapertura y evidencia de eficacia. La evidencia de reparación y prueba funcional cierra el defecto.","duration_seconds":136,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-062.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-062.jpg","explanation":"Objetivo\n\nRazonar las respuestas del bloque tres y reforzar decisiones conservadoras.\n\nExplicación detallada\n\nIzado. El plan debe definir masa y centro de gravedad, equipo y accesorios, configuración, capacidad, terreno, exclusión, señalista, comunicaciones y respuesta ante fallo. Nadie se sitúa bajo carga suspendida. Caso 3A Cámara averiada en un volquete Situación. La cámara trasera falla. Hay alarma, pero la descarga exige marcha atrás junto a un borde y circulan contratas. Trabajo del alumno. Clasifique el defecto y decida si existe alternativa admisible. Criterio de resolución. La pérdida de visibilidad en una maniobra crítica no se compensa automáticamente con alarma. Se inmoviliza para reparar o se rediseña con control documentado que elimine exposición: ruta sin marcha atrás, zona cerrada, señalista competente y comunicación fiable, si evaluación y DIS lo permiten. Caso 3B Cambio de latiguillo Situación. Un latiguillo pierde aceite. La cuchara se deja elevada y el motor está parado. Se propone colocar un tablón bajo el brazo. Trabajo del alumno. Enumere energías y método seguro. Criterio de resolución. Hay energía gravitatoria e hidráulica y posible arranque. Se baja el implemento o instala soporte diseñado, se consigna, descarga presión y verifica. Un tablón no es un soporte calculado.\n\nLectura guiada de la diapositiva\n\n3A. La pérdida de visibilidad en una maniobra crítica no se compensa con alarma. Inmovilizar para reparar o rediseñar con ruta sin marcha atrás, zona cerrada o señalista competente, si evaluación y disposición interna de seguridad lo permiten. 3B. Energía gravitatoria e hidráulica y posible arranque. Bajar implemento o instalar soporte diseñado; consignar, descargar presión y verificar. Freno y cinturón: críticos. Cosmético: menor. Falso: el CE no sustituye la evaluación del uso. Implemento elevado: soporte diseñado.\n\nAplicación práctica\n\nLa cámara averiada cambia la maniobra; el latiguillo conserva presión; el marcado CE no evalúa la explotación; la escalera no es siempre la opción correcta.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa evidencia de reparación y prueba funcional cierra el defecto.","key_points":["Razonar las respuestas del bloque tres y reforzar decisiones conservadoras.","La evidencia de reparación y prueba funcional cierra el defecto."],"stop_criterion":"La evidencia de reparación y prueba funcional cierra el defecto.","source_pages":"Bloque 3 · equipos, EPI y medios auxiliares"},{"slide_number":63,"block_number":4,"lesson_ordinal":8,"segment_position":1,"segment_id":"c87642d4-60f7-5533-a95c-356ede29becb","slide_id":"5c8ec268-7825-51af-8124-db3a69f912a7","note_id":"5fa821c9-1df1-5a29-8f28-4cfbe2f7b9c2","title":"OBJETIVOS DE LA VIGILANCIA Y QUÉ VIGILAR","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es definir los objetivos de la vigilancia y los elementos que deben observarse.\n\nControlar es comparar el estado real con un estándar, actuar ante desviaciones y comprobar el cierre. La vigilancia eficaz observa tendencias y eventos, no se limita a recorrer el centro. Resultados de aprendizaje. Diseñar un plan de inspección basado en riesgos y cambios. Definir criterios de aceptación, responsables y registros. Gestionar desviaciones, acciones correctoras y reapertura. Vigilar entorno, terceros y evolución geotécnica y ambiental.\n\nPensemos en un ejemplo. Vigilar significa comparar con un estándar, detectar cambios, actuar y verificar cierre. Incluye frentes, bermas, escombreras, pistas, aguas, instalaciones, equipos y conductas.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Una ronda sin criterio de aceptación produce observaciones, no control.","duration_seconds":136,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-063.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-063.jpg","explanation":"Objetivo\n\nDefinir los objetivos de la vigilancia y los elementos que deben observarse.\n\nExplicación detallada\n\nControlar es comparar el estado real con un estándar, actuar ante desviaciones y comprobar el cierre. La vigilancia eficaz observa tendencias y eventos, no se limita a recorrer el centro.\n\nResultados de aprendizaje. Diseñar un plan de inspección basado en riesgos y cambios. Definir criterios de aceptación, responsables y registros. Gestionar desviaciones, acciones correctoras y reapertura. Vigilar entorno, terceros y evolución geotécnica y ambiental.\n\nLectura guiada de la diapositiva\n\nControlar es comparar el estado real con un estándar, actuar ante desviaciones y comprobar el cierre. Frentes, bancos, bermas y escombreras. Pistas, accesos y bordes; plataformas y tajos. Planta e instalaciones. Polvo, ruido y vibración. Entorno exterior: terceros, obras vecinas y meteorología.\n\nAplicación práctica\n\nVigilar significa comparar con un estándar, detectar cambios, actuar y verificar cierre. Incluye frentes, bermas, escombreras, pistas, aguas, instalaciones, equipos y conductas.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna ronda sin criterio de aceptación produce observaciones, no control.","key_points":["Definir los objetivos de la vigilancia y los elementos que deben observarse.","Una ronda sin criterio de aceptación produce observaciones, no control."],"stop_criterion":"Una ronda sin criterio de aceptación produce observaciones, no control.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":64,"block_number":4,"lesson_ordinal":8,"segment_position":2,"segment_id":"1f9a3785-f0e5-538c-9c74-bd905bbf8ba6","slide_id":"3e519552-cb02-53cd-8f1a-11c34b6b54ef","note_id":"0df0111b-b511-5ac5-b45f-e050b6c556e9","title":"FRECUENCIAS Y DISPARADORES EXTRAORDINARIOS","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es diseñar frecuencias de inspección y disparadores extraordinarios según riesgo y cambio.\n\nControlar es comparar el estado real con un estándar, actuar ante desviaciones y comprobar el cierre. La vigilancia eficaz observa tendencias y eventos, no se limita a recorrer el centro. Resultados de aprendizaje. Diseñar un plan de inspección basado en riesgos y cambios. Definir criterios de aceptación, responsables y registros. Gestionar desviaciones, acciones correctoras y reapertura. Vigilar entorno, terceros y evolución geotécnica y ambiental.\n\nPensemos en un ejemplo. La lluvia, una voladura, un sismo, una modificación, un fallo repetido o una ausencia prolongada pueden exigir inspección adicional, aunque la ronda prevista ya se haya realizado.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La frecuencia fija nunca sustituye la vigilancia provocada por eventos.","duration_seconds":134,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-064.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-064.jpg","explanation":"Objetivo\n\nDiseñar frecuencias de inspección y disparadores extraordinarios según riesgo y cambio.\n\nExplicación detallada\n\nControlar es comparar el estado real con un estándar, actuar ante desviaciones y comprobar el cierre. La vigilancia eficaz observa tendencias y eventos, no se limita a recorrer el centro.\n\nResultados de aprendizaje. Diseñar un plan de inspección basado en riesgos y cambios. Definir criterios de aceptación, responsables y registros. Gestionar desviaciones, acciones correctoras y reapertura. Vigilar entorno, terceros y evolución geotécnica y ambiental.\n\nLectura guiada de la diapositiva\n\nÁMBITO VIGILANCIA DISPARADORES Frentes y Según Lluvia, escombreras riesgo, hielo, turno y sismo, programa voladura, geotécnico. caída, grieta, excavación o drenaje. Pistas y accesos Antes y durante la Tormenta, derrame, daño, equipo mayor o operación. incidente. Planta Rondas definidas. Atasco, protección activada, fuga o reparación. Polvo, ruido y Programa. Cambio de material, proceso, cabina, filtro vibración o síntoma. Las frecuencias son orientativas; las fija el centro.\n\nAplicación práctica\n\nLa lluvia, una voladura, un sismo, una modificación, un fallo repetido o una ausencia prolongada pueden exigir inspección adicional, aunque la ronda prevista ya se haya realizado.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa frecuencia fija nunca sustituye la vigilancia provocada por eventos.","key_points":["Diseñar frecuencias de inspección y disparadores extraordinarios según riesgo y cambio.","La frecuencia fija nunca sustituye la vigilancia provocada por eventos."],"stop_criterion":"La frecuencia fija nunca sustituye la vigilancia provocada por eventos.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":65,"block_number":4,"lesson_ordinal":8,"segment_position":3,"segment_id":"db3cdac1-9a47-52b8-ae65-2a05353a9938","slide_id":"37050c3f-520b-54c2-9bd2-a96fc28d35ef","note_id":"42322497-e778-525e-a151-f84b7e20b594","title":"INSPECCIÓN QUE PRODUCE DECISIONES","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es explicar una inspección que produce decisiones desde la preparación hasta la verificación.\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nPensemos en un ejemplo. El técnico prepara estándar, observa desde zona segura, recorre una secuencia, contrasta con ejecutantes, clasifica, asigna acciones y vuelve a comprobar.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: El cierre ocurre en campo cuando la función se ha recuperado.","duration_seconds":149,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-065.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-065.jpg","explanation":"Objetivo\n\nExplicar una inspección que produce decisiones desde la preparación hasta la verificación.\n\nExplicación detallada\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nLectura guiada de la diapositiva\n\nPreparar el estándar Observar desde zona segura Plano, proyecto, disposición interna de seguridad, elementos críticos y defectos Flujos, terreno, personas, energía, polvo y agua. abiertos. Recorrer Clasificar Secuencia fija y conversación con ejecutantes. Control inmediato, parada, aislamiento o seguimiento. Asignar Verificar Responsable, plazo y criterio de cierre. Cierre en campo y análisis de repetición o tendencia.\n\nAplicación práctica\n\nEl técnico prepara estándar, observa desde zona segura, recorre una secuencia, contrasta con ejecutantes, clasifica, asigna acciones y vuelve a comprobar.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl cierre ocurre en campo cuando la función se ha recuperado.","key_points":["Explicar una inspección que produce decisiones desde la preparación hasta la verificación.","El cierre ocurre en campo cuando la función se ha recuperado."],"stop_criterion":"El cierre ocurre en campo cuando la función se ha recuperado.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":66,"block_number":4,"lesson_ordinal":8,"segment_position":4,"segment_id":"1e8f1419-73a8-543f-9898-a07eeba5e7bf","slide_id":"4fbfb7db-e37e-5eba-861a-470f2f3582b2","note_id":"1f2c775d-87c8-5f68-83e8-6f34ba7dde62","title":"REGISTRO DE DESVIACIONES Y ACCIONES CORRECTORAS","narration_text":"Esta diapositiva propone mirar el trabajo con criterio técnico y no por costumbre. Nuestro objetivo es registrar desviaciones con responsable, plazo, criticidad y criterio de cierre.\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nPensemos en un ejemplo. Una fotografía puede mostrar un bache relleno, pero no demostrar drenaje ni comportamiento bajo carga. El registro debe decir qué resultado se espera y cómo se verificará.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Sin criterio de cierre, una acción puede quedar terminada administrativamente y abierta técnicamente.","duration_seconds":127,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-066.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-066.jpg","explanation":"Objetivo\n\nRegistrar desviaciones con responsable, plazo, criticidad y criterio de cierre.\n\nExplicación detallada\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, revisa circulación y verifica durante un periodo. Repetir relleno no cierra la causa.\n\nLectura guiada de la diapositiva\n\nCada desviación se clasifica y recibe responsable, plazo y criterio de TARJETA DE DESVIACIÓN cierre. Clasificación Una foto no siempre prueba la función recuperada: se verifica en campo. Responsable Analizar la repetición: repetir el parche no cierra la causa. Plazo Herramientas docentes del manual Criterio de cierre Lista diaria del técnico, tarjeta de parada y reevaluación, e inspección geotécnica visual. Verificación en campo Son modelos que deben adaptarse, aprobarse y validarse en el centro.\n\nAplicación práctica\n\nUna fotografía puede mostrar un bache relleno, pero no demostrar drenaje ni comportamiento bajo carga. El registro debe decir qué resultado se espera y cómo se verificará.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nSin criterio de cierre, una acción puede quedar terminada administrativamente y abierta técnicamente.","key_points":["Registrar desviaciones con responsable, plazo, criticidad y criterio de cierre.","Sin criterio de cierre, una acción puede quedar terminada administrativamente y abierta técnicamente."],"stop_criterion":"Sin criterio de cierre, una acción puede quedar terminada administrativamente y abierta técnicamente.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":67,"block_number":4,"lesson_ordinal":8,"segment_position":5,"segment_id":"7a7c25bf-1e8c-5f94-9e2a-b248f656e479","slide_id":"cf95a6d7-acac-54ee-97a5-91b48bd63e97","note_id":"7c0adb30-0576-5de4-929f-9603e297feaa","title":"NORMAL, ALERTA Y ALARMA","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es diferenciar estados normal, alerta y alarma y asociar una respuesta previamente definida.\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nPensemos en un ejemplo. Una tendencia de deformación puede activar alerta y mayor vigilancia; superar un umbral o perder una barrera crítica activa alarma, parada y exclusión.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Los umbrales deben acordarse antes de que la presión operativa influya en la decisión.","duration_seconds":128,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-067.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-067.jpg","explanation":"Objetivo\n\nDiferenciar estados normal, alerta y alarma y asociar una respuesta previamente definida.\n\nExplicación detallada\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, revisa circulación y verifica durante un periodo. Repetir relleno no cierra la causa.\n\nLectura guiada de la diapositiva\n\nNormal Alerta Alarma Dentro de criterios. Cambio o tendencia. Criterio superado o fallo. Operar y registrar. Aumentar control, limitar, Parar, aislar, excluir, evaluar preparar medida y comunicar. y corregir. Reapertura con Vuelta a criterios y validación. autorización documentada y seguimiento. Los valores proceden del diseño, instrumentación, fabricante, evaluación o plan de emergencia. No se inventan durante una incidencia.\n\nAplicación práctica\n\nUna tendencia de deformación puede activar alerta y mayor vigilancia; superar un umbral o perder una barrera crítica activa alarma, parada y exclusión.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLos umbrales deben acordarse antes de que la presión operativa influya en la decisión.","key_points":["Diferenciar estados normal, alerta y alarma y asociar una respuesta previamente definida.","Los umbrales deben acordarse antes de que la presión operativa influya en la decisión."],"stop_criterion":"Los umbrales deben acordarse antes de que la presión operativa influya en la decisión.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":68,"block_number":4,"lesson_ordinal":8,"segment_position":6,"segment_id":"84849edd-dc2f-5f6a-ab0a-195218d9c127","slide_id":"f923ce64-6e42-5878-8a94-dea6d069472a","note_id":"e9e4bb22-0599-553c-8a41-e4543a7c357d","title":"DERECHO Y DEBER DE PARADA","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es convertir el derecho y deber de parada en una capacidad operativa protegida.\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método.\n\nPensemos en un ejemplo. Quien detecta una condición peligrosa debe saber cómo avisar, dejar el equipo seguro, controlar la zona y recibir respuesta. La organización evita represalias y exige cierre.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Parar a tiempo es una acción profesional, no un fracaso productivo.","duration_seconds":123,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-068.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-068.jpg","explanation":"Objetivo\n\nConvertir el derecho y deber de parada en una capacidad operativa protegida.\n\nExplicación detallada\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, revisa circulación y verifica durante un periodo. Repetir relleno no cierra la causa.\n\nLectura guiada de la diapositiva\n\nLa parada debe ser una capacidad operativa El centro define: Cómo avisar y dejar el equipo seguro. Cómo controlar la zona y evaluar. Quién autoriza la reanudación. Quien comunica recibe respuesta y cierre.\n\nAplicación práctica\n\nQuien detecta una condición peligrosa debe saber cómo avisar, dejar el equipo seguro, controlar la zona y recibir respuesta. La organización evita represalias y exige cierre.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nParar a tiempo es una acción profesional, no un fracaso productivo.","key_points":["Convertir el derecho y deber de parada en una capacidad operativa protegida.","Parar a tiempo es una acción profesional, no un fracaso productivo."],"stop_criterion":"Parar a tiempo es una acción profesional, no un fracaso productivo.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":69,"block_number":4,"lesson_ordinal":8,"segment_position":7,"segment_id":"19315d71-30bc-5e2b-ac87-2b546be2b745","slide_id":"20170228-5201-545c-b175-6ea631e5ab79","note_id":"6a26ed54-cf0b-5f4e-9e6f-b5194b1577ba","title":"REAPERTURA DOCUMENTADA","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es explicar la reapertura documentada después de una parada.\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método.\n\nPensemos en un ejemplo. Se identifica causa, se implantan controles, se comprueba función, se comunica y una persona autorizada decide reanudar. Que la señal desaparezca por sí sola no demuestra seguridad.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La reapertura necesita evidencia proporcional a la criticidad.","duration_seconds":120,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-069.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-069.jpg","explanation":"Objetivo\n\nExplicar la reapertura documentada después de una parada.\n\nExplicación detallada\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, revisa circulación y verifica durante un periodo. Repetir relleno no cierra la causa.\n\nLectura guiada de la diapositiva\n\nReanudar por presión, por ausencia de daño previo o por normalización de la desviación equivale a aceptar riesgo sin base. Identificación Fecha, hora y ubicación; condición observada. Exposición Riesgo y expuestos; acción inmediata y zona aislada. Corrección Evaluación y medida; prueba de eficacia. Reapertura Autoridad y hora; seguimiento. Autoriza quien define el Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nAplicación práctica\n\nSe identifica causa, se implantan controles, se comprueba función, se comunica y una persona autorizada decide reanudar. Que la señal desaparezca por sí sola no demuestra seguridad.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa reapertura necesita evidencia proporcional a la criticidad.","key_points":["Explicar la reapertura documentada después de una parada.","La reapertura necesita evidencia proporcional a la criticidad."],"stop_criterion":"La reapertura necesita evidencia proporcional a la criticidad.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":70,"block_number":4,"lesson_ordinal":8,"segment_position":8,"segment_id":"6ee0c8dc-150f-50d5-bcfa-88854aa9d5f5","slide_id":"cf23041d-f1d9-5321-ae3c-c03bf3da570a","note_id":"0e0849fb-590a-503f-9fed-da98f6560e40","title":"ACTIVIDAD DEL ALUMNO · 15 MINUTOS","narration_text":"Llegamos a una actividad práctica de aproximadamente 15 minutos. El objetivo es resolver el caso del bache repetido buscando la causa sistémica.\n\nLa situación de trabajo es esta. CASO 4A. DEFECTO REPETIDO Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Definir una acción que cierre la causa Puesta en común tras el trabajo del grupo. Control del tráfico. Análisis de drenaje, base, carga, pendiente y método. Verificación posterior.\n\nPara orientar el análisis, considera este encuadre. Rellenar tres veces sin analizar drenaje, base, pendiente, carga o método demuestra repetición, no control. Primero se regula tráfico; después se corrige la causa y se verifica durante un periodo.\n\nTrabaja en este orden. Primero separa hechos de suposiciones. Después identifica la energía o condición peligrosa, su trayectoria y las personas expuestas. A continuación propone una medida inmediata para retirar la exposición y otra que corrija la causa. Termina indicando quién decide, qué debe comprobarse y qué condición permite reabrir. Evita respuestas genéricas como tener cuidado o señalizar sin explicar qué barrera controla el escenario.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén ahora la reproducción y realiza la actividad. Conserva tu respuesta para compararla con la resolución posterior. Una desviación recurrente debe escalarse y analizarse como tendencia.","duration_seconds":125,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-070.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-070.jpg","explanation":"Objetivo\n\nResolver el caso del bache repetido buscando la causa sistémica.\n\nExplicación detallada\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, revisa circulación y verifica durante un periodo. Repetir relleno no cierra la causa.\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nLectura guiada de la diapositiva\n\nCASO 4A. DEFECTO REPETIDO Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Definir una acción que cierre la causa Puesta en común tras el trabajo del grupo. Control del tráfico. Análisis de drenaje, base, carga, pendiente y método. Verificación posterior.\n\nAplicación práctica\n\nRellenar tres veces sin analizar drenaje, base, pendiente, carga o método demuestra repetición, no control. Primero se regula tráfico; después se corrige la causa y se verifica durante un periodo.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna desviación recurrente debe escalarse y analizarse como tendencia.","key_points":["Resolver el caso del bache repetido buscando la causa sistémica.","Una desviación recurrente debe escalarse y analizarse como tendencia."],"stop_criterion":"Una desviación recurrente debe escalarse y analizarse como tendencia.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":71,"block_number":4,"lesson_ordinal":8,"segment_position":9,"segment_id":"f6507ea1-3a05-56b6-a05b-dbff19c41ac3","slide_id":"caff9f2f-64e6-5469-ae4c-153447c8b5f4","note_id":"87141b30-6c03-5b86-86b2-6baa7581dab0","title":"BLOQUE 4. COMPROBACIÓN","narration_text":"Vamos a comprobar el aprendizaje del bloque. Justifica cada respuesta relacionando peligro, exposición, control y evidencia de campo.\n\nEstas son las cuestiones que debes resolver. Primera pregunta, de elección múltiple. Ante un nivel de alarma, elige entre: continuar vigilando; limitarse a registrar; parar, aislar, excluir, evaluar y autorizar la reapertura; o esperar al final del turno. Segunda pregunta. Ordena estas fases: preparar el estándar, observar desde zona segura, clasificar la desviación y verificar el cierre. Tercera pregunta. Producción presiona para reanudar una zona cerrada. Indica quién puede autorizarlo y con qué evidencia. Cuarta pregunta. Razona si una fotografía basta por sí sola para cerrar una desviación.\n\nUtiliza este ejemplo para comprobar tu criterio. La opción correcta para alarma debe incluir parar, aislar, excluir, evaluar y autorizar reapertura. La secuencia de inspección comienza preparando el estándar y termina verificando el cierre.\n\nHaz una pausa después de cada pregunta. Si dos opciones parecen posibles, elige la que elimine antes la exposición, dependa menos de la conducta y permita verificar su eficacia. En una secuencia, conserva el orden del trabajo seguro. Anota también el error más peligroso y la consecuencia que produciría; así evitarás acertar simplemente por descarte.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén la reproducción, responde por escrito y explica por qué descartas las demás opciones. Después continúa con la resolución razonada. La respuesta correcta conserva el orden preventivo.","duration_seconds":132,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-071.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-071.jpg","explanation":"Objetivo\n\nRealizar una comprobación con opciones completas sobre alarma y orden de inspección.\n\nExplicación detallada\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, revisa circulación y verifica durante un periodo. Repetir relleno no cierra la causa.\n\nLectura guiada de la diapositiva\n\nPrimera pregunta, de elección múltiple. Ante un nivel de alarma, elige entre: continuar vigilando; limitarse a registrar; parar, aislar, excluir, evaluar y autorizar la reapertura; o esperar al final del turno. Segunda pregunta. Ordena estas fases: preparar el estándar, observar desde zona segura, clasificar la desviación y verificar el cierre. Tercera pregunta. Producción presiona para reanudar una zona cerrada. Indica quién puede autorizarlo y con qué evidencia. Cuarta pregunta. Razona si una fotografía basta por sí sola para cerrar una desviación.\n\nAplicación práctica\n\nLa opción correcta para alarma debe incluir parar, aislar, excluir, evaluar y autorizar reapertura. La secuencia de inspección comienza preparando el estándar y termina verificando el cierre.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa respuesta correcta conserva el orden preventivo.","key_points":["Realizar una comprobación con opciones completas sobre alarma y orden de inspección.","La respuesta correcta conserva el orden preventivo."],"stop_criterion":"La respuesta correcta conserva el orden preventivo.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":72,"block_number":4,"lesson_ordinal":8,"segment_position":10,"segment_id":"0952ca1e-0397-5442-8987-b13b7481c005","slide_id":"004ee5f7-2e3f-5646-b697-345ef725ac86","note_id":"32e4f24c-8679-5d88-a53b-82a7e3b15b96","title":"BLOQUE 4. RESOLUCIÓN Y RESPUESTAS","narration_text":"Vamos a revisar la resolución. Lo importante es comprobar que la decisión retira la exposición inmediata, trata la causa y define cómo se recupera una condición segura.\n\nLa respuesta propuesta se desarrolla así. 4A. Controlar el tráfico y analizar drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, y se verifica durante un periodo. Repetir el relleno no cierra la causa. Alarma: parar, aislar, excluir, evaluar y corregir. Orden: preparar, observar, clasificar y verificar el cierre. Reanuda la autoridad definida, con documentación. Falso: el cierre exige función recuperada.\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente.\n\nEn una situación reconocible ocurriría lo siguiente. Controlar el tráfico reduce exposición inmediata; analizar drenaje y estructura trata la causa; observar el comportamiento posterior demuestra eficacia.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDistingue siempre entre control inmediato y solución definitiva. El primero detiene la exposición; la segunda corrige el diseño, el método, el mantenimiento o la organización. No retires una restricción temporal hasta comprobar el resultado y obtener la autorización prevista. Compara ahora esta solución con la tuya: revisa responsable, criterio de parada, condición de reapertura y evidencia de eficacia. Repetir una reparación fallida no equivale a cerrar la desviación.","duration_seconds":148,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-072.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-072.jpg","explanation":"Objetivo\n\nExplicar la resolución del caso y las respuestas del bloque cuatro.\n\nExplicación detallada\n\nLa parada debe ser una capacidad operativa. El centro define cómo avisar, dejar el equipo seguro, controlar la zona, evaluar y autorizar la reanudación. Quien comunica recibe respuesta y cierre. Reanudar por presión, ausencia de daño previo o normalización de la desviación equivale a aceptar riesgo sin base. Caso 4A Defecto repetido Situación. Durante tres semanas se rellena el mismo bache en una pendiente. La reparación falla y los conductores invaden el carril contrario. Trabajo del alumno. Defina una acción que cierre la causa. Criterio de resolución. Se controla el tráfico y se analiza drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, revisa circulación y verifica durante un periodo. Repetir relleno no cierra la causa.\n\n4.2 Inspección que produce decisiones 1. Preparar estándar: plano, proyecto, DIS, elementos críticos, defectos abiertos y eventos. 2. Observar desde zona segura antes de entrar: flujos, terreno, personas, energía, polvo, agua y cambios. 3. Recorrer una secuencia fija, hablar con ejecutantes y contrastar lo prescrito con lo posible. 4. Clasificar desviación y decidir control inmediato, parada, aislamiento o seguimiento. 5. Asignar responsable, plazo y criterio de cierre. Una foto no siempre prueba función recuperada. 6. Verificar cierre en campo y analizar repetición o tendencia.\n\nLectura guiada de la diapositiva\n\n4A. Controlar el tráfico y analizar drenaje, base, carga, pendiente y método. La acción restaura estructura y evacuación, y se verifica durante un periodo. Repetir el relleno no cierra la causa. Alarma: parar, aislar, excluir, evaluar y corregir. Orden: preparar, observar, clasificar y verificar el cierre. Reanuda la autoridad definida, con documentación. Falso: el cierre exige función recuperada.\n\nAplicación práctica\n\nControlar el tráfico reduce exposición inmediata; analizar drenaje y estructura trata la causa; observar el comportamiento posterior demuestra eficacia.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nRepetir una reparación fallida no equivale a cerrar la desviación.","key_points":["Explicar la resolución del caso y las respuestas del bloque cuatro.","Repetir una reparación fallida no equivale a cerrar la desviación."],"stop_criterion":"Repetir una reparación fallida no equivale a cerrar la desviación.","source_pages":"Bloque 4 · control y vigilancia"},{"slide_number":73,"block_number":5,"lesson_ordinal":9,"segment_position":1,"segment_id":"afe655d9-f671-5942-919c-898bbd47402e","slide_id":"5631e1d6-4d19-5838-84d7-f6943ba2cbde","note_id":"32c15a8d-07bb-5470-807f-57beba59bd40","title":"INTERFERENCIA Y RIESGO EMERGENTE","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es definir interferencia y riesgo emergente entre tareas, empresas o fases.\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones. Muchos accidentes aparecen entre tareas analizadas por separado. La coordinación controla el espacio, el tiempo, la energía, la información y la autoridad compartidos.\n\nPensemos en un ejemplo. Una empresa puede cumplir su procedimiento y, aun así, energizar el equipo de otra. La interferencia aparece en espacio, tiempo, energía, información o emergencia.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La suma de dos trabajos seguros por separado puede ser insegura.","duration_seconds":135,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-073.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-073.jpg","explanation":"Objetivo\n\nDefinir interferencia y riesgo emergente entre tareas, empresas o fases.\n\nExplicación detallada\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nMuchos accidentes aparecen entre tareas analizadas por separado. La coordinación controla el espacio, el tiempo, la energía, la información y la autoridad compartidos.\n\nLectura guiada de la diapositiva\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles. Un equipo bloquea una salida; una contrata cruza una voladura. Mantenimiento energiza una línea que producción considera aislada. Una carretera pública queda expuesta a polvo o proyecciones.\n\nAplicación práctica\n\nUna empresa puede cumplir su procedimiento y, aun así, energizar el equipo de otra. La interferencia aparece en espacio, tiempo, energía, información o emergencia.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa suma de dos trabajos seguros por separado puede ser insegura.","key_points":["Definir interferencia y riesgo emergente entre tareas, empresas o fases.","La suma de dos trabajos seguros por separado puede ser insegura."],"stop_criterion":"La suma de dos trabajos seguros por separado puede ser insegura.","source_pages":"Bloque 5 · interferencias"},{"slide_number":74,"block_number":5,"lesson_ordinal":9,"segment_position":2,"segment_id":"77988056-e38f-56f8-84c9-751dff663d59","slide_id":"67a670b0-ae86-57d5-a833-a1154a3c6008","note_id":"1bd6dcca-64bb-5907-b284-72fbc07c2e4d","title":"DIMENSIONES DE LA INTERFERENCIA","narration_text":"Esta diapositiva propone mirar el trabajo con criterio técnico y no por costumbre. Nuestro objetivo es analizar las dimensiones espacio, tiempo, energía, información, acceso y emergencia.\n\nMuchos accidentes aparecen entre tareas analizadas por separado. La coordinación controla el espacio, el tiempo, la energía, la información y la autoridad compartidos. Hay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nPensemos en un ejemplo. Un equipo puede compartir zona, una prueba puede coincidir con mantenimiento, una alarma puede no oírse o una ruta de evacuación quedar bloqueada.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La coordinación debe revisar todas las dimensiones, no solo la proximidad física.","duration_seconds":137,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-074.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-074.jpg","explanation":"Objetivo\n\nAnalizar las dimensiones espacio, tiempo, energía, información, acceso y emergencia.\n\nExplicación detallada\n\nMuchos accidentes aparecen entre tareas analizadas por separado. La coordinación controla el espacio, el tiempo, la energía, la información y la autoridad compartidos.\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nLectura guiada de la diapositiva\n\nDIMENSIÓN PREGUNTA DE COORDINACIÓN Espacio ¿Comparten zona, ruta, altura, banco o área de caída o proyección? Tiempo ¿La simultaneidad crea exposición? ¿Puede secuenciarse? Energía ¿Quién controla aislamiento, arranque, presión, carga, electricidad o explosivo? Información ¿Todos conocen cambios, restricciones, idioma y señales? Autoridad ¿Quién puede parar, modificar y autorizar reanudación? Emergencia ¿Son compatibles alarma, evacuación, recuento, acceso y rescate?\n\nAplicación práctica\n\nUn equipo puede compartir zona, una prueba puede coincidir con mantenimiento, una alarma puede no oírse o una ruta de evacuación quedar bloqueada.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa coordinación debe revisar todas las dimensiones, no solo la proximidad física.","key_points":["Analizar las dimensiones espacio, tiempo, energía, información, acceso y emergencia.","La coordinación debe revisar todas las dimensiones, no solo la proximidad física."],"stop_criterion":"La coordinación debe revisar todas las dimensiones, no solo la proximidad física.","source_pages":"Bloque 5 · interferencias"},{"slide_number":75,"block_number":5,"lesson_ordinal":9,"segment_position":3,"segment_id":"27ccc789-98f0-5e63-9fac-b95522cb18e1","slide_id":"c943061a-50f1-511a-a538-585850c331e3","note_id":"a1033d3b-d845-589e-b34b-2811108db0d2","title":"COORDINACIÓN DE ACTIVIDADES EMPRESARIALES","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es aclarar funciones de empresa titular, concurrentes y principal sin trasladar responsabilidades indebidamente.\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar. Hay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nPensemos en un ejemplo. La titular informa sobre el centro; cada concurrente comunica sus riesgos y aplica medidas; la principal cumple su deber de vigilancia cuando corresponde. Coordinar no borra obligaciones propias.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: El intercambio de información debe traducirse en controles de campo.","duration_seconds":145,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-075.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-075.jpg","explanation":"Objetivo\n\nAclarar funciones de empresa titular, concurrentes y principal sin trasladar responsabilidades indebidamente.\n\nExplicación detallada\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar.\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nLectura guiada de la diapositiva\n\nEmpresa titular Empresas concurrentes Empresa principal Informa de riesgos y medidas Informan de sus riesgos Vigila a contratistas y del centro. específicos que puedan afectar subcontratistas dentro del a otras. alcance legal. Medios proporcionales: reunión, recurso preventivo, coordinador, permiso, plan común, consignación, control de acceso o secuencia exclusiva. No se agota en intercambiar documentos. Real Decreto 171/2004.\n\nAplicación práctica\n\nLa titular informa sobre el centro; cada concurrente comunica sus riesgos y aplica medidas; la principal cumple su deber de vigilancia cuando corresponde. Coordinar no borra obligaciones propias.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl intercambio de información debe traducirse en controles de campo.","key_points":["Aclarar funciones de empresa titular, concurrentes y principal sin trasladar responsabilidades indebidamente.","El intercambio de información debe traducirse en controles de campo."],"stop_criterion":"El intercambio de información debe traducirse en controles de campo.","source_pages":"Bloque 5 · interferencias"},{"slide_number":76,"block_number":5,"lesson_ordinal":9,"segment_position":4,"segment_id":"b8c19953-22bc-596a-9671-5aba95a551e5","slide_id":"2b90451b-95a6-544e-9e61-884259d02143","note_id":"551196d9-c6ef-5ab2-a252-745e347f56c8","title":"LA COORDINACIÓN EN CINCO MOMENTOS","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es organizar la coordinación en cinco momentos desde contratación hasta entrega final.\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar. Hay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nPensemos en un ejemplo. Antes de contratar se definen interfaces; antes de entrar se comprueban requisitos; antes del trabajo se revisa realidad; durante se supervisa; al cerrar se entrega en estado seguro.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La coordinación es continua, no una reunión única.","duration_seconds":143,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-076.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-076.jpg","explanation":"Objetivo\n\nOrganizar la coordinación en cinco momentos desde contratación hasta entrega final.\n\nExplicación detallada\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar.\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nLectura guiada de la diapositiva\n\nAntes de contratar Alcance, interfaces, competencia, equipos y controles críticos. Antes de entrar Documentación relevante, acogida, comunicación, emergencia y autorización. Antes de cada trabajo Condiciones reales, simultaneidad, zona, energía, tráfico y cambios. Durante Supervisar barreras; canal único para modificaciones. Al cerrar Entregar instalación, retirar aislamientos y materiales, informar defectos y verificar estado.\n\nAplicación práctica\n\nAntes de contratar se definen interfaces; antes de entrar se comprueban requisitos; antes del trabajo se revisa realidad; durante se supervisa; al cerrar se entrega en estado seguro.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa coordinación es continua, no una reunión única.","key_points":["Organizar la coordinación en cinco momentos desde contratación hasta entrega final.","La coordinación es continua, no una reunión única."],"stop_criterion":"La coordinación es continua, no una reunión única.","source_pages":"Bloque 5 · interferencias"},{"slide_number":77,"block_number":5,"lesson_ordinal":9,"segment_position":5,"segment_id":"8f12885f-4d9f-5cdb-9b25-4114919f897a","slide_id":"898e4389-b75f-5ce1-b233-0a343dd9bcfb","note_id":"353598c0-7293-5f13-8497-1318ca50b572","title":"REUNIÓN PREVIA DE COORDINACIÓN","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es conducir una reunión previa que produzca acuerdos verificables.\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar. Hay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nPensemos en un ejemplo. Se fijan alcance, límites físicos, responsables, secuencia, energía, tráfico, comunicaciones, emergencias, parada y entrega. Los acuerdos se confirman con planos o referencias claras.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Una reunión eficaz termina con decisiones, responsables y criterios de cambio.","duration_seconds":144,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-077.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-077.jpg","explanation":"Objetivo\n\nConducir una reunión previa que produzca acuerdos verificables.\n\nExplicación detallada\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar.\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nLectura guiada de la diapositiva\n\nCAMPO ACUERDO NECESARIO Alcance y límites Plano o referencia física; tareas excluidas. Responsables y Nombres, sustitución, orden, hitos e secuencia incompatibilidades. Energía y tráfico Puntos, bloqueos, custodios; rutas, prioridad, señalista y cortes. Cambios Qué obliga a parar y quién aprueba. Emergencia y cierre Alarma, recuento, rescate, estado final y aceptación. Modelo del anexo C del manual: adaptar y validar en cada centro.\n\nAplicación práctica\n\nSe fijan alcance, límites físicos, responsables, secuencia, energía, tráfico, comunicaciones, emergencias, parada y entrega. Los acuerdos se confirman con planos o referencias claras.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna reunión eficaz termina con decisiones, responsables y criterios de cambio.","key_points":["Conducir una reunión previa que produzca acuerdos verificables.","Una reunión eficaz termina con decisiones, responsables y criterios de cambio."],"stop_criterion":"Una reunión eficaz termina con decisiones, responsables y criterios de cambio.","source_pages":"Bloque 5 · interferencias"},{"slide_number":78,"block_number":5,"lesson_ordinal":9,"segment_position":6,"segment_id":"4ef961cb-7e12-5cbe-b0e2-c6d76a25375b","slide_id":"c8024788-dce8-55cf-afb8-e806c27b3362","note_id":"8741f39c-4191-5a05-9241-fd4501639684","title":"PERMISOS Y CONSIGNACIONES COMPARTIDAS","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es controlar permisos y consignaciones compartidas entre equipos relacionados.\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar. Hay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nPensemos en un ejemplo. Bloquear solo el motor local no protege frente a alimentación desde aguas arriba, gravedad, material o pruebas remotas. La custodia de bloqueos y el cambio de turno deben quedar definidos.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Nadie retira el bloqueo de otra persona sin aplicar el procedimiento autorizado.","duration_seconds":145,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-078.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-078.jpg","explanation":"Objetivo\n\nControlar permisos y consignaciones compartidas entre equipos relacionados.\n\nExplicación detallada\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar.\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nLectura guiada de la diapositiva\n\nLa prueba de un equipo puede introducir energía o material en otro. Consignación conjunta de equipos relacionados, aguas arriba y abajo. Custodia de bloqueos y cambio de turno definidos. Procedimiento de prueba y retorno acordado. Ninguna parte modifica unilateralmente el aislamiento.\n\nAplicación práctica\n\nBloquear solo el motor local no protege frente a alimentación desde aguas arriba, gravedad, material o pruebas remotas. La custodia de bloqueos y el cambio de turno deben quedar definidos.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nNadie retira el bloqueo de otra persona sin aplicar el procedimiento autorizado.","key_points":["Controlar permisos y consignaciones compartidas entre equipos relacionados.","Nadie retira el bloqueo de otra persona sin aplicar el procedimiento autorizado."],"stop_criterion":"Nadie retira el bloqueo de otra persona sin aplicar el procedimiento autorizado.","source_pages":"Bloque 5 · interferencias"},{"slide_number":79,"block_number":5,"lesson_ordinal":9,"segment_position":7,"segment_id":"f9c0f6f2-97cb-5528-8615-65e6c795a8ad","slide_id":"b4567c2d-59c8-5e77-bf69-c983876d8844","note_id":"d60cd30c-cf76-5c94-aa4f-f9e05d01efdb","title":"INTERFERENCIAS FRECUENTES EN EXTERIOR","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es reconocer interferencias frecuentes en exterior antes de que coincidan en campo.\n\n5.4 Interferencias frecuentes. Voladura con mantenimiento, tráfico, perforación, drones o terceros. Carga y transporte con peatones, topografía, muestreo, vehículos ligeros o limpieza. Producción con mantenimiento en cintas, tolvas, trituradoras o cuadros. Excavación con líneas aéreas, tuberías, cables, edificaciones o propiedad. Vertido con equipos al pie, inestabilidad, agua o circulación por coronación. Trabajo en caliente con combustibles, polvo o materiales inflamables. Trabajo nocturno con iluminación, fatiga, relevo y menor apoyo externo. Caso 5A Mantenimiento y producción Situación. Una contrata cambia un rodamiento en un transportador. Producción quiere probar el triturador aguas arriba. La contrata ha bloqueado solo el motor local. Trabajo del alumno.\n\nPensemos en un ejemplo. Voladura con topografía, carga con peatones, producción con mantenimiento, excavación con líneas y trabajo nocturno con señalización son combinaciones previsibles.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Lo previsible debe planificarse, no resolverse mediante improvisación radiofónica.","duration_seconds":132,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-079.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-079.jpg","explanation":"Objetivo\n\nReconocer interferencias frecuentes en exterior antes de que coincidan en campo.\n\nExplicación detallada\n\n5.4 Interferencias frecuentes. Voladura con mantenimiento, tráfico, perforación, drones o terceros. Carga y transporte con peatones, topografía, muestreo, vehículos ligeros o limpieza. Producción con mantenimiento en cintas, tolvas, trituradoras o cuadros. Excavación con líneas aéreas, tuberías, cables, edificaciones o propiedad. Vertido con equipos al pie, inestabilidad, agua o circulación por coronación. Trabajo en caliente con combustibles, polvo o materiales inflamables. Trabajo nocturno con iluminación, fatiga, relevo y menor apoyo externo. Caso 5A Mantenimiento y producción Situación. Una contrata cambia un rodamiento en un transportador. Producción quiere probar el triturador aguas arriba. La contrata ha bloqueado solo el motor local. Trabajo del alumno. Identifique control común y quién decide. Criterio de resolución. La prueba puede introducir energía o material. Se requiere consignación conjunta de equipos relacionados, custodia de bloqueos, comunicación y procedimiento de prueba. Ninguna parte modifica unilateralmente el aislamiento.\n\nLectura guiada de la diapositiva\n\nVoladura con mantenimiento, tráfico, perforación, drones o terceros. Carga y transporte con peatones, topografía, muestreo, vehículos ligeros o limpieza. Producción con mantenimiento en cintas, tolvas, trituradoras o cuadros. Excavación con líneas aéreas, tuberías, cables o edificaciones. Vertido con equipos al pie, agua o circulación por coronación. Trabajo en caliente con combustibles; trabajo nocturno con poca iluminación.\n\nAplicación práctica\n\nVoladura con topografía, carga con peatones, producción con mantenimiento, excavación con líneas y trabajo nocturno con señalización son combinaciones previsibles.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLo previsible debe planificarse, no resolverse mediante improvisación radiofónica.","key_points":["Reconocer interferencias frecuentes en exterior antes de que coincidan en campo.","Lo previsible debe planificarse, no resolverse mediante improvisación radiofónica."],"stop_criterion":"Lo previsible debe planificarse, no resolverse mediante improvisación radiofónica.","source_pages":"Bloque 5 · interferencias"},{"slide_number":80,"block_number":5,"lesson_ordinal":9,"segment_position":8,"segment_id":"a07ce8c2-f6b0-5d27-85e2-b19e96fe87f9","slide_id":"eb897d51-afb3-5a9b-83ee-ee6e7776aff7","note_id":"7892a45a-eb49-5f0e-8118-cae0de579331","title":"COORDINACIÓN DE EMERGENCIAS","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es coordinar emergencias entre empresas con alarma, recuento, acceso y mando compatibles.\n\nMuchos accidentes aparecen entre tareas analizadas por separado. La coordinación controla el espacio, el tiempo, la energía, la información y la autoridad compartidos. Resultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar. Hay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nPensemos en un ejemplo. Todas las personas deben reconocer la alarma, conocer el punto de reunión y aparecer en el recuento. Los servicios externos necesitan coordenadas, acceso y guía.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Una emergencia revela inmediatamente si la coordinación era real o documental.","duration_seconds":129,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-080.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-080.jpg","explanation":"Objetivo\n\nCoordinar emergencias entre empresas con alarma, recuento, acceso y mando compatibles.\n\nExplicación detallada\n\nMuchos accidentes aparecen entre tareas analizadas por separado. La coordinación controla el espacio, el tiempo, la energía, la información y la autoridad compartidos.\n\nResultados de aprendizaje. Identificar interferencias entre empresas, equipos, fases y entorno. Aplicar la coordinación de forma operativa. Diseñar separaciones, permisos y comunicaciones verificables. Gestionar cambios y desacuerdos antes de iniciar o continuar.\n\nHay interferencia cuando una actividad modifica las condiciones de otra o comparte su trayectoria. Dos procedimientos correctos pueden ser incompatibles si un equipo bloquea una salida, una contrata cruza una voladura, mantenimiento energiza una línea que producción considera aislada o una carretera pública queda expuesta a polvo o proyecciones.\n\nLectura guiada de la diapositiva\n\nAlarma, evacuación, recuento, acceso y rescate deben ser compatibles entre empresas. Número interno y 112, ubicación y coordenadas, punto de acceso y guía. Alarma y canales alternativos; reunión y recuento. Riesgos que impiden el acceso; medios, primeros auxilios y rescate específico. Información de sustancias y energías; responsable designado.\n\nAplicación práctica\n\nTodas las personas deben reconocer la alarma, conocer el punto de reunión y aparecer en el recuento. Los servicios externos necesitan coordenadas, acceso y guía.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nUna emergencia revela inmediatamente si la coordinación era real o documental.","key_points":["Coordinar emergencias entre empresas con alarma, recuento, acceso y mando compatibles.","Una emergencia revela inmediatamente si la coordinación era real o documental."],"stop_criterion":"Una emergencia revela inmediatamente si la coordinación era real o documental.","source_pages":"Bloque 5 · interferencias"},{"slide_number":81,"block_number":5,"lesson_ordinal":9,"segment_position":9,"segment_id":"f3740480-cb96-5358-9d76-e9f30126eafe","slide_id":"92a1dea3-8c0b-5697-b4f6-8b472d220ebf","note_id":"a85c9ef4-7454-5b31-8e16-4bc941390e20","title":"ACTIVIDAD DEL ALUMNO · 15 MINUTOS","narration_text":"Llegamos a una actividad práctica de aproximadamente 15 minutos. El objetivo es plantear el caso de mantenimiento y producción en un transportador conectado.\n\nLa situación de trabajo es esta. CASO 5A. MANTENIMIENTO Y PRODUCCIÓN Una contrata cambia un rodamiento en un transportador. Producción quiere probar el triturador aguas arriba. La contrata ha bloqueado solo el motor local. Identificar el control común y quién decide Puesta en común después del trabajo del grupo. Consignación conjunta. Custodia de bloqueos. Comunicación. Procedimiento de prueba.\n\nPara orientar el análisis, considera este encuadre. La contrata ha bloqueado un motor, pero producción quiere probar el triturador aguas arriba. El alumno debe identificar alimentación de material, energía compartida y necesidad de consignación conjunta.\n\nTrabaja en este orden. Primero separa hechos de suposiciones. Después identifica la energía o condición peligrosa, su trayectoria y las personas expuestas. A continuación propone una medida inmediata para retirar la exposición y otra que corrija la causa. Termina indicando quién decide, qué debe comprobarse y qué condición permite reabrir. Evita respuestas genéricas como tener cuidado o señalizar sin explicar qué barrera controla el escenario.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nDetén ahora la reproducción y realiza la actividad. Conserva tu respuesta para compararla con la resolución posterior. La prueba no comienza hasta confirmar que todas las personas están fuera y todos los bloqueos se gestionan.","duration_seconds":127,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-081.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-081.jpg","explanation":"Objetivo\n\nPlantear el caso de mantenimiento y producción en un transportador conectado.\n\nExplicación detallada\n\n5.4 Interferencias frecuentes. Voladura con mantenimiento, tráfico, perforación, drones o terceros. Carga y transporte con peatones, topografía, muestreo, vehículos ligeros o limpieza. Producción con mantenimiento en cintas, tolvas, trituradoras o cuadros. Excavación con líneas aéreas, tuberías, cables, edificaciones o propiedad. Vertido con equipos al pie, inestabilidad, agua o circulación por coronación. Trabajo en caliente con combustibles, polvo o materiales inflamables. Trabajo nocturno con iluminación, fatiga, relevo y menor apoyo externo. Caso 5A Mantenimiento y producción Situación. Una contrata cambia un rodamiento en un transportador. Producción quiere probar el triturador aguas arriba. La contrata ha bloqueado solo el motor local. Trabajo del alumno. Identifique control común y quién decide. Criterio de resolución. La prueba puede introducir energía o material. Se requiere consignación conjunta de equipos relacionados, custodia de bloqueos, comunicación y procedimiento de prueba. Ninguna parte modifica unilateralmente el aislamiento.\n\nLectura guiada de la diapositiva\n\nCASO 5A. MANTENIMIENTO Y PRODUCCIÓN Una contrata cambia un rodamiento en un transportador. Producción quiere probar el triturador aguas arriba. La contrata ha bloqueado solo el motor local. Identificar el control común y quién decide Puesta en común después del trabajo del grupo. Consignación conjunta. Custodia de bloqueos. Comunicación. Procedimiento de prueba.\n\nAplicación práctica\n\nLa contrata ha bloqueado un motor, pero producción quiere probar el triturador aguas arriba. El alumno debe identificar alimentación de material, energía compartida y necesidad de consignación conjunta.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa prueba no comienza hasta confirmar que todas las personas están fuera y todos los bloqueos se gestionan.","key_points":["Plantear el caso de mantenimiento y producción en un transportador conectado.","La prueba no comienza hasta confirmar que todas las personas están fuera y todos los bloqueos se gestionan."],"stop_criterion":"La prueba no comienza hasta confirmar que todas las personas están fuera y todos los bloqueos se gestionan.","source_pages":"Bloque 5 · interferencias"},{"slide_number":82,"block_number":5,"lesson_ordinal":9,"segment_position":10,"segment_id":"ac678c18-b936-553c-a02d-e34ee7d55ac3","slide_id":"0bbef538-421c-5a3f-a027-052545603e2e","note_id":"94bbbd6e-362a-5a9b-a67f-cd3d190135ce","title":"BLOQUE 5. COMPROBACIÓN, RESOLUCIÓN Y RESPUESTAS","narration_text":"Vamos a revisar la resolución. Lo importante es comprobar que la decisión retira la exposición inmediata, trata la causa y define cómo se recupera una condición segura.\n\nLa respuesta propuesta se desarrolla así. Comprobación mediante tres escenarios. Uno: topografía entra en una zona de carga sin contacto positivo. Dos: mantenimiento bloquea solo el motor local de un transportador mientras producción quiere probar el equipo aguas arriba. Tres: dos empresas usan alarmas y puntos de reunión diferentes en el mismo sector. En el primer escenario se separan actividades y se confirma el acceso con el operador. En el segundo se establece consignación conjunta y procedimiento de prueba. En el tercero se unifican alarma, evacuación, recuento y mando. La coordinación eficaz controla interferencias; no se limita a intercambiar documentos.\n\n5.4 Interferencias frecuentes. Voladura con mantenimiento, tráfico, perforación, drones o terceros. Carga y transporte con peatones, topografía, muestreo, vehículos ligeros o limpieza. Producción con mantenimiento en cintas, tolvas, trituradoras o cuadros. Excavación con líneas aéreas, tuberías, cables, edificaciones o propiedad. Vertido con equipos al pie, inestabilidad, agua o circulación por coronación. Trabajo en caliente con combustibles, polvo o materiales inflamables. Trabajo nocturno con iluminación, fatiga, relevo y menor apoyo externo.\n\nEn una situación reconocible ocurriría lo siguiente. Escenario uno: topografía entra en una zona de carga. Escenario dos: mantenimiento bloquea solo el motor local. Escenario tres: dos empresas usan alarmas distintas en el mismo sector.\n\nDistingue siempre entre control inmediato y solución definitiva. El primero detiene la exposición; la segunda corrige el diseño, el método, el mantenimiento o la organización. No retires una restricción temporal hasta comprobar el resultado y obtener la autorización prevista. Compara ahora esta solución con la tuya: revisa responsable, criterio de parada, condición de reapertura y evidencia de eficacia. La coordinación eficaz modifica el trabajo y deja evidencia de los acuerdos.","duration_seconds":150,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-082.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-082.jpg","explanation":"Objetivo\n\nCompletar la comprobación del bloque con tres escenarios concretos y resolverlos.\n\nExplicación detallada\n\n5.4 Interferencias frecuentes. Voladura con mantenimiento, tráfico, perforación, drones o terceros. Carga y transporte con peatones, topografía, muestreo, vehículos ligeros o limpieza. Producción con mantenimiento en cintas, tolvas, trituradoras o cuadros. Excavación con líneas aéreas, tuberías, cables, edificaciones o propiedad. Vertido con equipos al pie, inestabilidad, agua o circulación por coronación. Trabajo en caliente con combustibles, polvo o materiales inflamables. Trabajo nocturno con iluminación, fatiga, relevo y menor apoyo externo. Caso 5A Mantenimiento y producción Situación. Una contrata cambia un rodamiento en un transportador. Producción quiere probar el triturador aguas arriba. La contrata ha bloqueado solo el motor local. Trabajo del alumno. Identifique control común y quién decide. Criterio de resolución. La prueba puede introducir energía o material. Se requiere consignación conjunta de equipos relacionados, custodia de bloqueos, comunicación y procedimiento de prueba. Ninguna parte modifica unilateralmente el aislamiento.\n\nLectura guiada de la diapositiva\n\nComprobación mediante tres escenarios. Uno: topografía entra en una zona de carga sin contacto positivo. Dos: mantenimiento bloquea solo el motor local de un transportador mientras producción quiere probar el equipo aguas arriba. Tres: dos empresas usan alarmas y puntos de reunión diferentes en el mismo sector. En el primer escenario se separan actividades y se confirma el acceso con el operador. En el segundo se establece consignación conjunta y procedimiento de prueba. En el tercero se unifican alarma, evacuación, recuento y mando. La coordinación eficaz controla interferencias; no se limita a intercambiar documentos.\n\nAplicación práctica\n\nEscenario uno: topografía entra en una zona de carga. Escenario dos: mantenimiento bloquea solo el motor local. Escenario tres: dos empresas usan alarmas distintas en el mismo sector.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa coordinación eficaz modifica el trabajo y deja evidencia de los acuerdos.","key_points":["Completar la comprobación del bloque con tres escenarios concretos y resolverlos.","La coordinación eficaz modifica el trabajo y deja evidencia de los acuerdos."],"stop_criterion":"La coordinación eficaz modifica el trabajo y deja evidencia de los acuerdos.","source_pages":"Bloque 5 · interferencias"},{"slide_number":83,"block_number":6,"lesson_ordinal":10,"segment_position":1,"segment_id":"b9ff68aa-85b7-572d-970f-e36c12814c8f","slide_id":"64798437-b434-5a22-95e9-fdfd756a5542","note_id":"0c7e95da-e1b0-5da9-8fef-b134e23d996b","title":"MARCO NORMATIVO POR NIVELES","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es ordenar el marco normativo por niveles y traducir referencias en obligaciones verificables.\n\nOrdenemos el mapa normativo. En el nivel minero aparecen la Ley de Minas, el Reglamento General de Normas Básicas de Seguridad Minera, las instrucciones técnicas del capítulo siete, la instrucción cero dos punto uno punto cero dos, la especificación técnica dos mil tres guión uno guión diez y la instrucción cero dos punto cero punto cero dos. El marco preventivo general lo forman la Ley treinta y uno de mil novecientos noventa y cinco y el Real Decreto treinta y nueve de mil novecientos noventa y siete. El Real Decreto mil trescientos ochenta y nueve de mil novecientos noventa y siete concreta las disposiciones mínimas para actividades extractivas. A partir de ahí se añaden las normas específicas de equipos, protección individual, coordinación, agentes, explosivos y electricidad. No se trata de memorizar una lista: se trata de saber qué norma consultar para cada decisión.\n\nPensemos en un ejemplo. Ante una decisión sobre una pista, el técnico puede necesitar normativa minera, proyecto, Documento sobre Seguridad y Salud, disposición interna, fabricante y evaluación preventiva.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Conocer la norma significa saber dónde encontrarla y cómo afecta al trabajo.","duration_seconds":136,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-083.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-083.jpg","explanation":"Objetivo\n\nOrdenar el marco normativo por niveles y traducir referencias en obligaciones verificables.\n\nExplicación detallada\n\nEl técnico necesita saber qué norma gobierna cada decisión y cómo se integran legislación minera y prevención laboral. Memorizar referencias no basta: hay que traducirlas a obligaciones, documentos y verificaciones.\n\nResultados de aprendizaje. Situar el curso dentro de la ITC 02.1.02 y ET 2003-1-10. Reconocer el marco minero, preventivo, de equipos, higiene y coordinación. Distinguir norma obligatoria, guía y buena práctica. Mantener una revisión normativa trazable.\n\nLectura guiada de la diapositiva\n\nCada decisión del técnico tiene una norma que la gobierna. Agrupe las referencias por nivel y tradúzcalas en obligaciones, documentos y verificaciones. NIVEL NORMAS PRINCIPALES APLICACIÓN Minería Ley de Minas; RGNBSM; ITC VII; Diseño, operación, organización, ITC 02.1.02; ET 2003-1-10; ITC formación, polvo y reglas específicas Prevención Ley 31/1995 y Real Decreto Principios, evaluación, planificación, 39/1997 formación y organización Extractivas Real Decreto 1389/1997 Disposiciones mínimas para minería por sondeos y explotaciones Equipos y equipo de protección individual Reales Decretos 1215/1997 y Adecuación, uso, comprobación y 773/1997 protección personal Coordinación Real Decreto 171/2004 Concurrencia, titular, principal y medios Agentes RD 665/1997, RD 286/2006 y RD Sílice y cancerígenos, ruido, 1311/2005 vibraciones y vigilancia Explosivos y RD 130/2017 y RD 614/2001 Habilitaciones, coordinación y riesgo electricidad eléctrico\n\nAplicación práctica\n\nAnte una decisión sobre una pista, el técnico puede necesitar normativa minera, proyecto, Documento sobre Seguridad y Salud, disposición interna, fabricante y evaluación preventiva.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nConocer la norma significa saber dónde encontrarla y cómo afecta al trabajo.","key_points":["Ordenar el marco normativo por niveles y traducir referencias en obligaciones verificables.","Conocer la norma significa saber dónde encontrarla y cómo afecta al trabajo."],"stop_criterion":"Conocer la norma significa saber dónde encontrarla y cómo afecta al trabajo.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":84,"block_number":6,"lesson_ordinal":10,"segment_position":2,"segment_id":"c971a2f3-490a-53bb-b481-8dcf4da16065","slide_id":"036f70e2-f17b-5dad-a449-a99af289869b","note_id":"db3a9f0a-f9f9-50df-bb07-9542afb12e7d","title":"LA ITC 02.1.02 Y LA ET 2003-1-10","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es situar el curso en la ITC 02.1.02 y la Especificación Técnica 2003-1-10.\n\nPara el grupo cinco punto dos, apartado a, la especificación técnica dos mil tres guión uno guión diez fija veinte horas de formación inicial. La distribución oficial es una hora para definir los trabajos; siete horas para técnicas preventivas y de protección; siete horas para equipos de trabajo, protección individual y medios auxiliares; dos horas para control y vigilancia del entorno; dos horas para interferencias con otras actividades; y una hora para normativa y legislación. Esta arquitectura es la que ordena el curso completo.\n\nPensemos en un ejemplo. El itinerario del grupo cinco punto dos, letra a, distribuye veinte horas en seis bloques. Esta trazabilidad permite demostrar que el programa cubre el contenido mínimo.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La presentación y el guion deben conservar la denominación y el reparto oficiales.","duration_seconds":120,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-084.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-084.jpg","explanation":"Objetivo\n\nSituar el curso en la ITC 02.1.02 y la Especificación Técnica 2003-1-10.\n\nExplicación detallada\n\nITC 02.1.02 regula formación preventiva para puestos mineros. Para el grupo 5.2.a, la ET 2003-1-10 fija veinte horas con el reparto de este manual. La ITC establece modalidad presencial y reciclaje mínimo de cinco horas; para técnicos titulados de exterior, la ET fija periodicidad máxima de cuatro años. La empresa registra y certifica conforme al sistema aplicable. Implicación para InmínerCampus. Materiales digitales, pruebas, audios y tutorías mejoran preparación y repaso, pero no deben presentarse como sustitución de la asistencia presencial exigida.\n\nLectura guiada de la diapositiva\n\nLa ITC 02.1.02 regula la formación preventiva para los puestos mineros. Para el grupo 5.2.a, la ET 2003-1-10 fija un curso inicial de veinte horas con este reparto: BLOQUE OFICIAL HORAS CAPÍTULO 1. Definición de los trabajos 1 Capítulo 1 2. Técnicas preventivas y de protección 7 Capítulo 2 3. Equipos de trabajo, equipo de protección individual y medios 7 Capítulo 3 4. Control y vigilancia del entorno 2 Capítulo 4 5. Interferencias con otras actividades 2 Capítulo 5 6. Normativa y legislación 1 Capítulo 6\n\nAplicación práctica\n\nEl itinerario del grupo cinco punto dos, letra a, distribuye veinte horas en seis bloques. Esta trazabilidad permite demostrar que el programa cubre el contenido mínimo.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa presentación y el guion deben conservar la denominación y el reparto oficiales.","key_points":["Situar el curso en la ITC 02.1.02 y la Especificación Técnica 2003-1-10.","La presentación y el guion deben conservar la denominación y el reparto oficiales."],"stop_criterion":"La presentación y el guion deben conservar la denominación y el reparto oficiales.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":85,"block_number":6,"lesson_ordinal":10,"segment_position":3,"segment_id":"56b80ad0-7dbf-5401-a185-84998769fe70","slide_id":"b4fea96c-2506-56d3-afda-e9277e76b4c0","note_id":"1b83ab2f-e047-5dff-be79-27a6899e84fe","title":"FORMACIÓN PRESENCIAL, RECICLAJE Y PERIODICIDAD","narration_text":"Aquí abordamos una situación cotidiana que puede tener consecuencias importantes. Nuestro objetivo es explicar presencialidad, reciclaje mínimo y periodicidad para técnicos titulados de exterior.\n\nHay tres datos que no deben confundirse. La formación regulada por la instrucción cero dos punto uno punto cero dos es presencial. El reciclaje tiene una duración mínima de cinco horas lectivas. Y, para los técnicos titulados de exterior del grupo cinco punto dos, apartado a, la periodicidad máxima establecida es de cuatro años. Por tanto, estos audios apoyan y enriquecen la sesión, pero no sustituyen la asistencia, las actividades dirigidas ni la comprobación del aprendizaje.\n\nPensemos en un ejemplo. La formación regulada es presencial; el reciclaje tiene al menos cinco horas y, para este grupo, una frecuencia máxima de cuatro años. Audios y plataforma apoyan la sesión, pero no la sustituyen.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: El diseño digital debe integrarse en una impartición presencial documentada.","duration_seconds":138,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-085.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-085.jpg","explanation":"Objetivo\n\nExplicar presencialidad, reciclaje mínimo y periodicidad para técnicos titulados de exterior.\n\nExplicación detallada\n\nITC 02.1.02 regula formación preventiva para puestos mineros. Para el grupo 5.2.a, la ET 2003-1-10 fija veinte horas con el reparto de este manual. La ITC establece modalidad presencial y reciclaje mínimo de cinco horas; para técnicos titulados de exterior, la ET fija periodicidad máxima de cuatro años. La empresa registra y certifica conforme al sistema aplicable. Implicación para InmínerCampus. Materiales digitales, pruebas, audios y tutorías mejoran preparación y repaso, pero no deben presentarse como sustitución de la asistencia presencial exigida.\n\nLectura guiada de la diapositiva\n\nLa formación reglada de la ITC 02.1.02 tiene requisitos que el técnico y la empresa deben cumplir: Modalidad: la ITC establece formación presencial. Reciclaje: mínimo de cinco horas. Periodicidad: máximo cuatro años para técnicos titulados de exterior, grupo 5.2.a. Registro: la empresa registra y certifica la formación según el sistema aplicable. Audios, diapositivas y pruebas no sustituyen la asistencia presencial. Son repaso y preparación.\n\nAplicación práctica\n\nLa formación regulada es presencial; el reciclaje tiene al menos cinco horas y, para este grupo, una frecuencia máxima de cuatro años. Audios y plataforma apoyan la sesión, pero no la sustituyen.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nEl diseño digital debe integrarse en una impartición presencial documentada.","key_points":["Explicar presencialidad, reciclaje mínimo y periodicidad para técnicos titulados de exterior.","El diseño digital debe integrarse en una impartición presencial documentada."],"stop_criterion":"El diseño digital debe integrarse en una impartición presencial documentada.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":86,"block_number":6,"lesson_ordinal":10,"segment_position":4,"segment_id":"a869ad2f-6481-5c9a-8882-36b4770d0895","slide_id":"cc5be446-b416-549b-b7cd-07ba29494e82","note_id":"31a96fef-4c57-5942-bc42-3c01318f9412","title":"REGLAMENTO MINERO E ITC APLICABLES","narration_text":"La clave de esta diapositiva está en pasar de la descripción a la comprobación. Nuestro objetivo es presentar el Reglamento General de Normas Básicas de Seguridad Minera y las ITC aplicables.\n\nEn el nivel específicamente minero, el Reglamento General de Normas Básicas de Seguridad Minera, aprobado por el Real Decreto ochocientos sesenta y tres de mil novecientos ochenta y cinco, proporciona el marco. Las instrucciones técnicas del capítulo siete desarrollan reglas para trabajos a cielo abierto; la instrucción cero dos punto cero punto cero dos aborda la protección frente al polvo; y la instrucción cero dos punto uno punto cero dos regula la formación preventiva. Antes de aplicar una cifra o una obligación hay que revisar el texto consolidado, el proyecto aprobado y las condiciones impuestas por la autoridad minera.\n\nPensemos en un ejemplo. La normativa minera se concreta en proyecto, geometría, organización, polvo y disposiciones internas. Una costumbre local no puede reducir una exigencia vigente.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Siempre se consulta el texto aplicable y las condiciones de la autoridad minera.","duration_seconds":119,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-086.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-086.jpg","explanation":"Objetivo\n\nPresentar el Reglamento General de Normas Básicas de Seguridad Minera y las ITC aplicables.\n\nExplicación detallada\n\nEl técnico necesita saber qué norma gobierna cada decisión y cómo se integran legislación minera y prevención laboral. Memorizar referencias no basta: hay que traducirlas a obligaciones, documentos y verificaciones.\n\nResultados de aprendizaje. Situar el curso dentro de la ITC 02.1.02 y ET 2003-1-10. Reconocer el marco minero, preventivo, de equipos, higiene y coordinación. Distinguir norma obligatoria, guía y buena práctica. Mantener una revisión normativa trazable.\n\nLectura guiada de la diapositiva\n\nEl nivel minero fija reglas de diseño, operación y organización que deben comprobarse siempre contra el proyecto aprobado. Reglamento General de Normas Básicas de Seguridad Minera (RGNBSM). ITC del capítulo VII: trabajos a cielo abierto, con distancias y bermas. ITC 02.0.02: protección frente al polvo. Ley de Minas y la ITC 02.1.02 de formación. Cuando la ITC fija un límite, ese límite prevalece sobre la costumbre de la explotación.\n\nAplicación práctica\n\nLa normativa minera se concreta en proyecto, geometría, organización, polvo y disposiciones internas. Una costumbre local no puede reducir una exigencia vigente.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nSiempre se consulta el texto aplicable y las condiciones de la autoridad minera.","key_points":["Presentar el Reglamento General de Normas Básicas de Seguridad Minera y las ITC aplicables.","Siempre se consulta el texto aplicable y las condiciones de la autoridad minera."],"stop_criterion":"Siempre se consulta el texto aplicable y las condiciones de la autoridad minera.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":87,"block_number":6,"lesson_ordinal":10,"segment_position":5,"segment_id":"135b4d04-a137-586b-9d76-90689371fe66","slide_id":"02a3c5d0-5807-5f90-ad97-3eb8bb2dfb67","note_id":"c5a3ac05-4e21-5817-8c72-3bfed44edde2","title":"LEY 31/1995 Y SU DESARROLLO","narration_text":"En una explotación exterior, este asunto rara vez aparece de forma aislada. Nuestro objetivo es explicar derechos, obligaciones y principios preventivos de la Ley 31 de 1995 y su desarrollo.\n\nEl técnico necesita saber qué norma gobierna cada decisión y cómo se integran legislación minera y prevención laboral. Memorizar referencias no basta: hay que traducirlas a obligaciones, documentos y verificaciones. Resultados de aprendizaje. Situar el curso dentro de la ITC 02.1.02 y ET 2003-1-10. Reconocer el marco minero, preventivo, de equipos, higiene y coordinación. Distinguir norma obligatoria, guía y buena práctica. Mantener una revisión normativa trazable.\n\nPensemos en un ejemplo. El trabajador tiene derecho a protección y formación y debe usar correctamente medios y comunicar peligros; la empresa evalúa, planifica e integra la prevención. El servicio preventivo asesora, pero no sustituye la gestión.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La prevención es una responsabilidad organizada y no una decisión aislada del técnico.","duration_seconds":148,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-087.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-087.jpg","explanation":"Objetivo\n\nExplicar derechos, obligaciones y principios preventivos de la Ley 31 de 1995 y su desarrollo.\n\nExplicación detallada\n\nEl técnico necesita saber qué norma gobierna cada decisión y cómo se integran legislación minera y prevención laboral. Memorizar referencias no basta: hay que traducirlas a obligaciones, documentos y verificaciones.\n\nResultados de aprendizaje. Situar el curso dentro de la ITC 02.1.02 y ET 2003-1-10. Reconocer el marco minero, preventivo, de equipos, higiene y coordinación. Distinguir norma obligatoria, guía y buena práctica. Mantener una revisión normativa trazable.\n\nLectura guiada de la diapositiva\n\nLa prevención de riesgos laborales es el marco general sobre el que se apoyan las normas mineras. Ley 31/1995: principios de la acción preventiva, evaluación, planificación, formación y organización. Real Decreto 39/1997: desarrollo de la organización de la prevención. Real Decreto 1389/1997: disposiciones mínimas para la minería por sondeos y explotaciones. La evaluación de riesgos y la planificación de la actividad son obligaciones de la empresa, no decisiones individuales del técnico.\n\nAplicación práctica\n\nEl trabajador tiene derecho a protección y formación y debe usar correctamente medios y comunicar peligros; la empresa evalúa, planifica e integra la prevención. El servicio preventivo asesora, pero no sustituye la gestión.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa prevención es una responsabilidad organizada y no una decisión aislada del técnico.","key_points":["Explicar derechos, obligaciones y principios preventivos de la Ley 31 de 1995 y su desarrollo.","La prevención es una responsabilidad organizada y no una decisión aislada del técnico."],"stop_criterion":"La prevención es una responsabilidad organizada y no una decisión aislada del técnico.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":88,"block_number":6,"lesson_ordinal":10,"segment_position":6,"segment_id":"2d1d58ed-0e48-543e-bf56-853f058d8709","slide_id":"55b56e0c-126d-540f-b1be-d7690d935e92","note_id":"0f41b74e-0cf0-58f1-8a56-cdd2a6ee3b49","title":"EQUIPOS DE TRABAJO, EPI Y COORDINACIÓN","narration_text":"Pensemos en cómo se aplicaría este criterio durante un turno real. Nuestro objetivo es relacionar las normas de equipos, EPI y coordinación con decisiones concretas.\n\nLa correspondencia operativa es directa. El Real Decreto mil doscientos quince de mil novecientos noventa y siete se aplica a la adecuación, utilización y comprobación de los equipos de trabajo. El Real Decreto setecientos setenta y tres de mil novecientos noventa y siete regula la selección, el uso y el mantenimiento de los equipos de protección individual. Y el Real Decreto ciento setenta y uno de dos mil cuatro desarrolla la coordinación de actividades empresariales cuando concurren empresas o trabajadores autónomos. Cada una cubre una capa diferente y ninguna sustituye a las otras.\n\nPensemos en un ejemplo. El Real Decreto 1215 gobierna adecuación y uso de equipos; el 773 regula EPI; el 171 organiza concurrencia empresarial. Una misma tarea puede activar los tres.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La norma se convierte en selección, comprobación, información y supervisión.","duration_seconds":118,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-088.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-088.jpg","explanation":"Objetivo\n\nRelacionar las normas de equipos, EPI y coordinación con decisiones concretas.\n\nExplicación detallada\n\nResultados de aprendizaje. Situar el curso dentro de la ITC 02.1.02 y ET 2003-1-10. Reconocer el marco minero, preventivo, de equipos, higiene y coordinación. Distinguir norma obligatoria, guía y buena práctica. Mantener una revisión normativa trazable.\n\nEl técnico necesita saber qué norma gobierna cada decisión y cómo se integran legislación minera y prevención laboral. Memorizar referencias no basta: hay que traducirlas a obligaciones, documentos y verificaciones.\n\nLectura guiada de la diapositiva\n\nTres normas regulan lo que el técnico maneja, protege y coordina en el puesto. Equipos de trabajo: RD 1215/1997 Adecuación del equipo, uso y comprobación periódica. equipo de protección individual: RD 773/1997 Protección personal: selección, uso y mantenimiento de los equipos de protección. Coordinación: RD 171/2004 Concurrencia de empresas: titular, principal y medios compartidos.\n\nAplicación práctica\n\nEl Real Decreto 1215 gobierna adecuación y uso de equipos; el 773 regula EPI; el 171 organiza concurrencia empresarial. Una misma tarea puede activar los tres.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa norma se convierte en selección, comprobación, información y supervisión.","key_points":["Relacionar las normas de equipos, EPI y coordinación con decisiones concretas.","La norma se convierte en selección, comprobación, información y supervisión."],"stop_criterion":"La norma se convierte en selección, comprobación, información y supervisión.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":89,"block_number":6,"lesson_ordinal":10,"segment_position":7,"segment_id":"5e7c2aa4-10c6-5211-99df-bde7e5f2d725","slide_id":"6a7a8a73-77f8-5015-a7f8-f5280db24f98","note_id":"59989444-0533-55ce-b517-eeef7aa0e8af","title":"POLVO, SÍLICE, RUIDO Y VIBRACIONES","narration_text":"Vamos a detenernos en una idea que condiciona muchas decisiones de campo. Nuestro objetivo es relacionar polvo, sílice, ruido y vibraciones con evaluación, medición y vigilancia de la salud.\n\nAsocia cada agente con su referencia. La exposición a agentes cancerígenos, incluida la sílice cristalina respirable generada en un procedimiento de trabajo, se encuadra en el Real Decreto seiscientos sesenta y cinco de mil novecientos noventa y siete. El ruido se regula por el Real Decreto doscientos ochenta y seis de dos mil seis. Las vibraciones mecánicas, por el Real Decreto mil trescientos once de dos mil cinco. Y la protección frente al polvo en la explotación minera se desarrolla además en la instrucción técnica complementaria cero dos punto cero punto cero dos. La medición, el control de la fuente y la vigilancia de la salud forman un sistema, no actuaciones aisladas.\n\nPensemos en un ejemplo. Cada agente tiene método, criterio y medidas específicas. No se intercambian límites ni se presume cumplimiento por ausencia de quejas.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La medición representa condiciones reales y conduce a una decisión preventiva.","duration_seconds":121,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-089.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-089.jpg","explanation":"Objetivo\n\nRelacionar polvo, sílice, ruido y vibraciones con evaluación, medición y vigilancia de la salud.\n\nExplicación detallada\n\nResultados de aprendizaje. Situar el curso dentro de la ITC 02.1.02 y ET 2003-1-10. Reconocer el marco minero, preventivo, de equipos, higiene y coordinación. Distinguir norma obligatoria, guía y buena práctica. Mantener una revisión normativa trazable.\n\nEl técnico necesita saber qué norma gobierna cada decisión y cómo se integran legislación minera y prevención laboral. Memorizar referencias no basta: hay que traducirlas a obligaciones, documentos y verificaciones.\n\nLectura guiada de la diapositiva\n\nLos agentes físicos y químicos se regulan con normas de exposición, medición y vigilancia. AGENTE NORMA QUÉ REGULA Sílice y cancerígenos RD 665/1997 Exposición, control y vigilancia Ruido RD 286/2006 Evaluación, protección y vigilancia Vibraciones RD 1311/2005 Evaluación, límites y vigilancia Polvo minero ITC 02.0.02 Protección frente al polvo en la explotación\n\nAplicación práctica\n\nCada agente tiene método, criterio y medidas específicas. No se intercambian límites ni se presume cumplimiento por ausencia de quejas.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa medición representa condiciones reales y conduce a una decisión preventiva.","key_points":["Relacionar polvo, sílice, ruido y vibraciones con evaluación, medición y vigilancia de la salud.","La medición representa condiciones reales y conduce a una decisión preventiva."],"stop_criterion":"La medición representa condiciones reales y conduce a una decisión preventiva.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":90,"block_number":6,"lesson_ordinal":10,"segment_position":8,"segment_id":"0c468617-07f1-5cef-9427-023d3f609a23","slide_id":"289524f6-c8e2-5e59-ba96-f0958b4afd9b","note_id":"50444039-b54b-59be-ba9d-7c87122b3cac","title":"EXPLOSIVOS Y ELECTRICIDAD: QUÉ NO HABILITA EL CURSO","narration_text":"Esta diapositiva propone mirar el trabajo con criterio técnico y no por costumbre. Nuestro objetivo es aclarar que el curso no habilita para explosivos ni para trabajos eléctricos reservados.\n\nEn explosivos, la referencia general es el Reglamento de Explosivos aprobado por el Real Decreto ciento treinta de dos mil diecisiete. En riesgo eléctrico, la referencia preventiva es el Real Decreto seiscientos catorce de dos mil uno. Este curso no habilita para actuar como artillero, manipular explosivos ni realizar trabajos eléctricos reservados a personal autorizado o cualificado. La función del técnico es reconocer la interferencia, mantener distancias y exclusiones, coordinar con las personas habilitadas y detener la tarea cuando no puede demostrarse una condición segura.\n\nPensemos en un ejemplo. El técnico puede coordinar exclusiones y verificar condiciones, pero artilleros y personal eléctrico deben poseer la habilitación o cualificación correspondiente.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nPara trasladarlo al puesto, comprueba tres cosas: qué condición debe existir antes de empezar, qué señal obliga a detenerse y qué evidencia permite cerrar la tarea. Asigna además una persona responsable de verificar el control. Así, el criterio deja de ser una recomendación general y se convierte en una decisión que puede observarse, comunicarse y corregirse durante el turno.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Formación preventiva general no amplía competencias legales específicas.","duration_seconds":139,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-090.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-090.jpg","explanation":"Objetivo\n\nAclarar que el curso no habilita para explosivos ni para trabajos eléctricos reservados.\n\nExplicación detallada\n\nResultados de aprendizaje. Situar el curso dentro de la ITC 02.1.02 y ET 2003-1-10. Reconocer el marco minero, preventivo, de equipos, higiene y coordinación. Distinguir norma obligatoria, guía y buena práctica. Mantener una revisión normativa trazable.\n\nEl técnico necesita saber qué norma gobierna cada decisión y cómo se integran legislación minera y prevención laboral. Memorizar referencias no basta: hay que traducirlas a obligaciones, documentos y verificaciones.\n\nLectura guiada de la diapositiva\n\nExplosivos: RD 130/2017 Las operaciones con explosivos corresponden al personal habilitado en el marco del Reglamento de Explosivos. Electricidad: RD 614/2001 Riesgo eléctrico en líneas, proximidades y equipos energizados. Qué no habilita el curso Ser artillero ni manipular explosivos. Realizar trabajos eléctricos sin la cualificación exigida. El técnico coordina, delimita interferencias y verifica condiciones.\n\nAplicación práctica\n\nEl técnico puede coordinar exclusiones y verificar condiciones, pero artilleros y personal eléctrico deben poseer la habilitación o cualificación correspondiente.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nFormación preventiva general no amplía competencias legales específicas.","key_points":["Aclarar que el curso no habilita para explosivos ni para trabajos eléctricos reservados.","Formación preventiva general no amplía competencias legales específicas."],"stop_criterion":"Formación preventiva general no amplía competencias legales específicas.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":91,"block_number":6,"lesson_ordinal":10,"segment_position":9,"segment_id":"07b43318-3976-5659-96bf-40241dca6b07","slide_id":"72bf9601-e87b-5737-89e5-ead8baef5dd5","note_id":"731c6ff8-6280-5ffc-9b36-cb79cef69123","title":"NORMA, GUÍA, NTP, FABRICANTE Y REGLA INTERNA","narration_text":"El contenido que aparece en pantalla debe convertirse en una forma concreta de decidir. Nuestro objetivo es distinguir norma jurídica, guía, nota técnica, fabricante, proyecto e instrucción interna.\n\nCuando varias fuentes regulan una misma tarea, no debe aplicarse una jerarquía simplificada como si una referencia anulara automáticamente a las demás. Se cumplen la legislación vigente y las condiciones de la autoridad minera; el proyecto, el Documento sobre Seguridad y Salud y las disposiciones internas concretan cómo se trabaja en ese centro; y el manual del fabricante fija límites esenciales del equipo. Ningún documento interno puede reducir una exigencia legal ni autorizar un uso contrario al fabricante. Si aparece una contradicción, se conserva el estado seguro, se detiene la decisión y se eleva a la competencia técnica o jurídica correspondiente.\n\nPensemos en un ejemplo. Una guía ayuda a interpretar y una nota técnica propone buenas prácticas; la norma obliga en su ámbito; el fabricante fija límites del equipo; proyecto, Documento sobre Seguridad y Salud e instrucciones internas concretan el centro.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: Ninguna recomendación se presenta como obligación literal sin comprobar su fuente.","duration_seconds":128,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-091.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-091.jpg","explanation":"Objetivo\n\nDistinguir norma jurídica, guía, nota técnica, fabricante, proyecto e instrucción interna.\n\nExplicación detallada\n\nResultados de aprendizaje. Situar el curso dentro de la ITC 02.1.02 y ET 2003-1-10. Reconocer el marco minero, preventivo, de equipos, higiene y coordinación. Distinguir norma obligatoria, guía y buena práctica. Mantener una revisión normativa trazable.\n\n6.5 Comprobación de aprendizaje. Explique por qué el curso es presencial y qué papel tienen los audios. Localice en norma oficial la anchura de pista y compruebe el vehículo crítico. Diferencie obligación legal y recomendación de una NTP. Identifique quién actualiza el DSS cuando cambia proceso o evaluación.\n\nEl técnico necesita saber qué norma gobierna cada decisión y cómo se integran legislación minera y prevención laboral. Memorizar referencias no basta: hay que traducirlas a obligaciones, documentos y verificaciones.\n\nLectura guiada de la diapositiva\n\nTIPO VALOR USO CORRECTO Norma jurídica Obligatoria en su ámbito Comprobar texto consolidado, fecha y ámbito Guía oficial Criterio técnico; puede no ser No convertir recomendaciones vinculante en obligación literal NTP o documento Buena práctica no vinculante Adaptar a riesgo y tecnología salvo incorporación actuales Manual del Instrucción esencial del Integrar con la evaluación; no fabricante equipo anular protecciones Regla interna Obligatoria en el centro Mantener coherencia, formar y cuando se establece supervisar válidamente Regla de prevalencia: legislación vigente, condiciones de la autoridad minera, proyecto aprobado, Documento sobre Seguridad y Salud, disposiciones internas y fabricante.\n\nAplicación práctica\n\nUna guía ayuda a interpretar y una nota técnica propone buenas prácticas; la norma obliga en su ámbito; el fabricante fija límites del equipo; proyecto, Documento sobre Seguridad y Salud e instrucciones internas concretan el centro.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nNinguna recomendación se presenta como obligación literal sin comprobar su fuente.","key_points":["Distinguir norma jurídica, guía, nota técnica, fabricante, proyecto e instrucción interna.","Ninguna recomendación se presenta como obligación literal sin comprobar su fuente."],"stop_criterion":"Ninguna recomendación se presenta como obligación literal sin comprobar su fuente.","source_pages":"Bloque 6 · normativa y legislación"},{"slide_number":92,"block_number":6,"lesson_ordinal":10,"segment_position":10,"segment_id":"280a72ac-8d61-506e-9d6e-bfbccbb48b36","slide_id":"f2396830-2bd2-5275-88fd-743c4734ef8b","note_id":"e237835e-b2ac-5fe4-ad50-22082cbf4297","title":"REVISIÓN NORMATIVA EN CINCO PASOS","narration_text":"Antes de pasar a la siguiente operación, conviene entender bien este punto. Nuestro objetivo es cerrar con un método de revisión normativa y cultura de actualización.\n\n6.4 Revisión normativa 1. Mantener registro con enlace oficial, versión consolidada, responsable y fecha. 2. Vigilar BOE, autoridad autonómica, MITECO e INSST y valorar cambios. 3. Analizar impacto en proyecto, DSS, DIS, formación, equipos y mediciones. 4. Aprobar, comunicar, formar y conservar evidencia de implantación. 5. Retirar versiones obsoletas del uso sin perder archivo necesario. 6.5 Comprobación de aprendizaje. Explique por qué el curso es presencial y qué papel tienen los audios. Localice en norma oficial la anchura de pista y compruebe el vehículo crítico. Diferencie obligación legal y recomendación de una NTP. Identifique quién actualiza el DSS cuando cambia proceso o evaluación.\n\nPensemos en un ejemplo. Se registra la fuente oficial, se vigilan cambios, se analiza impacto, se aprueba y comunica la adaptación y se retiran copias obsoletas. Además, se revisan derechos y obligaciones, instrucciones de trabajo y disposiciones internas.\n\nLa actuación técnica debe seguir una secuencia sencilla: observar la condición real, retirar o evitar la exposición, aplicar la barrera más robusta disponible y comprobar que funciona. La medida necesita un responsable y un criterio visible de aceptación. Si cambia el terreno, el equipo, el personal o la tarea simultánea, vuelve a evaluar antes de continuar. Una instrucción como hacerlo con cuidado no define un control verificable.\n\nAntes de continuar, pregúntate qué observarías o medirías para demostrar que el criterio se cumple durante el turno. Puede ser una condición visible, una medición, una prueba funcional o un registro con responsable. Resume la diapositiva con esta idea: La normativa solo protege cuando la organización la mantiene vigente y la lleva al campo.","duration_seconds":135,"audio_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/audio/slide-092.mp3","image_storage_path":"4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/slides/slide-092.jpg","explanation":"Objetivo\n\nCerrar con un método de revisión normativa y cultura de actualización.\n\nExplicación detallada\n\n6.4 Revisión normativa 1. Mantener registro con enlace oficial, versión consolidada, responsable y fecha. 2. Vigilar BOE, autoridad autonómica, MITECO e INSST y valorar cambios. 3. Analizar impacto en proyecto, DSS, DIS, formación, equipos y mediciones. 4. Aprobar, comunicar, formar y conservar evidencia de implantación. 5. Retirar versiones obsoletas del uso sin perder archivo necesario.\n\n6.5 Comprobación de aprendizaje. Explique por qué el curso es presencial y qué papel tienen los audios. Localice en norma oficial la anchura de pista y compruebe el vehículo crítico. Diferencie obligación legal y recomendación de una NTP. Identifique quién actualiza el DSS cuando cambia proceso o evaluación.\n\nLectura guiada de la diapositiva\n\n1. Registrar cada norma con enlace oficial, versión, responsable y fecha. 2. Vigilar BOE, autoridad autonómica, MITECO e INSST. 3. Analizar el impacto en proyecto, Documento sobre Seguridad y Salud, disposición interna de seguridad, formación, equipos y mediciones. 4. Aprobar, comunicar, formar y conservar la evidencia. 5. Retirar las versiones obsoletas del uso, conservando el archivo.\n\nAplicación práctica\n\nSe registra la fuente oficial, se vigilan cambios, se analiza impacto, se aprueba y comunica la adaptación y se retiran copias obsoletas. Además, se revisan derechos y obligaciones, instrucciones de trabajo y disposiciones internas.\n\nComprobación antes de continuar\n\nIdentifica la condición real, la persona o equipo expuesto, la barrera aplicable, quién debe verificarla y qué evidencia permitirá autorizar la continuación.\n\nIdea clave\n\nLa normativa solo protege cuando la organización la mantiene vigente y la lleva al campo.","key_points":["Cerrar con un método de revisión normativa y cultura de actualización.","La normativa solo protege cuando la organización la mantiene vigente y la lleva al campo."],"stop_criterion":"La normativa solo protege cuando la organización la mantiene vigente y la lleva al campo.","source_pages":"Bloque 6 · normativa y legislación"}]$units$::jsonb) as unit(
  slide_number integer,
  block_number integer,
  lesson_ordinal integer,
  segment_position integer,
  segment_id uuid,
  slide_id uuid,
  note_id uuid,
  title text,
  narration_text text,
  duration_seconds integer,
  audio_storage_path text,
  image_storage_path text,
  explanation text,
  key_points jsonb,
  stop_criterion text,
  source_pages text
);

insert into public.lesson_audio_segments (
  id, lesson_id, position, lesson_code, manual_chapter, title,
  narration_text, audio_storage_path, duration_seconds, published
)
select u.segment_id, l.id, u.segment_position,
  concat(u.lesson_ordinal, '.', u.segment_position),
  concat('Bloque ', u.block_number, ' · diapositiva ', lpad(u.slide_number::text, 2, '0')),
  u.title, u.narration_text, u.audio_storage_path, u.duration_seconds, true
from _tex_units u
join _tex_lessons l on l.ordinal = u.lesson_ordinal
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  position = excluded.position,
  lesson_code = excluded.lesson_code,
  manual_chapter = excluded.manual_chapter,
  title = excluded.title,
  narration_text = excluded.narration_text,
  audio_storage_path = excluded.audio_storage_path,
  duration_seconds = excluded.duration_seconds,
  published = excluded.published,
  updated_at = now();

insert into public.lesson_segment_slides (
  id, segment_id, position, title, body, image_storage_path,
  source_label, source_page, alt_text
)
select u.slide_id, u.segment_id, 1, u.title,
  concat('Objetivo: ', (u.key_points->>0), E'

Idea clave: ', u.stop_criterion),
  u.image_storage_path,
  'Presentación InmínerCampus · Técnicos titulados de exterior',
  concat('Diapositiva ', u.slide_number),
  concat('Diapositiva ', u.slide_number, ': ', u.title)
from _tex_units u
on conflict (id) do update set
  title = excluded.title,
  body = excluded.body,
  image_storage_path = excluded.image_storage_path,
  source_label = excluded.source_label,
  source_page = excluded.source_page,
  alt_text = excluded.alt_text,
  updated_at = now();

insert into public.lesson_segment_notes (
  id, segment_id, summary, key_points, stop_criterion,
  source_label, source_pages, approved
)
select u.note_id, u.segment_id, u.explanation,
  array(select jsonb_array_elements_text(u.key_points)),
  u.stop_criterion,
  'Manual InmínerCampus · Técnicos titulados de exterior · edición 1.1',
  u.source_pages,
  true
from _tex_units u
on conflict (segment_id) do update set
  summary = excluded.summary,
  key_points = excluded.key_points,
  stop_criterion = excluded.stop_criterion,
  source_label = excluded.source_label,
  source_pages = excluded.source_pages,
  approved = excluded.approved,
  updated_at = now();

insert into public.course_materials (
  id, course_version_id, kind, title, description, storage_path,
  file_name, mime_type, size_bytes, page_count, downloadable, position,
  is_published
) values
('5e842080-85a0-5b92-a891-15a609cee3d5'::uuid, '4becab3e-b832-558c-9dec-b03f35848333'::uuid, 'manual', 'Manual del curso de técnicos titulados de exterior', 'Manual maestro InmínerCampus, edición 1.1.', '4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/materials/manual-tecnicos-exterior-20h-v1.1.pdf', 'manual-tecnicos-exterior-20h-v1.1.pdf', 'application/pdf', 1006355, 38, true, 1, false),
('2d2a2dae-9079-5626-a967-28c7aeb12ce1'::uuid, '4becab3e-b832-558c-9dec-b03f35848333'::uuid, 'presentation', 'Presentación del curso de técnicos titulados de exterior', 'Presentación completa con 92 diapositivas.', '4becab3e-b832-558c-9dec-b03f35848333/tecnicos-titulados-actividades-extractivas-exterior/v1-2026-10/materials/presentacion-tecnicos-exterior-20h-v1.1.pdf', 'presentacion-tecnicos-exterior-20h-v1.1.pdf', 'application/pdf', 8290161, 92, true, 2, false)
on conflict (id) do update set
  title = excluded.title,
  description = excluded.description,
  storage_path = excluded.storage_path,
  file_name = excluded.file_name,
  mime_type = excluded.mime_type,
  size_bytes = excluded.size_bytes,
  page_count = excluded.page_count,
  downloadable = excluded.downloadable,
  position = excluded.position,
  is_published = excluded.is_published,
  updated_at = now();

do $$
declare
  modules_count integer;
  lessons_count integer;
  segments_count integer;
  slides_count integer;
  notes_count integer;
begin
  select count(*) into modules_count from public.course_modules
    where course_version_id = '4becab3e-b832-558c-9dec-b03f35848333'::uuid;
  select count(*) into lessons_count from public.lessons l
    join public.course_modules m on m.id = l.module_id
    where m.course_version_id = '4becab3e-b832-558c-9dec-b03f35848333'::uuid;
  select count(*) into segments_count from public.lesson_audio_segments s
    join public.lessons l on l.id = s.lesson_id
    join public.course_modules m on m.id = l.module_id
    where m.course_version_id = '4becab3e-b832-558c-9dec-b03f35848333'::uuid;
  select count(*) into slides_count from public.lesson_segment_slides p
    join public.lesson_audio_segments s on s.id = p.segment_id
    join public.lessons l on l.id = s.lesson_id
    join public.course_modules m on m.id = l.module_id
    where m.course_version_id = '4becab3e-b832-558c-9dec-b03f35848333'::uuid;
  select count(*) into notes_count from public.lesson_segment_notes n
    join public.lesson_audio_segments s on s.id = n.segment_id
    join public.lessons l on l.id = s.lesson_id
    join public.course_modules m on m.id = l.module_id
    where m.course_version_id = '4becab3e-b832-558c-9dec-b03f35848333'::uuid;
  if modules_count <> 7 or lessons_count <> 10 or segments_count <> 92
     or slides_count <> 92 or notes_count <> 92 then
    raise exception 'Paquete incompleto: módulos %, lecciones %, audios %, diapositivas %, explicaciones %',
      modules_count, lessons_count, segments_count, slides_count, notes_count;
  end if;
end $$;

commit;
